pub fn build_gateway_formal_backend_hermetic_execution_descriptor(
    descriptor_id: impl Into<String>,
    invariant_property: GatewayFormalBackendHermeticInvariantProperty,
    toolchain_lock_digest: Hash,
    input_manifest_digest: Hash,
    output_root_label: impl Into<String>,
) -> GatewayFormalBackendHermeticExecutionDescriptor {
    let output_root_label = output_root_label.into();
    GatewayFormalBackendHermeticExecutionDescriptor {
        schema_version: GATEWAY_FORMAL_BACKEND_HERMETIC_EXECUTION_DESCRIPTOR_SCHEMA_VERSION
            .to_owned(),
        descriptor_id: descriptor_id.into(),
        state_slice: GATEWAY_FORMAL_BACKEND_HERMETIC_EXECUTION_DESCRIPTOR_STATE_SLICE.to_owned(),
        lane: GatewayFormalBackendHermeticExecutionLane::LocalSmtTinyGatewayInvariant,
        backend_kind: GatewayFormalBackendKind::Smt,
        command_kind: GatewayFormalBackendHermeticCommandKind::DirectProcessNoShell,
        invariant_property,
        tool_name: "local-smt-tiny-gateway-invariant".to_owned(),
        tool_version: "policy-fixed-no-spawn".to_owned(),
        toolchain_lock_digest,
        executable_path_label: "tools/formal/local-smt-tiny-gateway-invariant".to_owned(),
        argv_template: vec![
            "local-smt-tiny-gateway-invariant".to_owned(),
            "--input-manifest-digest".to_owned(),
            hash_hex(input_manifest_digest),
            "--output-root".to_owned(),
            output_root_label.clone(),
        ],
        input_manifest_digest,
        output_root_label,
        timeout_millis: 30_000,
        max_stdout_bytes: 8_192,
        max_stderr_bytes: 8_192,
        inherit_environment: false,
        allowed_environment_variables: BTreeSet::new(),
        environment_variables: BTreeMap::new(),
        no_stdin: true,
        no_shell: true,
        no_network: true,
        output_root_ignored: true,
        no_spawn: true,
        backend_executed: false,
        proof_artifact_created: false,
        checker_transcript_created: false,
        raw_stdout_retained: false,
        raw_stderr_retained: false,
        raw_solver_trace_retained: false,
        creates_accepted_evidence: false,
        creates_level2_evidence: false,
        populates_score_axes: false,
        grants_authority: false,
        semantic_correctness_claimed: false,
        production_readiness_claimed: false,
        sota_claimed: false,
        breakthrough_claimed: false,
        full_security_claimed: false,
        claim_boundary: gateway_formal_backend_hermetic_execution_descriptor_claim_boundary(),
        claim_text: Vec::new(),
        nonclaims: gateway_formal_backend_hermetic_execution_descriptor_required_nonclaims(),
    }
}

pub fn validate_gateway_formal_backend_hermetic_execution_descriptor(
    descriptor: &GatewayFormalBackendHermeticExecutionDescriptor,
) -> GatewayFormalBackendHermeticExecutionDescriptorValidation {
    let mut issues = Vec::new();
    if descriptor.schema_version
        != GATEWAY_FORMAL_BACKEND_HERMETIC_EXECUTION_DESCRIPTOR_SCHEMA_VERSION
    {
        issues.push(GatewayFormalBackendHermeticExecutionDescriptorIssue::InvalidSchemaVersion);
    }
    if descriptor.descriptor_id.trim().is_empty()
        || !is_safe_relative_path(&descriptor.descriptor_id)
        || descriptor.descriptor_id.contains(['/', '\\'])
    {
        issues.push(GatewayFormalBackendHermeticExecutionDescriptorIssue::InvalidDescriptorId);
    }
    if descriptor.state_slice != GATEWAY_FORMAL_BACKEND_HERMETIC_EXECUTION_DESCRIPTOR_STATE_SLICE {
        issues.push(GatewayFormalBackendHermeticExecutionDescriptorIssue::StateSliceMismatch);
    }
    if descriptor.backend_kind != GatewayFormalBackendKind::Smt {
        issues.push(GatewayFormalBackendHermeticExecutionDescriptorIssue::BackendKindMismatch);
    }
    if descriptor.command_kind != GatewayFormalBackendHermeticCommandKind::DirectProcessNoShell {
        issues.push(GatewayFormalBackendHermeticExecutionDescriptorIssue::UnsupportedCommandKind);
    }
    if descriptor.tool_name.trim().is_empty() {
        issues.push(GatewayFormalBackendHermeticExecutionDescriptorIssue::EmptyToolName);
    }
    if descriptor.tool_version.trim().is_empty() {
        issues.push(GatewayFormalBackendHermeticExecutionDescriptorIssue::EmptyToolVersion);
    }
    if descriptor.toolchain_lock_digest == Hash([0; 32]) {
        issues.push(
            GatewayFormalBackendHermeticExecutionDescriptorIssue::ToolchainLockDigestMismatch,
        );
    }
    if !is_safe_relative_path(&descriptor.executable_path_label)
        || path_label_is_protected(&descriptor.executable_path_label)
        || has_shell_metacharacters(&descriptor.executable_path_label)
    {
        issues
            .push(GatewayFormalBackendHermeticExecutionDescriptorIssue::InvalidExecutablePathLabel);
    }
    if descriptor.argv_template.is_empty() {
        issues.push(GatewayFormalBackendHermeticExecutionDescriptorIssue::EmptyArgvTemplate);
    }
    for arg in &descriptor.argv_template {
        if arg.trim().is_empty() || arg.contains('\0') {
            issues.push(
                GatewayFormalBackendHermeticExecutionDescriptorIssue::InvalidArgvFragment(
                    arg.clone(),
                ),
            );
        }
        if has_shell_metacharacters(arg) {
            issues.push(
                GatewayFormalBackendHermeticExecutionDescriptorIssue::ShellMetacharacterFragment(
                    arg.clone(),
                ),
            );
        }
        if looks_like_credential_value(arg) {
            issues.push(
                GatewayFormalBackendHermeticExecutionDescriptorIssue::CredentialLookingCommandValue(
                    arg.clone(),
                ),
            );
        }
    }
    if descriptor.input_manifest_digest == Hash([0; 32]) {
        issues.push(
            GatewayFormalBackendHermeticExecutionDescriptorIssue::InputManifestDigestMismatch,
        );
    }
    if descriptor.output_root_label.trim().is_empty()
        || !is_safe_relative_path(&descriptor.output_root_label)
        || path_label_is_protected(&descriptor.output_root_label)
        || has_shell_metacharacters(&descriptor.output_root_label)
    {
        issues.push(GatewayFormalBackendHermeticExecutionDescriptorIssue::InvalidOutputRootLabel);
    }
    if descriptor.timeout_millis == 0 || descriptor.timeout_millis > 60_000 {
        issues.push(GatewayFormalBackendHermeticExecutionDescriptorIssue::InvalidTimeout);
    }
    if descriptor.max_stdout_bytes == 0 || descriptor.max_stdout_bytes > 65_536 {
        issues.push(GatewayFormalBackendHermeticExecutionDescriptorIssue::InvalidStdoutLimit);
    }
    if descriptor.max_stderr_bytes == 0 || descriptor.max_stderr_bytes > 65_536 {
        issues.push(GatewayFormalBackendHermeticExecutionDescriptorIssue::InvalidStderrLimit);
    }
    if descriptor.inherit_environment {
        issues.push(GatewayFormalBackendHermeticExecutionDescriptorIssue::InheritedEnvironment);
    }
    for name in &descriptor.allowed_environment_variables {
        if !is_safe_environment_variable_name(name) {
            issues.push(
                GatewayFormalBackendHermeticExecutionDescriptorIssue::InvalidEnvironmentVariableName(
                    name.clone(),
                ),
            );
        }
    }
    for (name, value) in &descriptor.environment_variables {
        if !is_safe_environment_variable_name(name) {
            issues.push(
                GatewayFormalBackendHermeticExecutionDescriptorIssue::InvalidEnvironmentVariableName(
                    name.clone(),
                ),
            );
        }
        if !descriptor.allowed_environment_variables.contains(name) {
            issues.push(
                GatewayFormalBackendHermeticExecutionDescriptorIssue::EnvironmentVariableNotAllowed(
                    name.clone(),
                ),
            );
        }
        if looks_like_credential_name(name) || looks_like_credential_value(value) {
            issues.push(
                GatewayFormalBackendHermeticExecutionDescriptorIssue::CredentialLookingEnvironmentValue(
                    name.clone(),
                ),
            );
        }
    }
    if !descriptor.no_stdin {
        issues.push(GatewayFormalBackendHermeticExecutionDescriptorIssue::StdinEnabled);
    }
    if !descriptor.no_shell {
        issues.push(GatewayFormalBackendHermeticExecutionDescriptorIssue::ShellEnabled);
    }
    if !descriptor.no_network {
        issues.push(GatewayFormalBackendHermeticExecutionDescriptorIssue::NetworkEnabled);
    }
    if !descriptor.output_root_ignored {
        issues.push(GatewayFormalBackendHermeticExecutionDescriptorIssue::OutputRootNotIgnored);
    }
    if !descriptor.no_spawn {
        issues.push(GatewayFormalBackendHermeticExecutionDescriptorIssue::ProcessSpawnAllowed);
    }
    if descriptor.backend_executed {
        issues.push(GatewayFormalBackendHermeticExecutionDescriptorIssue::BackendExecuted);
    }
    if descriptor.proof_artifact_created {
        issues.push(GatewayFormalBackendHermeticExecutionDescriptorIssue::ProofArtifactCreated);
    }
    if descriptor.checker_transcript_created {
        issues.push(GatewayFormalBackendHermeticExecutionDescriptorIssue::CheckerTranscriptCreated);
    }
    if descriptor.raw_stdout_retained {
        issues.push(GatewayFormalBackendHermeticExecutionDescriptorIssue::RawStdoutRetained);
    }
    if descriptor.raw_stderr_retained {
        issues.push(GatewayFormalBackendHermeticExecutionDescriptorIssue::RawStderrRetained);
    }
    if descriptor.raw_solver_trace_retained {
        issues.push(GatewayFormalBackendHermeticExecutionDescriptorIssue::RawSolverTraceRetained);
    }
    if descriptor.creates_accepted_evidence {
        issues.push(GatewayFormalBackendHermeticExecutionDescriptorIssue::AcceptedEvidenceCreated);
    }
    if descriptor.creates_level2_evidence {
        issues.push(GatewayFormalBackendHermeticExecutionDescriptorIssue::Level2EvidenceCreated);
    }
    if descriptor.populates_score_axes {
        issues.push(GatewayFormalBackendHermeticExecutionDescriptorIssue::ScoreAxesPopulated);
    }
    if descriptor.grants_authority {
        issues.push(GatewayFormalBackendHermeticExecutionDescriptorIssue::AuthorityGranted);
    }
    if descriptor.semantic_correctness_claimed {
        issues
            .push(GatewayFormalBackendHermeticExecutionDescriptorIssue::SemanticCorrectnessClaimed);
    }
    if descriptor.production_readiness_claimed {
        issues
            .push(GatewayFormalBackendHermeticExecutionDescriptorIssue::ProductionReadinessClaimed);
    }
    if descriptor.sota_claimed {
        issues.push(GatewayFormalBackendHermeticExecutionDescriptorIssue::SotaClaimed);
    }
    if descriptor.breakthrough_claimed {
        issues.push(GatewayFormalBackendHermeticExecutionDescriptorIssue::BreakthroughClaimed);
    }
    if descriptor.full_security_claimed {
        issues.push(GatewayFormalBackendHermeticExecutionDescriptorIssue::FullSecurityClaimed);
    }
    if descriptor.claim_boundary
        != gateway_formal_backend_hermetic_execution_descriptor_claim_boundary()
    {
        issues.push(GatewayFormalBackendHermeticExecutionDescriptorIssue::ClaimBoundaryMismatch);
    }
    for forbidden in gateway_formal_evidence_forbidden_claim_fragments() {
        if descriptor
            .claim_text
            .iter()
            .any(|text| text.to_ascii_lowercase().contains(forbidden))
        {
            issues.push(
                GatewayFormalBackendHermeticExecutionDescriptorIssue::ForbiddenClaimText(
                    (*forbidden).to_owned(),
                ),
            );
        }
    }
    for required in gateway_formal_backend_hermetic_execution_descriptor_required_nonclaims() {
        if !descriptor.nonclaims.contains(&required) {
            issues.push(
                GatewayFormalBackendHermeticExecutionDescriptorIssue::MissingRequiredNonclaim(
                    required.0,
                ),
            );
        }
    }

    GatewayFormalBackendHermeticExecutionDescriptorValidation {
        valid: issues.is_empty(),
        issues,
    }
}

pub fn build_gateway_formal_backend_hermetic_execution_descriptor_report(
    descriptor: &GatewayFormalBackendHermeticExecutionDescriptor,
) -> GatewayFormalBackendHermeticExecutionDescriptorReport {
    GatewayFormalBackendHermeticExecutionDescriptorReport {
        schema_version: GATEWAY_FORMAL_BACKEND_HERMETIC_EXECUTION_DESCRIPTOR_REPORT_SCHEMA_VERSION
            .to_owned(),
        descriptor_id: descriptor.descriptor_id.clone(),
        descriptor_digest: descriptor.digest(),
        input_manifest_digest: descriptor.input_manifest_digest,
        toolchain_lock_digest: descriptor.toolchain_lock_digest,
        lane: descriptor.lane.clone(),
        backend_kind: descriptor.backend_kind.clone(),
        invariant_property: descriptor.invariant_property.clone(),
        validation: validate_gateway_formal_backend_hermetic_execution_descriptor(descriptor),
        claim_boundary: gateway_formal_backend_hermetic_execution_descriptor_claim_boundary(),
        no_spawn: descriptor.no_spawn,
        backend_executed: descriptor.backend_executed,
        proof_artifact_created: descriptor.proof_artifact_created,
        checker_transcript_created: descriptor.checker_transcript_created,
        creates_accepted_evidence: descriptor.creates_accepted_evidence,
        creates_level2_evidence: descriptor.creates_level2_evidence,
        populates_score_axes: descriptor.populates_score_axes,
        grants_authority: descriptor.grants_authority,
        nonclaims: descriptor.nonclaims.clone(),
    }
}

pub fn gateway_formal_backend_hermetic_descriptor_report_output_declared_files() -> Vec<String> {
    GATEWAY_FORMAL_BACKEND_HERMETIC_DESCRIPTOR_REPORT_DECLARED_FILES
        .iter()
        .map(|value| (*value).to_owned())
        .collect()
}

pub fn gateway_formal_backend_hermetic_descriptor_report_output_claim_boundary() -> String {
    GATEWAY_FORMAL_BACKEND_HERMETIC_DESCRIPTOR_REPORT_OUTPUT_CLAIM_BOUNDARY.to_owned()
}

pub fn materialize_gateway_formal_backend_hermetic_descriptor_report_output_bundle(
    output_root: &Path,
    descriptor: &GatewayFormalBackendHermeticExecutionDescriptor,
    report: &GatewayFormalBackendHermeticExecutionDescriptorReport,
    request: &GatewayFormalBackendHermeticDescriptorReportOutputRequest,
) -> Result<
    GatewayFormalBackendHermeticDescriptorReportOutputManifest,
    GatewayFormalBackendHermeticDescriptorReportOutputError,
> {
    validate_gateway_formal_backend_hermetic_descriptor_report_output_request(
        output_root,
        descriptor,
        report,
        request,
    )?;
    let staging_root = gateway_formal_backend_hermetic_descriptor_report_staging_root_for(
        output_root,
        &request.bundle_id,
    )?;
    if staging_root.exists() {
        remove_gateway_formal_backend_hermetic_descriptor_report_dir_all_checked(&staging_root)?;
    }
    fs::create_dir_all(staging_root.join("gateway-formal-backend-hermetic-descriptor-report"))
        .map_err(gateway_formal_backend_hermetic_descriptor_report_io_error)?;

    let files = build_gateway_formal_backend_hermetic_descriptor_report_bundle_files(
        descriptor, report, request,
    )?;
    for (logical_path, bytes) in &files {
        let target = staging_root.join(logical_path);
        if let Some(parent) = target.parent() {
            fs::create_dir_all(parent)
                .map_err(gateway_formal_backend_hermetic_descriptor_report_io_error)?;
        }
        fs::write(&target, bytes)
            .map_err(gateway_formal_backend_hermetic_descriptor_report_io_error)?;
        fs::write(
            sidecar_path(&target),
            hash_hex(hash_bytes(bytes)).into_bytes(),
        )
        .map_err(gateway_formal_backend_hermetic_descriptor_report_io_error)?;
    }

    if output_root.exists() {
        if !request.overwrite {
            remove_gateway_formal_backend_hermetic_descriptor_report_dir_all_checked(
                &staging_root,
            )?;
            return Err(
                GatewayFormalBackendHermeticDescriptorReportOutputError::OutputRootExistsWithoutOverwrite,
            );
        }
        remove_gateway_formal_backend_hermetic_descriptor_report_dir_all_checked(output_root)?;
    }
    fs::rename(&staging_root, output_root)
        .map_err(gateway_formal_backend_hermetic_descriptor_report_io_error)?;
    read_gateway_formal_backend_hermetic_descriptor_report_output_bundle(output_root)
}

pub fn read_gateway_formal_backend_hermetic_descriptor_report_output_bundle(
    output_root: &Path,
) -> Result<
    GatewayFormalBackendHermeticDescriptorReportOutputManifest,
    GatewayFormalBackendHermeticDescriptorReportOutputError,
> {
    let output_metadata = fs::symlink_metadata(output_root)
        .map_err(gateway_formal_backend_hermetic_descriptor_report_io_error)?;
    if output_metadata.file_type().is_symlink() {
        return Err(GatewayFormalBackendHermeticDescriptorReportOutputError::OutputRootIsSymlink);
    }
    if !output_metadata.is_dir() {
        return Err(GatewayFormalBackendHermeticDescriptorReportOutputError::OutputRootIsFile);
    }
    let bundle_dir = output_root.join("gateway-formal-backend-hermetic-descriptor-report");
    let bundle_metadata = fs::symlink_metadata(&bundle_dir)
        .map_err(gateway_formal_backend_hermetic_descriptor_report_io_error)?;
    if bundle_metadata.file_type().is_symlink() {
        return Err(
            GatewayFormalBackendHermeticDescriptorReportOutputError::BundleFileIsSymlink(
                "gateway-formal-backend-hermetic-descriptor-report".to_owned(),
            ),
        );
    }
    if !bundle_metadata.is_dir() {
        return Err(
            GatewayFormalBackendHermeticDescriptorReportOutputError::DeclaredFileTypeMismatch(
                "gateway-formal-backend-hermetic-descriptor-report".to_owned(),
            ),
        );
    }

    reject_undeclared_gateway_formal_backend_hermetic_descriptor_report_files(output_root)?;
    let mut file_bytes = BTreeMap::new();
    for logical_path in GATEWAY_FORMAL_BACKEND_HERMETIC_DESCRIPTOR_REPORT_DECLARED_FILES {
        let path = output_root.join(logical_path);
        let metadata = fs::symlink_metadata(&path)
            .map_err(gateway_formal_backend_hermetic_descriptor_report_io_error)?;
        if metadata.file_type().is_symlink() {
            return Err(
                GatewayFormalBackendHermeticDescriptorReportOutputError::BundleFileIsSymlink(
                    (*logical_path).to_owned(),
                ),
            );
        }
        if !metadata.is_file() {
            return Err(
                GatewayFormalBackendHermeticDescriptorReportOutputError::DeclaredFileTypeMismatch(
                    (*logical_path).to_owned(),
                ),
            );
        }
        let sidecar = sidecar_path(&path);
        let sidecar_metadata = fs::symlink_metadata(&sidecar)
            .map_err(gateway_formal_backend_hermetic_descriptor_report_io_error)?;
        if sidecar_metadata.file_type().is_symlink() {
            return Err(
                GatewayFormalBackendHermeticDescriptorReportOutputError::BundleFileIsSymlink(
                    format!("{logical_path}.sha256"),
                ),
            );
        }
        if !sidecar_metadata.is_file() {
            return Err(
                GatewayFormalBackendHermeticDescriptorReportOutputError::DeclaredFileTypeMismatch(
                    format!("{logical_path}.sha256"),
                ),
            );
        }
        let bytes =
            fs::read(&path).map_err(gateway_formal_backend_hermetic_descriptor_report_io_error)?;
        let expected = fs::read_to_string(sidecar)
            .map_err(gateway_formal_backend_hermetic_descriptor_report_io_error)?;
        if expected != hash_hex(hash_bytes(&bytes)) {
            return Err(
                GatewayFormalBackendHermeticDescriptorReportOutputError::DigestMismatch(
                    (*logical_path).to_owned(),
                ),
            );
        }
        file_bytes.insert((*logical_path).to_owned(), bytes);
    }

    validate_gateway_formal_backend_hermetic_descriptor_report_bundle_semantics(&file_bytes)
}

fn validate_gateway_formal_backend_hermetic_descriptor_report_output_request(
    output_root: &Path,
    descriptor: &GatewayFormalBackendHermeticExecutionDescriptor,
    report: &GatewayFormalBackendHermeticExecutionDescriptorReport,
    request: &GatewayFormalBackendHermeticDescriptorReportOutputRequest,
) -> Result<(), GatewayFormalBackendHermeticDescriptorReportOutputError> {
    if request.bundle_id.trim().is_empty()
        || !is_safe_relative_path(&request.bundle_id)
        || request.bundle_id.contains(['/', '\\'])
    {
        return Err(GatewayFormalBackendHermeticDescriptorReportOutputError::EmptyBundleId);
    }
    let validation = validate_gateway_formal_backend_hermetic_execution_descriptor(descriptor);
    if !validation.valid {
        return Err(
            GatewayFormalBackendHermeticDescriptorReportOutputError::InvalidDescriptor(
                validation.issues,
            ),
        );
    }
    if report != &build_gateway_formal_backend_hermetic_execution_descriptor_report(descriptor) {
        return Err(GatewayFormalBackendHermeticDescriptorReportOutputError::ReportMismatch);
    }
    validate_gateway_formal_backend_hermetic_descriptor_report_output_root(
        output_root,
        &request.protected_roots,
        request.overwrite,
    )
}

fn build_gateway_formal_backend_hermetic_descriptor_report_bundle_files(
    descriptor: &GatewayFormalBackendHermeticExecutionDescriptor,
    report: &GatewayFormalBackendHermeticExecutionDescriptorReport,
    request: &GatewayFormalBackendHermeticDescriptorReportOutputRequest,
) -> Result<BTreeMap<String, Vec<u8>>, GatewayFormalBackendHermeticDescriptorReportOutputError> {
    let validation = report.validation.clone();
    let command_contract =
        gateway_formal_backend_hermetic_descriptor_report_command_contract(descriptor);
    let validation_report =
        gateway_formal_backend_hermetic_descriptor_report_output_validation_report(report, request);
    let nonclaims =
        render_gateway_formal_backend_hermetic_descriptor_report_nonclaims(&descriptor.nonclaims);
    let mut files = BTreeMap::from([
        (
            "gateway-formal-backend-hermetic-descriptor-report/descriptor.json".to_owned(),
            serde_json::to_vec_pretty(descriptor)
                .map_err(gateway_formal_backend_hermetic_descriptor_report_serde_error)?,
        ),
        (
            "gateway-formal-backend-hermetic-descriptor-report/report.json".to_owned(),
            serde_json::to_vec_pretty(report)
                .map_err(gateway_formal_backend_hermetic_descriptor_report_serde_error)?,
        ),
        (
            "gateway-formal-backend-hermetic-descriptor-report/validation.json".to_owned(),
            serde_json::to_vec_pretty(&validation)
                .map_err(gateway_formal_backend_hermetic_descriptor_report_serde_error)?,
        ),
        (
            "gateway-formal-backend-hermetic-descriptor-report/command-contract.json".to_owned(),
            serde_json::to_vec_pretty(&command_contract)
                .map_err(gateway_formal_backend_hermetic_descriptor_report_serde_error)?,
        ),
        (
            "gateway-formal-backend-hermetic-descriptor-report/nonclaims.md".to_owned(),
            nonclaims.into_bytes(),
        ),
    ]);
    let manifest = gateway_formal_backend_hermetic_descriptor_report_output_manifest_for_files(
        descriptor,
        report,
        &validation,
        &command_contract,
        &validation_report,
        request,
        &files,
    );
    files.insert(
        "gateway-formal-backend-hermetic-descriptor-report/manifest.json".to_owned(),
        serde_json::to_vec_pretty(&manifest)
            .map_err(gateway_formal_backend_hermetic_descriptor_report_serde_error)?,
    );
    Ok(files)
}

fn gateway_formal_backend_hermetic_descriptor_report_output_manifest_for_files(
    descriptor: &GatewayFormalBackendHermeticExecutionDescriptor,
    report: &GatewayFormalBackendHermeticExecutionDescriptorReport,
    validation: &GatewayFormalBackendHermeticExecutionDescriptorValidation,
    command_contract: &GatewayFormalBackendHermeticDescriptorReportCommandContract,
    _validation_report: &GatewayFormalBackendHermeticDescriptorReportOutputValidationReport,
    request: &GatewayFormalBackendHermeticDescriptorReportOutputRequest,
    files: &BTreeMap<String, Vec<u8>>,
) -> GatewayFormalBackendHermeticDescriptorReportOutputManifest {
    let mut declared_file_digests = BTreeMap::new();
    for (logical_path, bytes) in files {
        declared_file_digests.insert(logical_path.clone(), hash_bytes(bytes));
    }
    GatewayFormalBackendHermeticDescriptorReportOutputManifest {
        schema_version: GATEWAY_FORMAL_BACKEND_HERMETIC_DESCRIPTOR_REPORT_OUTPUT_SCHEMA_VERSION
            .to_owned(),
        bundle_id: request.bundle_id.clone(),
        state_slice: GATEWAY_FORMAL_BACKEND_HERMETIC_DESCRIPTOR_REPORT_OUTPUT_STATE_SLICE
            .to_owned(),
        created_at_unix: request.created_at_unix,
        descriptor_digest: descriptor.digest(),
        report_digest: report.digest(),
        validation_digest: gateway_formal_backend_hermetic_descriptor_validation_digest(validation),
        command_contract_digest: command_contract.digest(),
        input_manifest_digest: descriptor.input_manifest_digest,
        toolchain_lock_digest: descriptor.toolchain_lock_digest,
        lane: descriptor.lane.clone(),
        backend_kind: descriptor.backend_kind.clone(),
        invariant_property: descriptor.invariant_property.clone(),
        command_kind: descriptor.command_kind.clone(),
        executable_path_label: descriptor.executable_path_label.clone(),
        argv_template_digest: gateway_formal_backend_hermetic_argv_template_digest(
            &descriptor.argv_template,
        ),
        output_root_label: descriptor.output_root_label.clone(),
        timeout_millis: descriptor.timeout_millis,
        max_stdout_bytes: descriptor.max_stdout_bytes,
        max_stderr_bytes: descriptor.max_stderr_bytes,
        nonclaims_digest: hash_bytes(
            files
                .get("gateway-formal-backend-hermetic-descriptor-report/nonclaims.md")
                .map(Vec::as_slice)
                .unwrap_or_default(),
        ),
        declared_files: gateway_formal_backend_hermetic_descriptor_report_output_declared_files(),
        declared_file_digests,
        claim_boundary: gateway_formal_backend_hermetic_descriptor_report_output_claim_boundary(),
        no_spawn: descriptor.no_spawn,
        backend_executed: descriptor.backend_executed,
        proof_artifact_created: descriptor.proof_artifact_created,
        checker_transcript_created: descriptor.checker_transcript_created,
        creates_accepted_evidence: descriptor.creates_accepted_evidence,
        creates_level2_evidence: descriptor.creates_level2_evidence,
        populates_score_axes: descriptor.populates_score_axes,
        semantic_correctness_claimed: descriptor.semantic_correctness_claimed,
        production_readiness_claimed: descriptor.production_readiness_claimed,
        sota_claimed: descriptor.sota_claimed,
        breakthrough_claimed: descriptor.breakthrough_claimed,
        full_security_claimed: descriptor.full_security_claimed,
        grants_authority: descriptor.grants_authority,
        nonclaims: descriptor.nonclaims.clone(),
    }
}

fn validate_gateway_formal_backend_hermetic_descriptor_report_bundle_semantics(
    files: &BTreeMap<String, Vec<u8>>,
) -> Result<
    GatewayFormalBackendHermeticDescriptorReportOutputManifest,
    GatewayFormalBackendHermeticDescriptorReportOutputError,
> {
    let manifest: GatewayFormalBackendHermeticDescriptorReportOutputManifest =
        parse_gateway_formal_backend_hermetic_descriptor_report_declared_json(
            files,
            "gateway-formal-backend-hermetic-descriptor-report/manifest.json",
        )?;
    let descriptor: GatewayFormalBackendHermeticExecutionDescriptor =
        parse_gateway_formal_backend_hermetic_descriptor_report_declared_json(
            files,
            "gateway-formal-backend-hermetic-descriptor-report/descriptor.json",
        )?;
    let report: GatewayFormalBackendHermeticExecutionDescriptorReport =
        parse_gateway_formal_backend_hermetic_descriptor_report_declared_json(
            files,
            "gateway-formal-backend-hermetic-descriptor-report/report.json",
        )?;
    let validation: GatewayFormalBackendHermeticExecutionDescriptorValidation =
        parse_gateway_formal_backend_hermetic_descriptor_report_declared_json(
            files,
            "gateway-formal-backend-hermetic-descriptor-report/validation.json",
        )?;
    let command_contract: GatewayFormalBackendHermeticDescriptorReportCommandContract =
        parse_gateway_formal_backend_hermetic_descriptor_report_declared_json(
            files,
            "gateway-formal-backend-hermetic-descriptor-report/command-contract.json",
        )?;

    let descriptor_validation =
        validate_gateway_formal_backend_hermetic_execution_descriptor(&descriptor);
    if !descriptor_validation.valid {
        return Err(
            GatewayFormalBackendHermeticDescriptorReportOutputError::InvalidDescriptor(
                descriptor_validation.issues,
            ),
        );
    }
    let expected_report =
        build_gateway_formal_backend_hermetic_execution_descriptor_report(&descriptor);
    if report != expected_report {
        return Err(GatewayFormalBackendHermeticDescriptorReportOutputError::ReportMismatch);
    }
    if validation != report.validation {
        return Err(GatewayFormalBackendHermeticDescriptorReportOutputError::ValidationMismatch);
    }
    if command_contract
        != gateway_formal_backend_hermetic_descriptor_report_command_contract(&descriptor)
    {
        return Err(
            GatewayFormalBackendHermeticDescriptorReportOutputError::CommandContractMismatch,
        );
    }
    if declared_gateway_formal_backend_hermetic_descriptor_report_bytes(
        files,
        "gateway-formal-backend-hermetic-descriptor-report/nonclaims.md",
    )? != render_gateway_formal_backend_hermetic_descriptor_report_nonclaims(
        &descriptor.nonclaims,
    )
    .as_bytes()
    {
        return Err(GatewayFormalBackendHermeticDescriptorReportOutputError::NonclaimMismatch);
    }
    let validation_report =
        gateway_formal_backend_hermetic_descriptor_report_output_validation_report_for_manifest(
            &report, &manifest,
        );
    validate_gateway_formal_backend_hermetic_descriptor_report_manifest_semantics(
        &manifest,
        &descriptor,
        &report,
        &validation_report,
        &command_contract,
        files,
    )?;
    Ok(manifest)
}

fn validate_gateway_formal_backend_hermetic_descriptor_report_manifest_semantics(
    manifest: &GatewayFormalBackendHermeticDescriptorReportOutputManifest,
    descriptor: &GatewayFormalBackendHermeticExecutionDescriptor,
    report: &GatewayFormalBackendHermeticExecutionDescriptorReport,
    _validation_report: &GatewayFormalBackendHermeticDescriptorReportOutputValidationReport,
    command_contract: &GatewayFormalBackendHermeticDescriptorReportCommandContract,
    files: &BTreeMap<String, Vec<u8>>,
) -> Result<(), GatewayFormalBackendHermeticDescriptorReportOutputError> {
    let expected_digest_paths: BTreeSet<String> =
        GATEWAY_FORMAL_BACKEND_HERMETIC_DESCRIPTOR_REPORT_DECLARED_FILES
            .iter()
            .filter(|path| {
                **path != "gateway-formal-backend-hermetic-descriptor-report/manifest.json"
            })
            .map(|path| (*path).to_owned())
            .collect();
    let actual_digest_paths: BTreeSet<String> =
        manifest.declared_file_digests.keys().cloned().collect();
    if manifest.schema_version
        != GATEWAY_FORMAL_BACKEND_HERMETIC_DESCRIPTOR_REPORT_OUTPUT_SCHEMA_VERSION
        || manifest.bundle_id.trim().is_empty()
        || !is_safe_relative_path(&manifest.bundle_id)
        || manifest.bundle_id.contains(['/', '\\'])
        || manifest.state_slice
            != GATEWAY_FORMAL_BACKEND_HERMETIC_DESCRIPTOR_REPORT_OUTPUT_STATE_SLICE
        || manifest.descriptor_digest != descriptor.digest()
        || manifest.report_digest != report.digest()
        || manifest.validation_digest
            != gateway_formal_backend_hermetic_descriptor_validation_digest(&report.validation)
        || manifest.command_contract_digest != command_contract.digest()
        || manifest.input_manifest_digest != descriptor.input_manifest_digest
        || manifest.toolchain_lock_digest != descriptor.toolchain_lock_digest
        || manifest.lane != descriptor.lane
        || manifest.backend_kind != descriptor.backend_kind
        || manifest.invariant_property != descriptor.invariant_property
        || manifest.command_kind != descriptor.command_kind
        || manifest.executable_path_label != descriptor.executable_path_label
        || manifest.argv_template_digest
            != gateway_formal_backend_hermetic_argv_template_digest(&descriptor.argv_template)
        || manifest.output_root_label != descriptor.output_root_label
        || manifest.timeout_millis != descriptor.timeout_millis
        || manifest.max_stdout_bytes != descriptor.max_stdout_bytes
        || manifest.max_stderr_bytes != descriptor.max_stderr_bytes
        || manifest.nonclaims_digest
            != hash_bytes(
                declared_gateway_formal_backend_hermetic_descriptor_report_bytes(
                    files,
                    "gateway-formal-backend-hermetic-descriptor-report/nonclaims.md",
                )?,
            )
        || manifest.declared_files
            != gateway_formal_backend_hermetic_descriptor_report_output_declared_files()
        || actual_digest_paths != expected_digest_paths
        || manifest.claim_boundary
            != gateway_formal_backend_hermetic_descriptor_report_output_claim_boundary()
        || !manifest.no_spawn
        || manifest.backend_executed
        || manifest.proof_artifact_created
        || manifest.checker_transcript_created
        || manifest.creates_accepted_evidence
        || manifest.creates_level2_evidence
        || manifest.populates_score_axes
        || manifest.semantic_correctness_claimed
        || manifest.production_readiness_claimed
        || manifest.sota_claimed
        || manifest.breakthrough_claimed
        || manifest.full_security_claimed
        || manifest.grants_authority
        || manifest.nonclaims != descriptor.nonclaims
    {
        return Err(
            GatewayFormalBackendHermeticDescriptorReportOutputError::ManifestSemanticMismatch,
        );
    }
    for (logical_path, expected_digest) in &manifest.declared_file_digests {
        let bytes =
            declared_gateway_formal_backend_hermetic_descriptor_report_bytes(files, logical_path)?;
        if *expected_digest != hash_bytes(bytes) {
            return Err(
                GatewayFormalBackendHermeticDescriptorReportOutputError::DigestMismatch(
                    logical_path.clone(),
                ),
            );
        }
    }
    Ok(())
}

fn gateway_formal_backend_hermetic_descriptor_report_command_contract(
    descriptor: &GatewayFormalBackendHermeticExecutionDescriptor,
) -> GatewayFormalBackendHermeticDescriptorReportCommandContract {
    GatewayFormalBackendHermeticDescriptorReportCommandContract {
        lane: descriptor.lane.clone(),
        backend_kind: descriptor.backend_kind.clone(),
        command_kind: descriptor.command_kind.clone(),
        invariant_property: descriptor.invariant_property.clone(),
        executable_path_label: descriptor.executable_path_label.clone(),
        argv_template: descriptor.argv_template.clone(),
        argv_template_digest: gateway_formal_backend_hermetic_argv_template_digest(
            &descriptor.argv_template,
        ),
        output_root_label: descriptor.output_root_label.clone(),
        timeout_millis: descriptor.timeout_millis,
        max_stdout_bytes: descriptor.max_stdout_bytes,
        max_stderr_bytes: descriptor.max_stderr_bytes,
        inherit_environment: descriptor.inherit_environment,
        no_stdin: descriptor.no_stdin,
        no_shell: descriptor.no_shell,
        no_network: descriptor.no_network,
        output_root_ignored: descriptor.output_root_ignored,
        no_spawn: descriptor.no_spawn,
    }
}

fn gateway_formal_backend_hermetic_argv_template_digest(argv_template: &[String]) -> Hash {
    hash_tagged(
        "hsai-agent-admission:gateway-formal-backend-hermetic-argv-template:v1",
        &argv_template.to_vec(),
    )
}

fn gateway_formal_backend_hermetic_descriptor_validation_digest(
    validation: &GatewayFormalBackendHermeticExecutionDescriptorValidation,
) -> Hash {
    hash_tagged(
        "hsai-agent-admission:gateway-formal-backend-hermetic-descriptor-validation:v1",
        validation,
    )
}

