fn render_gateway_formal_backend_hermetic_descriptor_report_nonclaims(
    nonclaims: &BTreeSet<NonClaimLabel>,
) -> String {
    let mut out = String::from("# Gateway Formal Backend Hermetic Descriptor Report Nonclaims\n\n");
    for nonclaim in nonclaims {
        out.push_str("- ");
        out.push_str(&nonclaim.0);
        out.push('\n');
    }
    out
}

fn declared_gateway_formal_backend_hermetic_descriptor_report_bytes<'a>(
    files: &'a BTreeMap<String, Vec<u8>>,
    logical_path: &str,
) -> Result<&'a [u8], GatewayFormalBackendHermeticDescriptorReportOutputError> {
    files.get(logical_path).map(Vec::as_slice).ok_or_else(|| {
        GatewayFormalBackendHermeticDescriptorReportOutputError::Io(format!(
            "declared file missing: {logical_path}"
        ))
    })
}

fn parse_gateway_formal_backend_hermetic_descriptor_report_declared_json<
    T: for<'de> Deserialize<'de>,
>(
    files: &BTreeMap<String, Vec<u8>>,
    logical_path: &str,
) -> Result<T, GatewayFormalBackendHermeticDescriptorReportOutputError> {
    let bytes =
        declared_gateway_formal_backend_hermetic_descriptor_report_bytes(files, logical_path)?;
    let text = std::str::from_utf8(bytes).map_err(|_| {
        GatewayFormalBackendHermeticDescriptorReportOutputError::MalformedDeclaredFile(
            logical_path.to_owned(),
        )
    })?;
    serde_json::from_str(text).map_err(|_| {
        GatewayFormalBackendHermeticDescriptorReportOutputError::MalformedDeclaredFile(
            logical_path.to_owned(),
        )
    })
}

fn reject_undeclared_gateway_formal_backend_hermetic_descriptor_report_files(
    output_root: &Path,
) -> Result<(), GatewayFormalBackendHermeticDescriptorReportOutputError> {
    let mut declared: BTreeSet<String> =
        GATEWAY_FORMAL_BACKEND_HERMETIC_DESCRIPTOR_REPORT_DECLARED_FILES
            .iter()
            .chain(GATEWAY_FORMAL_BACKEND_HERMETIC_DESCRIPTOR_REPORT_DECLARED_SIDECARS.iter())
            .map(|value| (*value).to_owned())
            .collect();
    let bundle_dir = output_root.join("gateway-formal-backend-hermetic-descriptor-report");
    for entry in fs::read_dir(&bundle_dir)
        .map_err(gateway_formal_backend_hermetic_descriptor_report_io_error)?
    {
        let entry = entry.map_err(gateway_formal_backend_hermetic_descriptor_report_io_error)?;
        let logical_path = entry
            .path()
            .strip_prefix(output_root)
            .map_err(|error| {
                GatewayFormalBackendHermeticDescriptorReportOutputError::Io(error.to_string())
            })?
            .to_string_lossy()
            .replace('\\', "/");
        if !declared.remove(&logical_path) {
            return Err(
                GatewayFormalBackendHermeticDescriptorReportOutputError::UndeclaredFile(
                    logical_path,
                ),
            );
        }
    }
    if let Some(missing) = declared.into_iter().next() {
        return Err(GatewayFormalBackendHermeticDescriptorReportOutputError::Io(
            format!("declared file missing: {missing}"),
        ));
    }
    Ok(())
}

fn validate_gateway_formal_backend_hermetic_descriptor_report_output_root(
    output_root: &Path,
    protected_roots: &[PathBuf],
    overwrite: bool,
) -> Result<(), GatewayFormalBackendHermeticDescriptorReportOutputError> {
    match validate_output_root(output_root, protected_roots, overwrite) {
        Ok(()) => Ok(()),
        Err(AdmissionJournalMaterializationError::EmptyOutputRoot) => {
            Err(GatewayFormalBackendHermeticDescriptorReportOutputError::EmptyOutputRoot)
        }
        Err(AdmissionJournalMaterializationError::ProtectedOutputRoot) => {
            Err(GatewayFormalBackendHermeticDescriptorReportOutputError::ProtectedOutputRoot)
        }
        Err(AdmissionJournalMaterializationError::OutputRootExistsWithoutOverwrite) => Err(
            GatewayFormalBackendHermeticDescriptorReportOutputError::OutputRootExistsWithoutOverwrite,
        ),
        Err(AdmissionJournalMaterializationError::OutputRootIsFile) => {
            Err(GatewayFormalBackendHermeticDescriptorReportOutputError::OutputRootIsFile)
        }
        Err(AdmissionJournalMaterializationError::OutputRootIsSymlink) => {
            Err(GatewayFormalBackendHermeticDescriptorReportOutputError::OutputRootIsSymlink)
        }
        Err(AdmissionJournalMaterializationError::Io(error)) => {
            Err(GatewayFormalBackendHermeticDescriptorReportOutputError::Io(error))
        }
        Err(other) => Err(GatewayFormalBackendHermeticDescriptorReportOutputError::Io(
            format!("{other:?}"),
        )),
    }
}

fn gateway_formal_backend_hermetic_descriptor_report_staging_root_for(
    output_root: &Path,
    bundle_id: &str,
) -> Result<PathBuf, GatewayFormalBackendHermeticDescriptorReportOutputError> {
    let parent = output_root
        .parent()
        .ok_or(GatewayFormalBackendHermeticDescriptorReportOutputError::EmptyOutputRoot)?;
    let name = output_root
        .file_name()
        .map(|value| value.to_string_lossy().into_owned())
        .ok_or(GatewayFormalBackendHermeticDescriptorReportOutputError::EmptyOutputRoot)?;
    Ok(parent.join(format!(".{name}.{bundle_id}.staging")))
}

fn remove_gateway_formal_backend_hermetic_descriptor_report_dir_all_checked(
    path: &Path,
) -> Result<(), GatewayFormalBackendHermeticDescriptorReportOutputError> {
    if !path.exists() {
        return Ok(());
    }
    if fs::symlink_metadata(path)
        .map_err(gateway_formal_backend_hermetic_descriptor_report_io_error)?
        .file_type()
        .is_symlink()
    {
        return Err(GatewayFormalBackendHermeticDescriptorReportOutputError::OutputRootIsSymlink);
    }
    fs::remove_dir_all(path).map_err(gateway_formal_backend_hermetic_descriptor_report_io_error)
}

fn gateway_formal_backend_hermetic_descriptor_report_io_error(
    error: io::Error,
) -> GatewayFormalBackendHermeticDescriptorReportOutputError {
    GatewayFormalBackendHermeticDescriptorReportOutputError::Io(error.to_string())
}

fn gateway_formal_backend_hermetic_descriptor_report_serde_error(
    error: serde_json::Error,
) -> GatewayFormalBackendHermeticDescriptorReportOutputError {
    GatewayFormalBackendHermeticDescriptorReportOutputError::Serialization(error.to_string())
}

pub fn gateway_formal_backend_hermetic_execution_result_quarantine_output_declared_files(
) -> Vec<String> {
    GATEWAY_FORMAL_BACKEND_HERMETIC_EXECUTION_RESULT_QUARANTINE_DECLARED_FILES
        .iter()
        .map(|value| (*value).to_owned())
        .collect()
}

pub fn gateway_formal_backend_hermetic_execution_result_quarantine_output_claim_boundary() -> String
{
    GATEWAY_FORMAL_BACKEND_HERMETIC_EXECUTION_RESULT_QUARANTINE_OUTPUT_CLAIM_BOUNDARY.to_owned()
}

pub fn materialize_gateway_formal_backend_hermetic_execution_result_quarantine_output_bundle(
    output_root: &Path,
    descriptor: &GatewayFormalBackendHermeticExecutionDescriptor,
    descriptor_report_manifest: &GatewayFormalBackendHermeticDescriptorReportOutputManifest,
    request: &GatewayFormalBackendHermeticExecutionResultQuarantineOutputRequest,
) -> Result<
    GatewayFormalBackendHermeticExecutionResultQuarantineOutputManifest,
    GatewayFormalBackendHermeticExecutionResultQuarantineOutputError,
> {
    validate_gateway_formal_backend_hermetic_execution_result_quarantine_output_request(
        output_root,
        descriptor,
        descriptor_report_manifest,
        request,
    )?;
    let staging_root =
        gateway_formal_backend_hermetic_execution_result_quarantine_staging_root_for(
            output_root,
            &request.bundle_id,
        )?;
    if staging_root.exists() {
        remove_gateway_formal_backend_hermetic_execution_result_quarantine_dir_all_checked(
            &staging_root,
        )?;
    }
    fs::create_dir_all(
        staging_root.join("gateway-formal-backend-hermetic-execution-result-quarantine"),
    )
    .map_err(gateway_formal_backend_hermetic_execution_result_quarantine_io_error)?;

    let files = build_gateway_formal_backend_hermetic_execution_result_quarantine_bundle_files(
        descriptor,
        descriptor_report_manifest,
        request,
    )?;
    for (logical_path, bytes) in &files {
        let target = staging_root.join(logical_path);
        if let Some(parent) = target.parent() {
            fs::create_dir_all(parent)
                .map_err(gateway_formal_backend_hermetic_execution_result_quarantine_io_error)?;
        }
        fs::write(&target, bytes)
            .map_err(gateway_formal_backend_hermetic_execution_result_quarantine_io_error)?;
        fs::write(
            sidecar_path(&target),
            hash_hex(hash_bytes(bytes)).into_bytes(),
        )
        .map_err(gateway_formal_backend_hermetic_execution_result_quarantine_io_error)?;
    }

    if output_root.exists() {
        if !request.overwrite {
            remove_gateway_formal_backend_hermetic_execution_result_quarantine_dir_all_checked(
                &staging_root,
            )?;
            return Err(
                GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::OutputRootExistsWithoutOverwrite,
            );
        }
        remove_gateway_formal_backend_hermetic_execution_result_quarantine_dir_all_checked(
            output_root,
        )?;
    }
    fs::rename(&staging_root, output_root)
        .map_err(gateway_formal_backend_hermetic_execution_result_quarantine_io_error)?;
    read_gateway_formal_backend_hermetic_execution_result_quarantine_output_bundle(output_root)
}

pub fn read_gateway_formal_backend_hermetic_execution_result_quarantine_output_bundle(
    output_root: &Path,
) -> Result<
    GatewayFormalBackendHermeticExecutionResultQuarantineOutputManifest,
    GatewayFormalBackendHermeticExecutionResultQuarantineOutputError,
> {
    let output_metadata = fs::symlink_metadata(output_root)
        .map_err(gateway_formal_backend_hermetic_execution_result_quarantine_io_error)?;
    if output_metadata.file_type().is_symlink() {
        return Err(
            GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::OutputRootIsSymlink,
        );
    }
    if !output_metadata.is_dir() {
        return Err(
            GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::OutputRootIsFile,
        );
    }
    let bundle_dir =
        output_root.join("gateway-formal-backend-hermetic-execution-result-quarantine");
    let bundle_metadata = fs::symlink_metadata(&bundle_dir)
        .map_err(gateway_formal_backend_hermetic_execution_result_quarantine_io_error)?;
    if bundle_metadata.file_type().is_symlink() {
        return Err(
            GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::BundleFileIsSymlink(
                "gateway-formal-backend-hermetic-execution-result-quarantine".to_owned(),
            ),
        );
    }
    if !bundle_metadata.is_dir() {
        return Err(
            GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::DeclaredFileTypeMismatch(
                "gateway-formal-backend-hermetic-execution-result-quarantine".to_owned(),
            ),
        );
    }

    reject_undeclared_gateway_formal_backend_hermetic_execution_result_quarantine_files(
        output_root,
    )?;
    let mut file_bytes = BTreeMap::new();
    for logical_path in GATEWAY_FORMAL_BACKEND_HERMETIC_EXECUTION_RESULT_QUARANTINE_DECLARED_FILES {
        let path = output_root.join(logical_path);
        let metadata = fs::symlink_metadata(&path)
            .map_err(gateway_formal_backend_hermetic_execution_result_quarantine_io_error)?;
        if metadata.file_type().is_symlink() {
            return Err(
                GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::BundleFileIsSymlink(
                    (*logical_path).to_owned(),
                ),
            );
        }
        if !metadata.is_file() {
            return Err(
                GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::DeclaredFileTypeMismatch(
                    (*logical_path).to_owned(),
                ),
            );
        }
        let sidecar = sidecar_path(&path);
        let sidecar_metadata = fs::symlink_metadata(&sidecar)
            .map_err(gateway_formal_backend_hermetic_execution_result_quarantine_io_error)?;
        if sidecar_metadata.file_type().is_symlink() {
            return Err(
                GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::BundleFileIsSymlink(
                    format!("{logical_path}.sha256"),
                ),
            );
        }
        if !sidecar_metadata.is_file() {
            return Err(
                GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::DeclaredFileTypeMismatch(
                    format!("{logical_path}.sha256"),
                ),
            );
        }
        let bytes = fs::read(&path)
            .map_err(gateway_formal_backend_hermetic_execution_result_quarantine_io_error)?;
        let expected = fs::read_to_string(sidecar)
            .map_err(gateway_formal_backend_hermetic_execution_result_quarantine_io_error)?;
        if expected != hash_hex(hash_bytes(&bytes)) {
            return Err(
                GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::DigestMismatch(
                    (*logical_path).to_owned(),
                ),
            );
        }
        file_bytes.insert((*logical_path).to_owned(), bytes);
    }

    validate_gateway_formal_backend_hermetic_execution_result_quarantine_bundle_semantics(
        &file_bytes,
    )
}

fn validate_gateway_formal_backend_hermetic_execution_result_quarantine_output_request(
    output_root: &Path,
    descriptor: &GatewayFormalBackendHermeticExecutionDescriptor,
    descriptor_report_manifest: &GatewayFormalBackendHermeticDescriptorReportOutputManifest,
    request: &GatewayFormalBackendHermeticExecutionResultQuarantineOutputRequest,
) -> Result<(), GatewayFormalBackendHermeticExecutionResultQuarantineOutputError> {
    if request.bundle_id.trim().is_empty()
        || !is_safe_relative_path(&request.bundle_id)
        || request.bundle_id.contains(['/', '\\'])
    {
        return Err(
            GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::EmptyBundleId,
        );
    }
    let validation = validate_gateway_formal_backend_hermetic_execution_descriptor(descriptor);
    if !validation.valid {
        return Err(
            GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::InvalidDescriptor(
                validation.issues,
            ),
        );
    }
    if !gateway_formal_backend_hermetic_execution_result_descriptor_report_manifest_matches(
        descriptor,
        descriptor_report_manifest,
    ) {
        return Err(
            GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::DescriptorReportManifestMismatch,
        );
    }
    validate_gateway_formal_backend_hermetic_execution_result_quarantine_output_root(
        output_root,
        &request.protected_roots,
        request.overwrite,
    )
}

fn build_gateway_formal_backend_hermetic_execution_result_quarantine_bundle_files(
    descriptor: &GatewayFormalBackendHermeticExecutionDescriptor,
    descriptor_report_manifest: &GatewayFormalBackendHermeticDescriptorReportOutputManifest,
    request: &GatewayFormalBackendHermeticExecutionResultQuarantineOutputRequest,
) -> Result<
    BTreeMap<String, Vec<u8>>,
    GatewayFormalBackendHermeticExecutionResultQuarantineOutputError,
> {
    let input_binding = gateway_formal_backend_hermetic_execution_result_input_binding(
        descriptor,
        descriptor_report_manifest,
    );
    let command_contract =
        gateway_formal_backend_hermetic_descriptor_report_command_contract(descriptor);
    let output_inventory = gateway_formal_backend_hermetic_execution_result_output_inventory();
    let stdout_summary = gateway_formal_backend_hermetic_execution_result_bounded_summary(
        "stdout",
        descriptor.max_stdout_bytes,
    );
    let stderr_summary = gateway_formal_backend_hermetic_execution_result_bounded_summary(
        "stderr",
        descriptor.max_stderr_bytes,
    );
    let redaction_report = gateway_formal_backend_hermetic_execution_result_redaction_report();
    let invariant_verdict =
        gateway_formal_backend_hermetic_execution_result_invariant_verdict(descriptor);
    let nonpromotion_report =
        gateway_formal_backend_hermetic_execution_result_nonpromotion_report();
    let execution_status = gateway_formal_backend_hermetic_execution_result_execution_status(
        descriptor,
        &command_contract,
        &input_binding,
        &output_inventory,
    );
    let validation_report =
        gateway_formal_backend_hermetic_execution_result_output_validation_report(request);
    let nonclaims = render_gateway_formal_backend_hermetic_execution_result_quarantine_nonclaims(
        &descriptor.nonclaims,
    );
    let mut files = BTreeMap::from([
        (
            "gateway-formal-backend-hermetic-execution-result-quarantine/execution-status.json"
                .to_owned(),
            serde_json::to_vec_pretty(&execution_status)
                .map_err(gateway_formal_backend_hermetic_execution_result_quarantine_serde_error)?,
        ),
        (
            "gateway-formal-backend-hermetic-execution-result-quarantine/input-binding.json"
                .to_owned(),
            serde_json::to_vec_pretty(&input_binding)
                .map_err(gateway_formal_backend_hermetic_execution_result_quarantine_serde_error)?,
        ),
        (
            "gateway-formal-backend-hermetic-execution-result-quarantine/command-contract.json"
                .to_owned(),
            serde_json::to_vec_pretty(&command_contract)
                .map_err(gateway_formal_backend_hermetic_execution_result_quarantine_serde_error)?,
        ),
        (
            "gateway-formal-backend-hermetic-execution-result-quarantine/stdout-summary.json"
                .to_owned(),
            serde_json::to_vec_pretty(&stdout_summary)
                .map_err(gateway_formal_backend_hermetic_execution_result_quarantine_serde_error)?,
        ),
        (
            "gateway-formal-backend-hermetic-execution-result-quarantine/stderr-summary.json"
                .to_owned(),
            serde_json::to_vec_pretty(&stderr_summary)
                .map_err(gateway_formal_backend_hermetic_execution_result_quarantine_serde_error)?,
        ),
        (
            "gateway-formal-backend-hermetic-execution-result-quarantine/redaction-report.json"
                .to_owned(),
            serde_json::to_vec_pretty(&redaction_report)
                .map_err(gateway_formal_backend_hermetic_execution_result_quarantine_serde_error)?,
        ),
        (
            "gateway-formal-backend-hermetic-execution-result-quarantine/output-inventory.json"
                .to_owned(),
            serde_json::to_vec_pretty(&output_inventory)
                .map_err(gateway_formal_backend_hermetic_execution_result_quarantine_serde_error)?,
        ),
        (
            "gateway-formal-backend-hermetic-execution-result-quarantine/invariant-verdict.json"
                .to_owned(),
            serde_json::to_vec_pretty(&invariant_verdict)
                .map_err(gateway_formal_backend_hermetic_execution_result_quarantine_serde_error)?,
        ),
        (
            "gateway-formal-backend-hermetic-execution-result-quarantine/nonpromotion-report.json"
                .to_owned(),
            serde_json::to_vec_pretty(&nonpromotion_report)
                .map_err(gateway_formal_backend_hermetic_execution_result_quarantine_serde_error)?,
        ),
        (
            "gateway-formal-backend-hermetic-execution-result-quarantine/validation.json"
                .to_owned(),
            serde_json::to_vec_pretty(&validation_report)
                .map_err(gateway_formal_backend_hermetic_execution_result_quarantine_serde_error)?,
        ),
        (
            "gateway-formal-backend-hermetic-execution-result-quarantine/nonclaims.md".to_owned(),
            nonclaims.into_bytes(),
        ),
    ]);
    let manifest =
        gateway_formal_backend_hermetic_execution_result_quarantine_output_manifest_for_files(
            descriptor,
            descriptor_report_manifest,
            &input_binding,
            &command_contract,
            &execution_status,
            &stdout_summary,
            &stderr_summary,
            &redaction_report,
            &output_inventory,
            &invariant_verdict,
            &nonpromotion_report,
            &validation_report,
            request,
            &files,
        );
    files.insert(
        "gateway-formal-backend-hermetic-execution-result-quarantine/manifest.json".to_owned(),
        serde_json::to_vec_pretty(&manifest)
            .map_err(gateway_formal_backend_hermetic_execution_result_quarantine_serde_error)?,
    );
    Ok(files)
}

#[allow(clippy::too_many_arguments)]
fn gateway_formal_backend_hermetic_execution_result_quarantine_output_manifest_for_files(
    descriptor: &GatewayFormalBackendHermeticExecutionDescriptor,
    descriptor_report_manifest: &GatewayFormalBackendHermeticDescriptorReportOutputManifest,
    input_binding: &GatewayFormalBackendHermeticExecutionResultInputBinding,
    command_contract: &GatewayFormalBackendHermeticDescriptorReportCommandContract,
    execution_status: &GatewayFormalBackendHermeticExecutionResultExecutionStatus,
    stdout_summary: &GatewayFormalBackendHermeticExecutionResultBoundedSummary,
    stderr_summary: &GatewayFormalBackendHermeticExecutionResultBoundedSummary,
    redaction_report: &GatewayFormalBackendHermeticExecutionResultRedactionReport,
    output_inventory: &GatewayFormalBackendHermeticExecutionResultOutputInventory,
    invariant_verdict: &GatewayFormalBackendHermeticExecutionResultInvariantVerdictReport,
    nonpromotion_report: &GatewayFormalBackendHermeticExecutionResultNonpromotionReport,
    validation_report: &GatewayFormalBackendHermeticExecutionResultOutputValidationReport,
    request: &GatewayFormalBackendHermeticExecutionResultQuarantineOutputRequest,
    files: &BTreeMap<String, Vec<u8>>,
) -> GatewayFormalBackendHermeticExecutionResultQuarantineOutputManifest {
    let mut declared_file_digests = BTreeMap::new();
    for (logical_path, bytes) in files {
        declared_file_digests.insert(logical_path.clone(), hash_bytes(bytes));
    }
    GatewayFormalBackendHermeticExecutionResultQuarantineOutputManifest {
        schema_version:
            GATEWAY_FORMAL_BACKEND_HERMETIC_EXECUTION_RESULT_QUARANTINE_OUTPUT_SCHEMA_VERSION
                .to_owned(),
        bundle_id: request.bundle_id.clone(),
        state_slice: GATEWAY_FORMAL_BACKEND_HERMETIC_EXECUTION_RESULT_QUARANTINE_OUTPUT_STATE_SLICE
            .to_owned(),
        created_at_unix: request.created_at_unix,
        descriptor_digest: descriptor.digest(),
        descriptor_report_output_manifest_digest: descriptor_report_manifest.digest(),
        descriptor_report_validation_digest: descriptor_report_manifest.validation_digest,
        input_binding_digest: input_binding.digest(),
        command_contract_digest: command_contract.digest(),
        execution_status_digest: execution_status.digest(),
        stdout_summary_digest: stdout_summary.digest(),
        stderr_summary_digest: stderr_summary.digest(),
        redaction_report_digest: redaction_report.digest(),
        output_inventory_digest: output_inventory.digest(),
        invariant_verdict_digest: invariant_verdict.digest(),
        nonpromotion_report_digest: nonpromotion_report.digest(),
        validation_digest: validation_report.digest(),
        nonclaims_digest: hash_bytes(
            files
                .get("gateway-formal-backend-hermetic-execution-result-quarantine/nonclaims.md")
                .map(Vec::as_slice)
                .unwrap_or_default(),
        ),
        backend_id: "local_smt_tiny_gateway_invariant".to_owned(),
        backend_kind: descriptor.backend_kind.clone(),
        tool_name: descriptor.tool_name.clone(),
        tool_version: descriptor.tool_version.clone(),
        executable_path_label: descriptor.executable_path_label.clone(),
        argv_template_digest: gateway_formal_backend_hermetic_argv_template_digest(
            &descriptor.argv_template,
        ),
        environment_policy_digest:
            gateway_formal_backend_hermetic_execution_result_environment_policy_digest(descriptor),
        output_root_label_digest:
            gateway_formal_backend_hermetic_execution_result_output_root_label_digest(
                &descriptor.output_root_label,
            ),
        timeout_millis: descriptor.timeout_millis,
        max_stdout_bytes: descriptor.max_stdout_bytes,
        max_stderr_bytes: descriptor.max_stderr_bytes,
        process_exit_code_label: "not_run".to_owned(),
        timeout: false,
        signal: false,
        solver_status: GatewayFormalBackendHermeticExecutionSolverStatus::NotRun,
        invariant_verdict: GatewayFormalBackendHermeticExecutionInvariantVerdict::NotEvaluated,
        declared_files:
            gateway_formal_backend_hermetic_execution_result_quarantine_output_declared_files(),
        declared_file_digests,
        claim_boundary:
            gateway_formal_backend_hermetic_execution_result_quarantine_output_claim_boundary(),
        process_spawned: false,
        backend_executed: false,
        proof_artifact_created: false,
        checker_transcript_created: false,
        solver_certificate_created: false,
        creates_accepted_evidence: false,
        creates_level2_evidence: false,
        populates_score_axes: false,
        semantic_correctness_claimed: false,
        production_readiness_claimed: false,
        sota_claimed: false,
        breakthrough_claimed: false,
        full_security_claimed: false,
        grants_authority: false,
        nonclaims: descriptor.nonclaims.clone(),
    }
}

fn validate_gateway_formal_backend_hermetic_execution_result_quarantine_bundle_semantics(
    files: &BTreeMap<String, Vec<u8>>,
) -> Result<
    GatewayFormalBackendHermeticExecutionResultQuarantineOutputManifest,
    GatewayFormalBackendHermeticExecutionResultQuarantineOutputError,
> {
    let manifest: GatewayFormalBackendHermeticExecutionResultQuarantineOutputManifest =
        parse_gateway_formal_backend_hermetic_execution_result_quarantine_declared_json(
            files,
            "gateway-formal-backend-hermetic-execution-result-quarantine/manifest.json",
        )?;
    let input_binding: GatewayFormalBackendHermeticExecutionResultInputBinding =
        parse_gateway_formal_backend_hermetic_execution_result_quarantine_declared_json(
            files,
            "gateway-formal-backend-hermetic-execution-result-quarantine/input-binding.json",
        )?;
    let command_contract: GatewayFormalBackendHermeticDescriptorReportCommandContract =
        parse_gateway_formal_backend_hermetic_execution_result_quarantine_declared_json(
            files,
            "gateway-formal-backend-hermetic-execution-result-quarantine/command-contract.json",
        )?;
    let execution_status: GatewayFormalBackendHermeticExecutionResultExecutionStatus =
        parse_gateway_formal_backend_hermetic_execution_result_quarantine_declared_json(
            files,
            "gateway-formal-backend-hermetic-execution-result-quarantine/execution-status.json",
        )?;
    let stdout_summary: GatewayFormalBackendHermeticExecutionResultBoundedSummary =
        parse_gateway_formal_backend_hermetic_execution_result_quarantine_declared_json(
            files,
            "gateway-formal-backend-hermetic-execution-result-quarantine/stdout-summary.json",
        )?;
    let stderr_summary: GatewayFormalBackendHermeticExecutionResultBoundedSummary =
        parse_gateway_formal_backend_hermetic_execution_result_quarantine_declared_json(
            files,
            "gateway-formal-backend-hermetic-execution-result-quarantine/stderr-summary.json",
        )?;
    let redaction_report: GatewayFormalBackendHermeticExecutionResultRedactionReport =
        parse_gateway_formal_backend_hermetic_execution_result_quarantine_declared_json(
            files,
            "gateway-formal-backend-hermetic-execution-result-quarantine/redaction-report.json",
        )?;
    let output_inventory: GatewayFormalBackendHermeticExecutionResultOutputInventory =
        parse_gateway_formal_backend_hermetic_execution_result_quarantine_declared_json(
            files,
            "gateway-formal-backend-hermetic-execution-result-quarantine/output-inventory.json",
        )?;
    let invariant_verdict: GatewayFormalBackendHermeticExecutionResultInvariantVerdictReport =
        parse_gateway_formal_backend_hermetic_execution_result_quarantine_declared_json(
            files,
            "gateway-formal-backend-hermetic-execution-result-quarantine/invariant-verdict.json",
        )?;
    let nonpromotion_report: GatewayFormalBackendHermeticExecutionResultNonpromotionReport =
        parse_gateway_formal_backend_hermetic_execution_result_quarantine_declared_json(
            files,
            "gateway-formal-backend-hermetic-execution-result-quarantine/nonpromotion-report.json",
        )?;
    let validation_report: GatewayFormalBackendHermeticExecutionResultOutputValidationReport =
        parse_gateway_formal_backend_hermetic_execution_result_quarantine_declared_json(
            files,
            "gateway-formal-backend-hermetic-execution-result-quarantine/validation.json",
        )?;

    if command_contract.no_spawn
        && !command_contract.inherit_environment
        && command_contract.no_stdin
        && command_contract.no_shell
        && command_contract.no_network
        && command_contract.output_root_ignored
    {
    } else {
        return Err(
            GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::CommandContractMismatch,
        );
    }
    if input_binding.claim_boundary
        != gateway_formal_backend_hermetic_execution_result_quarantine_output_claim_boundary()
    {
        return Err(
            GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::InputBindingMismatch,
        );
    }
    if !gateway_formal_backend_hermetic_execution_result_execution_status_is_valid(
        &execution_status,
        &command_contract,
        &input_binding,
        &output_inventory,
    ) {
        return Err(
            GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::ExecutionStatusMismatch,
        );
    }
    if stdout_summary
        != gateway_formal_backend_hermetic_execution_result_bounded_summary(
            "stdout",
            command_contract.max_stdout_bytes,
        )
    {
        return Err(
            GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::StdoutSummaryMismatch,
        );
    }
    if stderr_summary
        != gateway_formal_backend_hermetic_execution_result_bounded_summary(
            "stderr",
            command_contract.max_stderr_bytes,
        )
    {
        return Err(
            GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::StderrSummaryMismatch,
        );
    }
    if redaction_report != gateway_formal_backend_hermetic_execution_result_redaction_report() {
        return Err(
            GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::RedactionReportMismatch,
        );
    }
    if output_inventory != gateway_formal_backend_hermetic_execution_result_output_inventory() {
        return Err(
            GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::OutputInventoryMismatch,
        );
    }
    if invariant_verdict
        != gateway_formal_backend_hermetic_execution_result_invariant_verdict_from_binding(
            &input_binding,
        )
    {
        return Err(
            GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::InvariantVerdictMismatch,
        );
    }
    if nonpromotion_report != gateway_formal_backend_hermetic_execution_result_nonpromotion_report()
    {
        return Err(
            GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::NonpromotionReportMismatch,
        );
    }
    if validation_report.bundle_id != manifest.bundle_id
        || validation_report
            != gateway_formal_backend_hermetic_execution_result_output_validation_report_for_manifest(
                &manifest,
            )
    {
        return Err(
            GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::ValidationReportMismatch,
        );
    }
    if declared_gateway_formal_backend_hermetic_execution_result_quarantine_bytes(
        files,
        "gateway-formal-backend-hermetic-execution-result-quarantine/nonclaims.md",
    )? != render_gateway_formal_backend_hermetic_execution_result_quarantine_nonclaims(
        &manifest.nonclaims,
    )
    .as_bytes()
    {
        return Err(
            GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::NonclaimMismatch,
        );
    }
    validate_gateway_formal_backend_hermetic_execution_result_quarantine_manifest_semantics(
        &manifest,
        &input_binding,
        &command_contract,
        &execution_status,
        &stdout_summary,
        &stderr_summary,
        &redaction_report,
        &output_inventory,
        &invariant_verdict,
        &nonpromotion_report,
        &validation_report,
        files,
    )?;
    Ok(manifest)
}

#[allow(clippy::too_many_arguments)]
fn validate_gateway_formal_backend_hermetic_execution_result_quarantine_manifest_semantics(
    manifest: &GatewayFormalBackendHermeticExecutionResultQuarantineOutputManifest,
    input_binding: &GatewayFormalBackendHermeticExecutionResultInputBinding,
    command_contract: &GatewayFormalBackendHermeticDescriptorReportCommandContract,
    execution_status: &GatewayFormalBackendHermeticExecutionResultExecutionStatus,
    stdout_summary: &GatewayFormalBackendHermeticExecutionResultBoundedSummary,
    stderr_summary: &GatewayFormalBackendHermeticExecutionResultBoundedSummary,
    redaction_report: &GatewayFormalBackendHermeticExecutionResultRedactionReport,
    output_inventory: &GatewayFormalBackendHermeticExecutionResultOutputInventory,
    invariant_verdict: &GatewayFormalBackendHermeticExecutionResultInvariantVerdictReport,
    nonpromotion_report: &GatewayFormalBackendHermeticExecutionResultNonpromotionReport,
    validation_report: &GatewayFormalBackendHermeticExecutionResultOutputValidationReport,
    files: &BTreeMap<String, Vec<u8>>,
) -> Result<(), GatewayFormalBackendHermeticExecutionResultQuarantineOutputError> {
    let expected_digest_paths: BTreeSet<String> =
        GATEWAY_FORMAL_BACKEND_HERMETIC_EXECUTION_RESULT_QUARANTINE_DECLARED_FILES
            .iter()
            .filter(|path| {
                **path
                    != "gateway-formal-backend-hermetic-execution-result-quarantine/manifest.json"
            })
            .map(|path| (*path).to_owned())
            .collect();
    let actual_digest_paths: BTreeSet<String> =
        manifest.declared_file_digests.keys().cloned().collect();
    if manifest.schema_version
        != GATEWAY_FORMAL_BACKEND_HERMETIC_EXECUTION_RESULT_QUARANTINE_OUTPUT_SCHEMA_VERSION
        || manifest.bundle_id.trim().is_empty()
        || !is_safe_relative_path(&manifest.bundle_id)
        || manifest.bundle_id.contains(['/', '\\'])
        || manifest.state_slice
            != GATEWAY_FORMAL_BACKEND_HERMETIC_EXECUTION_RESULT_QUARANTINE_OUTPUT_STATE_SLICE
        || manifest.descriptor_digest != input_binding.descriptor_digest
        || manifest.descriptor_report_output_manifest_digest
            != input_binding.descriptor_report_output_manifest_digest
        || manifest.descriptor_report_validation_digest
            != input_binding.descriptor_report_validation_digest
        || manifest.input_binding_digest != input_binding.digest()
        || manifest.command_contract_digest != command_contract.digest()
        || manifest.execution_status_digest != execution_status.digest()
        || manifest.stdout_summary_digest != stdout_summary.digest()
        || manifest.stderr_summary_digest != stderr_summary.digest()
        || manifest.redaction_report_digest != redaction_report.digest()
        || manifest.output_inventory_digest != output_inventory.digest()
        || manifest.invariant_verdict_digest != invariant_verdict.digest()
        || manifest.nonpromotion_report_digest != nonpromotion_report.digest()
        || manifest.validation_digest != validation_report.digest()
        || manifest.nonclaims_digest
            != hash_bytes(
                declared_gateway_formal_backend_hermetic_execution_result_quarantine_bytes(
                    files,
                    "gateway-formal-backend-hermetic-execution-result-quarantine/nonclaims.md",
                )?,
            )
        || manifest.backend_id != "local_smt_tiny_gateway_invariant"
        || manifest.backend_kind != command_contract.backend_kind
        || manifest.tool_name.trim().is_empty()
        || manifest.tool_version.trim().is_empty()
        || manifest.executable_path_label != command_contract.executable_path_label
        || manifest.argv_template_digest != command_contract.argv_template_digest
        || manifest.environment_policy_digest
            != hash_tagged(
                "hsai-agent-admission:gateway-formal-backend-hermetic-execution-result-environment-policy:v1",
                &(
                    command_contract.inherit_environment,
                    command_contract.no_stdin,
                    command_contract.no_shell,
                    command_contract.no_network,
                    command_contract.output_root_ignored,
                ),
            )
        || manifest.output_root_label_digest
            != gateway_formal_backend_hermetic_execution_result_output_root_label_digest(
                &command_contract.output_root_label,
            )
        || manifest.timeout_millis != command_contract.timeout_millis
        || manifest.max_stdout_bytes != command_contract.max_stdout_bytes
        || manifest.max_stderr_bytes != command_contract.max_stderr_bytes
        || manifest.process_exit_code_label != "not_run"
        || manifest.timeout
        || manifest.signal
        || manifest.solver_status != GatewayFormalBackendHermeticExecutionSolverStatus::NotRun
        || manifest.invariant_verdict
            != GatewayFormalBackendHermeticExecutionInvariantVerdict::NotEvaluated
        || manifest.declared_files
            != gateway_formal_backend_hermetic_execution_result_quarantine_output_declared_files()
        || actual_digest_paths != expected_digest_paths
        || manifest.claim_boundary
            != gateway_formal_backend_hermetic_execution_result_quarantine_output_claim_boundary()
        || manifest.process_spawned
        || manifest.backend_executed
        || manifest.proof_artifact_created
        || manifest.checker_transcript_created
        || manifest.solver_certificate_created
        || manifest.creates_accepted_evidence
        || manifest.creates_level2_evidence
        || manifest.populates_score_axes
        || manifest.semantic_correctness_claimed
        || manifest.production_readiness_claimed
        || manifest.sota_claimed
        || manifest.breakthrough_claimed
        || manifest.full_security_claimed
        || manifest.grants_authority
    {
        return Err(
            GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::ManifestSemanticMismatch,
        );
    }
    for (logical_path, expected_digest) in &manifest.declared_file_digests {
        let bytes = declared_gateway_formal_backend_hermetic_execution_result_quarantine_bytes(
            files,
            logical_path,
        )?;
        if *expected_digest != hash_bytes(bytes) {
            return Err(
                GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::DigestMismatch(
                    logical_path.clone(),
                ),
            );
        }
    }
    Ok(())
}

fn gateway_formal_backend_hermetic_execution_result_descriptor_report_manifest_matches(
    descriptor: &GatewayFormalBackendHermeticExecutionDescriptor,
    descriptor_report_manifest: &GatewayFormalBackendHermeticDescriptorReportOutputManifest,
) -> bool {
    descriptor_report_manifest.descriptor_digest == descriptor.digest()
        && descriptor_report_manifest.input_manifest_digest == descriptor.input_manifest_digest
        && descriptor_report_manifest.toolchain_lock_digest == descriptor.toolchain_lock_digest
        && descriptor_report_manifest.lane == descriptor.lane
        && descriptor_report_manifest.backend_kind == descriptor.backend_kind
        && descriptor_report_manifest.invariant_property == descriptor.invariant_property
        && descriptor_report_manifest.command_kind == descriptor.command_kind
        && descriptor_report_manifest.executable_path_label == descriptor.executable_path_label
        && descriptor_report_manifest.argv_template_digest
            == gateway_formal_backend_hermetic_argv_template_digest(&descriptor.argv_template)
        && descriptor_report_manifest.output_root_label == descriptor.output_root_label
        && descriptor_report_manifest.timeout_millis == descriptor.timeout_millis
        && descriptor_report_manifest.max_stdout_bytes == descriptor.max_stdout_bytes
        && descriptor_report_manifest.max_stderr_bytes == descriptor.max_stderr_bytes
        && descriptor_report_manifest.no_spawn
        && !descriptor_report_manifest.backend_executed
        && !descriptor_report_manifest.proof_artifact_created
        && !descriptor_report_manifest.checker_transcript_created
        && !descriptor_report_manifest.creates_accepted_evidence
        && !descriptor_report_manifest.creates_level2_evidence
        && !descriptor_report_manifest.populates_score_axes
        && !descriptor_report_manifest.semantic_correctness_claimed
        && !descriptor_report_manifest.production_readiness_claimed
        && !descriptor_report_manifest.sota_claimed
        && !descriptor_report_manifest.breakthrough_claimed
        && !descriptor_report_manifest.full_security_claimed
        && !descriptor_report_manifest.grants_authority
}

