fn gateway_formal_backend_hermetic_execution_result_execution_status_is_valid(
    status: &GatewayFormalBackendHermeticExecutionResultExecutionStatus,
    command_contract: &GatewayFormalBackendHermeticDescriptorReportCommandContract,
    input_binding: &GatewayFormalBackendHermeticExecutionResultInputBinding,
    output_inventory: &GatewayFormalBackendHermeticExecutionResultOutputInventory,
) -> bool {
    status.backend_id == "local_smt_tiny_gateway_invariant"
        && status.backend_kind == command_contract.backend_kind
        && !status.tool_name.trim().is_empty()
        && !status.tool_version.trim().is_empty()
        && status.started_at_unix == 0
        && status.finished_at_unix == 0
        && !status.process_spawned
        && !status.backend_executed
        && status.process_exit_code_label == "not_run"
        && !status.timeout
        && !status.signal
        && !status.stdout_truncated
        && !status.stderr_truncated
        && status.solver_status == GatewayFormalBackendHermeticExecutionSolverStatus::NotRun
        && status.invariant_verdict
            == GatewayFormalBackendHermeticExecutionInvariantVerdict::NotEvaluated
        && status.command_contract_digest == command_contract.digest()
        && status.input_binding_digest == input_binding.digest()
        && status.output_inventory_digest == output_inventory.digest()
}

