fn declared_gateway_formal_backend_hermetic_execution_result_quarantine_bytes<'a>(
    files: &'a BTreeMap<String, Vec<u8>>,
    logical_path: &str,
) -> Result<&'a [u8], GatewayFormalBackendHermeticExecutionResultQuarantineOutputError> {
    files.get(logical_path).map(Vec::as_slice).ok_or_else(|| {
        GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::Io(format!(
            "declared file missing: {logical_path}"
        ))
    })
}

fn parse_gateway_formal_backend_hermetic_execution_result_quarantine_declared_json<
    T: for<'de> Deserialize<'de>,
>(
    files: &BTreeMap<String, Vec<u8>>,
    logical_path: &str,
) -> Result<T, GatewayFormalBackendHermeticExecutionResultQuarantineOutputError> {
    let bytes = declared_gateway_formal_backend_hermetic_execution_result_quarantine_bytes(
        files,
        logical_path,
    )?;
    let text = std::str::from_utf8(bytes).map_err(|_| {
        GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::MalformedDeclaredFile(
            logical_path.to_owned(),
        )
    })?;
    serde_json::from_str(text).map_err(|_| {
        GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::MalformedDeclaredFile(
            logical_path.to_owned(),
        )
    })
}

fn reject_undeclared_gateway_formal_backend_hermetic_execution_result_quarantine_files(
    output_root: &Path,
) -> Result<(), GatewayFormalBackendHermeticExecutionResultQuarantineOutputError> {
    let mut declared: BTreeSet<String> =
        GATEWAY_FORMAL_BACKEND_HERMETIC_EXECUTION_RESULT_QUARANTINE_DECLARED_FILES
            .iter()
            .chain(
                GATEWAY_FORMAL_BACKEND_HERMETIC_EXECUTION_RESULT_QUARANTINE_DECLARED_SIDECARS
                    .iter(),
            )
            .map(|value| (*value).to_owned())
            .collect();
    let bundle_dir =
        output_root.join("gateway-formal-backend-hermetic-execution-result-quarantine");
    for entry in fs::read_dir(&bundle_dir)
        .map_err(gateway_formal_backend_hermetic_execution_result_quarantine_io_error)?
    {
        let entry =
            entry.map_err(gateway_formal_backend_hermetic_execution_result_quarantine_io_error)?;
        let logical_path = entry
            .path()
            .strip_prefix(output_root)
            .map_err(|error| {
                GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::Io(
                    error.to_string(),
                )
            })?
            .to_string_lossy()
            .replace('\\', "/");
        if !declared.remove(&logical_path) {
            return Err(
                GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::UndeclaredFile(
                    logical_path,
                ),
            );
        }
    }
    if let Some(missing) = declared.into_iter().next() {
        return Err(
            GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::Io(format!(
                "declared file missing: {missing}"
            )),
        );
    }
    Ok(())
}

fn validate_gateway_formal_backend_hermetic_execution_result_quarantine_output_root(
    output_root: &Path,
    protected_roots: &[PathBuf],
    overwrite: bool,
) -> Result<(), GatewayFormalBackendHermeticExecutionResultQuarantineOutputError> {
    match validate_output_root(output_root, protected_roots, overwrite) {
        Ok(()) => Ok(()),
        Err(AdmissionJournalMaterializationError::EmptyOutputRoot) => {
            Err(GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::EmptyOutputRoot)
        }
        Err(AdmissionJournalMaterializationError::ProtectedOutputRoot) => Err(
            GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::ProtectedOutputRoot,
        ),
        Err(AdmissionJournalMaterializationError::OutputRootExistsWithoutOverwrite) => Err(
            GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::OutputRootExistsWithoutOverwrite,
        ),
        Err(AdmissionJournalMaterializationError::OutputRootIsFile) => {
            Err(GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::OutputRootIsFile)
        }
        Err(AdmissionJournalMaterializationError::OutputRootIsSymlink) => Err(
            GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::OutputRootIsSymlink,
        ),
        Err(AdmissionJournalMaterializationError::Io(error)) => {
            Err(GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::Io(error))
        }
        Err(other) => Err(
            GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::Io(format!(
                "{other:?}"
            )),
        ),
    }
}

fn gateway_formal_backend_hermetic_execution_result_quarantine_staging_root_for(
    output_root: &Path,
    bundle_id: &str,
) -> Result<PathBuf, GatewayFormalBackendHermeticExecutionResultQuarantineOutputError> {
    let parent = output_root
        .parent()
        .ok_or(GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::EmptyOutputRoot)?;
    let name = output_root
        .file_name()
        .map(|value| value.to_string_lossy().into_owned())
        .ok_or(GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::EmptyOutputRoot)?;
    Ok(parent.join(format!(".{name}.{bundle_id}.staging")))
}

fn remove_gateway_formal_backend_hermetic_execution_result_quarantine_dir_all_checked(
    path: &Path,
) -> Result<(), GatewayFormalBackendHermeticExecutionResultQuarantineOutputError> {
    if !path.exists() {
        return Ok(());
    }
    if fs::symlink_metadata(path)
        .map_err(gateway_formal_backend_hermetic_execution_result_quarantine_io_error)?
        .file_type()
        .is_symlink()
    {
        return Err(
            GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::OutputRootIsSymlink,
        );
    }
    fs::remove_dir_all(path)
        .map_err(gateway_formal_backend_hermetic_execution_result_quarantine_io_error)
}

fn gateway_formal_backend_hermetic_execution_result_quarantine_io_error(
    error: io::Error,
) -> GatewayFormalBackendHermeticExecutionResultQuarantineOutputError {
    GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::Io(error.to_string())
}

