pub fn build_gateway_formal_backend_hermetic_process_spawn_interface(
    interface_id: impl Into<String>,
    descriptor: &GatewayFormalBackendHermeticExecutionDescriptor,
    descriptor_report_manifest: &GatewayFormalBackendHermeticDescriptorReportOutputManifest,
    result_quarantine_manifest: &GatewayFormalBackendHermeticExecutionResultQuarantineOutputManifest,
) -> GatewayFormalBackendHermeticProcessSpawnInterface {
    let executable_policy =
        gateway_formal_backend_hermetic_process_spawn_executable_policy(descriptor);
    let runtime_policy = gateway_formal_backend_hermetic_process_spawn_runtime_policy(descriptor);
    let nonpromotion_policy = gateway_formal_backend_hermetic_process_spawn_nonpromotion_policy();
    GatewayFormalBackendHermeticProcessSpawnInterface {
        schema_version: GATEWAY_FORMAL_BACKEND_HERMETIC_PROCESS_SPAWN_INTERFACE_SCHEMA_VERSION
            .to_owned(),
        interface_id: interface_id.into(),
        state_slice: GATEWAY_FORMAL_BACKEND_HERMETIC_PROCESS_SPAWN_INTERFACE_STATE_SLICE.to_owned(),
        descriptor_digest: descriptor.digest(),
        descriptor_report_output_manifest_digest: descriptor_report_manifest.digest(),
        result_quarantine_output_manifest_digest: result_quarantine_manifest.digest(),
        executable_policy_digest: executable_policy.digest(),
        runtime_policy_digest: runtime_policy.digest(),
        nonpromotion_policy_digest: nonpromotion_policy.digest(),
        executable_policy,
        runtime_policy,
        nonpromotion_policy,
        has_default_runner: false,
        process_spawned: false,
        backend_executed: false,
        claim_boundary: gateway_formal_backend_hermetic_process_spawn_interface_claim_boundary(),
        claim_text: Vec::new(),
        nonclaims: gateway_formal_backend_hermetic_process_spawn_interface_required_nonclaims(),
    }
}

pub fn validate_gateway_formal_backend_hermetic_process_spawn_interface(
    interface: &GatewayFormalBackendHermeticProcessSpawnInterface,
    descriptor: &GatewayFormalBackendHermeticExecutionDescriptor,
    descriptor_report_manifest: &GatewayFormalBackendHermeticDescriptorReportOutputManifest,
    result_quarantine_manifest: &GatewayFormalBackendHermeticExecutionResultQuarantineOutputManifest,
) -> GatewayFormalBackendHermeticProcessSpawnInterfaceValidation {
    let mut issues = Vec::new();
    if interface.schema_version
        != GATEWAY_FORMAL_BACKEND_HERMETIC_PROCESS_SPAWN_INTERFACE_SCHEMA_VERSION
    {
        issues.push(GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::InvalidSchemaVersion);
    }
    if interface.interface_id.trim().is_empty()
        || !is_safe_relative_path(&interface.interface_id)
        || interface.interface_id.contains(['/', '\\'])
    {
        issues.push(GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::InvalidInterfaceId);
    }
    if interface.state_slice != GATEWAY_FORMAL_BACKEND_HERMETIC_PROCESS_SPAWN_INTERFACE_STATE_SLICE
    {
        issues.push(GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::StateSliceMismatch);
    }
    if !validate_gateway_formal_backend_hermetic_execution_descriptor(descriptor).valid {
        issues.push(GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::DescriptorInvalid);
    }
    if !gateway_formal_backend_hermetic_execution_result_descriptor_report_manifest_matches(
        descriptor,
        descriptor_report_manifest,
    ) {
        issues.push(
            GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::DescriptorReportManifestMismatch,
        );
    }
    if !gateway_formal_backend_hermetic_process_spawn_result_quarantine_manifest_matches(
        descriptor,
        descriptor_report_manifest,
        result_quarantine_manifest,
    ) {
        issues.push(
            GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::ResultQuarantineManifestMismatch,
        );
    }
    if interface.descriptor_digest != descriptor.digest()
        || interface.descriptor_report_output_manifest_digest != descriptor_report_manifest.digest()
        || interface.result_quarantine_output_manifest_digest != result_quarantine_manifest.digest()
    {
        issues.push(
            GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::ResultQuarantineManifestMismatch,
        );
    }

    validate_gateway_formal_backend_hermetic_process_spawn_executable_policy(
        &interface.executable_policy,
        descriptor,
        &mut issues,
    );
    validate_gateway_formal_backend_hermetic_process_spawn_runtime_policy(
        &interface.runtime_policy,
        descriptor,
        &mut issues,
    );
    validate_gateway_formal_backend_hermetic_process_spawn_nonpromotion_policy(
        &interface.nonpromotion_policy,
        &mut issues,
    );

    if interface.executable_policy_digest != interface.executable_policy.digest() {
        issues.push(
            GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::ExecutablePolicyDigestMismatch,
        );
    }
    if interface.runtime_policy_digest != interface.runtime_policy.digest() {
        issues.push(
            GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::RuntimePolicyDigestMismatch,
        );
    }
    if interface.nonpromotion_policy_digest != interface.nonpromotion_policy.digest() {
        issues.push(
            GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::NonpromotionPolicyDigestMismatch,
        );
    }
    if interface.has_default_runner {
        issues.push(GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::DefaultRunnerPresent);
    }
    if interface.process_spawned {
        issues.push(GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::ProcessSpawned);
    }
    if interface.backend_executed {
        issues.push(GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::BackendExecuted);
    }
    if interface.claim_boundary
        != gateway_formal_backend_hermetic_process_spawn_interface_claim_boundary()
    {
        issues.push(GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::ClaimBoundaryMismatch);
    }
    for claim in &interface.claim_text {
        let lower = claim.to_ascii_lowercase();
        for forbidden in gateway_formal_evidence_forbidden_claim_fragments() {
            if lower.contains(forbidden) {
                issues.push(
                    GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::ForbiddenClaimText(
                        claim.clone(),
                    ),
                );
            }
        }
    }
    for required in gateway_formal_backend_hermetic_process_spawn_interface_required_nonclaims() {
        if !interface.nonclaims.contains(&required) {
            issues.push(
                GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::MissingRequiredNonclaim(
                    required.0,
                ),
            );
        }
    }
    GatewayFormalBackendHermeticProcessSpawnInterfaceValidation {
        valid: issues.is_empty(),
        issues,
    }
}

