pub fn validate_gateway_formal_tiny_digest_backend_z3_policy_decision_input(
    handoff: &GatewayFormalTinyDigestBackendZ3AcceptedHandoff,
    input: &GatewayFormalTinyDigestBackendZ3PolicyDecisionInput,
) -> GatewayFormalTinyDigestBackendZ3PolicyDecisionValidation {
    let mut issues = Vec::new();
    if input.schema_version != GATEWAY_FORMAL_TINY_DIGEST_BACKEND_Z3_POLICY_DECISION_SCHEMA_VERSION
    {
        issues.push(GatewayFormalTinyDigestBackendZ3PolicyDecisionIssue::InvalidSchemaVersion);
    }
    if !is_single_segment_id(&input.decision_id) {
        issues.push(GatewayFormalTinyDigestBackendZ3PolicyDecisionIssue::InvalidDecisionId);
    }
    if input.created_at_unix == 0 {
        issues.push(GatewayFormalTinyDigestBackendZ3PolicyDecisionIssue::MissingCreatedAt);
    }
    validate_gateway_formal_tiny_digest_backend_z3_policy_decision_digests(input, &mut issues);
    validate_gateway_formal_tiny_digest_backend_z3_policy_decision_handoff(
        handoff,
        input,
        &mut issues,
    );
    validate_gateway_formal_tiny_digest_backend_z3_policy_decision_policy(input, &mut issues);
    GatewayFormalTinyDigestBackendZ3PolicyDecisionValidation {
        valid: issues.is_empty(),
        issues,
    }
}

fn validate_gateway_formal_tiny_digest_backend_z3_policy_decision_digests(
    input: &GatewayFormalTinyDigestBackendZ3PolicyDecisionInput,
    issues: &mut Vec<GatewayFormalTinyDigestBackendZ3PolicyDecisionIssue>,
) {
    for (label, digest) in [
        ("handoff_digest", input.handoff_digest),
        ("handoff_input_digest", input.handoff_input_digest),
        ("reviewed_record_digest", input.reviewed_record_digest),
        (
            "policy_decision_statement_digest",
            input.policy_decision_statement_digest,
        ),
        (
            "current_accepted_append_blockers_digest",
            input.current_accepted_append_blockers_digest,
        ),
        ("explicit_nonclaims_digest", input.explicit_nonclaims_digest),
    ] {
        if digest == Hash([0; 32]) {
            issues.push(
                GatewayFormalTinyDigestBackendZ3PolicyDecisionIssue::MissingDigest(
                    label.to_owned(),
                ),
            );
        }
    }
}

fn validate_gateway_formal_tiny_digest_backend_z3_policy_decision_handoff(
    handoff: &GatewayFormalTinyDigestBackendZ3AcceptedHandoff,
    input: &GatewayFormalTinyDigestBackendZ3PolicyDecisionInput,
    issues: &mut Vec<GatewayFormalTinyDigestBackendZ3PolicyDecisionIssue>,
) {
    if input.handoff_digest != handoff.digest()
        || input.handoff_input_digest != handoff.handoff_input_digest
        || input.reviewed_record_digest != handoff.reviewed_record_digest
        || input.accepted_append_policy_version != handoff.accepted_append_policy_version
        || input.source_formal_evidence_acceptance_policy_version
            != handoff.formal_evidence_acceptance_policy_version
    {
        issues.push(GatewayFormalTinyDigestBackendZ3PolicyDecisionIssue::HandoffDigestDrift);
    }
    if handoff.schema_version
        != GATEWAY_FORMAL_TINY_DIGEST_BACKEND_Z3_ACCEPTED_HANDOFF_SCHEMA_VERSION
        || handoff.state_slice != GATEWAY_FORMAL_TINY_DIGEST_BACKEND_Z3_ACCEPTED_HANDOFF_STATE_SLICE
        || handoff.promotion_state != "future_accepted_formal_evidence_handoff"
        || handoff.next_required_state != "accepted_formal_evidence_policy_decision"
        || handoff.claim_boundary
            != gateway_formal_tiny_digest_backend_z3_accepted_handoff_claim_boundary()
        || handoff.formal_evidence_acceptance_policy_decision
            != GatewayFormalTinyDigestBackendZ3FormalAcceptancePolicyDecision::UnresolvedAcceptedAppendBlocksFormalEvidence
        || handoff.creates_accepted_evidence
        || handoff.creates_level2_evidence
        || handoff.populates_score_axes
        || handoff.proof_artifact_created
        || handoff.checker_transcript_created
        || handoff.solver_certificate_created
        || handoff.semantic_correctness_claimed
        || handoff.production_readiness_claimed
        || handoff.sota_claimed
        || handoff.breakthrough_claimed
        || handoff.full_security_claimed
        || handoff.grants_authority
    {
        issues.push(GatewayFormalTinyDigestBackendZ3PolicyDecisionIssue::HandoffStateMismatch);
    }
}

fn validate_gateway_formal_tiny_digest_backend_z3_policy_decision_policy(
    input: &GatewayFormalTinyDigestBackendZ3PolicyDecisionInput,
    issues: &mut Vec<GatewayFormalTinyDigestBackendZ3PolicyDecisionIssue>,
) {
    if input.accepted_append_policy_version
        != GATEWAY_FORMAL_TINY_DIGEST_BACKEND_Z3_ACCEPTED_HANDOFF_ACCEPTED_APPEND_POLICY_VERSION
    {
        issues.push(
            GatewayFormalTinyDigestBackendZ3PolicyDecisionIssue::AcceptedAppendPolicyVersionMismatch,
        );
    }
    if input.source_formal_evidence_acceptance_policy_version
        != GATEWAY_FORMAL_TINY_DIGEST_BACKEND_Z3_ACCEPTED_HANDOFF_FORMAL_POLICY_VERSION
    {
        issues.push(
            GatewayFormalTinyDigestBackendZ3PolicyDecisionIssue::SourceFormalPolicyVersionMismatch,
        );
    }
    if input.policy_decision_version
        != GATEWAY_FORMAL_TINY_DIGEST_BACKEND_Z3_POLICY_DECISION_VERSION
    {
        issues.push(
            GatewayFormalTinyDigestBackendZ3PolicyDecisionIssue::PolicyDecisionVersionMismatch,
        );
    }
    if input.policy_decision
        != GatewayFormalTinyDigestBackendZ3FormalAcceptancePolicyDecision::AcceptedFormalEvidenceStillForbidden
    {
        issues.push(GatewayFormalTinyDigestBackendZ3PolicyDecisionIssue::PolicyDecisionNotForbidden);
    }
    let statement = gateway_formal_tiny_digest_backend_z3_policy_decision_statement();
    if input.policy_decision_statement != statement
        || input.policy_decision_statement_digest
            != hash_tagged(
                "hsai-agent-admission:gateway-formal-tiny-digest-backend-z3-policy-decision-statement:v1",
                &statement,
            )
    {
        issues.push(
            GatewayFormalTinyDigestBackendZ3PolicyDecisionIssue::PolicyDecisionStatementMismatch,
        );
    }
    let blockers = gateway_formal_tiny_digest_backend_z3_accepted_handoff_current_blockers();
    if input.current_accepted_append_blockers != blockers
        || input.current_accepted_append_blockers_digest
            != hash_tagged(
                "hsai-agent-admission:gateway-formal-tiny-digest-backend-z3-accepted-handoff-current-blockers:v1",
                &blockers,
            )
    {
        issues.push(
            GatewayFormalTinyDigestBackendZ3PolicyDecisionIssue::AcceptedAppendBlockerMismatch,
        );
    }
    let nonclaims = gateway_formal_tiny_digest_backend_z3_policy_decision_required_nonclaims();
    if input.explicit_nonclaims != nonclaims
        || input.explicit_nonclaims_digest
            != hash_tagged(
                "hsai-agent-admission:gateway-formal-tiny-digest-backend-z3-policy-decision-nonclaims:v1",
                &nonclaims,
            )
    {
        issues.push(GatewayFormalTinyDigestBackendZ3PolicyDecisionIssue::NonclaimMismatch);
    }
    if input.accepted_evidence_mutation_requested
        || input.accepted_append_policy_change_requested
        || input.accepted_formal_evidence_created
        || input.bounded_formal_evidence_class_approved
        || input.creates_level2_evidence
        || input.populates_score_axes
        || input.proof_artifact_promoted
        || input.checker_transcript_promoted
        || input.solver_certificate_promoted
        || input.benchmark_or_sota_comparison_claimed
        || input.semantic_correctness_claimed
        || input.production_readiness_claimed
        || input.sota_claimed
        || input.breakthrough_claimed
        || input.full_security_claimed
        || input.action_authority_claimed
    {
        issues.push(GatewayFormalTinyDigestBackendZ3PolicyDecisionIssue::PromotionAttempt);
    }
}

