fn validate_gateway_formal_tiny_digest_backend_z3_audit_package_artifact_semantics(
    files: &BTreeMap<String, Vec<u8>>,
) -> Result<
    GatewayFormalTinyDigestBackendZ3AuditPackageArtifactManifest,
    GatewayFormalTinyDigestBackendZ3AuditPackageArtifactOutputError,
> {
    let manifest: GatewayFormalTinyDigestBackendZ3AuditPackageArtifactManifest =
        parse_gateway_formal_tiny_digest_backend_z3_audit_package_artifact_declared_json(
            files,
            "tiny-z3-audit-package/manifest.json",
        )?;
    let review: GatewayFormalTinyDigestBackendZ3SerializationPreviewReview =
        parse_gateway_formal_tiny_digest_backend_z3_audit_package_artifact_declared_json(
            files,
            "tiny-z3-audit-package/review.json",
        )?;
    let preview: GatewayFormalTinyDigestBackendZ3AuditPackageSerializationPreview =
        parse_gateway_formal_tiny_digest_backend_z3_audit_package_artifact_declared_json(
            files,
            "tiny-z3-audit-package/serialization-preview.json",
        )?;
    let nonclaims: BTreeSet<NonClaimLabel> =
        parse_gateway_formal_tiny_digest_backend_z3_audit_package_artifact_declared_json(
            files,
            "tiny-z3-audit-package/nonclaims.json",
        )?;
    let digest_index: BTreeMap<String, Hash> =
        parse_gateway_formal_tiny_digest_backend_z3_audit_package_artifact_declared_json(
            files,
            "tiny-z3-audit-package/digests.json",
        )?;
    let claim_boundary = String::from_utf8(
        declared_gateway_formal_tiny_digest_backend_z3_audit_package_artifact_bytes(
            files,
            "tiny-z3-audit-package/claim-boundary.txt",
        )?
        .to_vec(),
    )
    .map_err(|_| {
        GatewayFormalTinyDigestBackendZ3AuditPackageArtifactOutputError::MalformedDeclaredFile(
            "tiny-z3-audit-package/claim-boundary.txt".to_owned(),
        )
    })?;

    if manifest.schema_version
        != GATEWAY_FORMAL_TINY_DIGEST_BACKEND_Z3_AUDIT_PACKAGE_ARTIFACT_SCHEMA_VERSION
        || manifest.state_slice
            != GATEWAY_FORMAL_TINY_DIGEST_BACKEND_Z3_AUDIT_PACKAGE_ARTIFACT_STATE_SLICE
        || manifest.artifact_profile_id
            != GATEWAY_FORMAL_TINY_DIGEST_BACKEND_Z3_AUDIT_PACKAGE_ARTIFACT_PROFILE_ID
        || manifest.claim_boundary
            != gateway_formal_tiny_digest_backend_z3_audit_package_artifact_claim_boundary()
        || claim_boundary != manifest.claim_boundary
        || manifest.declared_files
            != gateway_formal_tiny_digest_backend_z3_audit_package_artifact_declared_files()
        || manifest.declared_sidecars
            != gateway_formal_tiny_digest_backend_z3_audit_package_artifact_declared_sidecars()
    {
        return Err(
            GatewayFormalTinyDigestBackendZ3AuditPackageArtifactOutputError::ManifestSemanticMismatch,
        );
    }
    if manifest.creates_accepted_evidence
        || manifest.changes_accepted_append_policy
        || manifest.creates_level2_evidence
        || manifest.populates_score_axes
        || manifest.proof_artifact_created
        || manifest.checker_transcript_created
        || manifest.solver_certificate_created
        || manifest.semantic_correctness_claimed
        || manifest.production_readiness_claimed
        || manifest.sota_claimed
        || manifest.breakthrough_claimed
        || manifest.full_security_claimed
        || manifest.grants_authority
    {
        return Err(
            GatewayFormalTinyDigestBackendZ3AuditPackageArtifactOutputError::PromotionAttempt,
        );
    }
    validate_gateway_formal_tiny_digest_backend_z3_audit_package_artifact_review(
        &review, &preview,
    )?;
    if manifest.review_digest != review.digest()
        || manifest.review_input_digest != review.review_input_digest
        || manifest.serialization_preview_digest != preview.digest()
        || manifest.serialization_preview_input_digest != preview.preview_input_digest
        || manifest.audit_package_digest != preview.package_digest
        || manifest.review_record_digest != preview.review_digest
        || manifest.metadata_digest != preview.metadata_digest
        || manifest.phase405_output_manifest_digest != preview.phase405_output_manifest_digest
        || manifest.phase404_execution_digest != preview.phase404_execution_digest
        || manifest.current_accepted_append_blockers_digest
            != preview.current_accepted_append_blockers_digest
        || manifest.package_manifest_digest != preview.package_manifest_digest
        || manifest.serialization_profile_id != preview.serialization_profile_id
        || manifest.canonical_field_order_digest != preview.canonical_field_order_digest
        || manifest.canonical_json_shape_digest != preview.canonical_json_shape_digest
        || manifest.canonical_json_payload_digest != preview.canonical_json_payload_digest
        || manifest.redaction_policy_digest != preview.redaction_policy_digest
        || manifest.logical_preview_path_digest != review.logical_preview_path_digest
    {
        return Err(
            GatewayFormalTinyDigestBackendZ3AuditPackageArtifactOutputError::ManifestSemanticMismatch,
        );
    }
    let required_nonclaims =
        gateway_formal_tiny_digest_backend_z3_audit_package_artifact_required_nonclaims();
    if manifest.nonclaims != required_nonclaims || nonclaims != required_nonclaims {
        return Err(
            GatewayFormalTinyDigestBackendZ3AuditPackageArtifactOutputError::NonclaimMismatch,
        );
    }
    let expected_digest_index =
        gateway_formal_tiny_digest_backend_z3_audit_package_artifact_digest_index(
            &review,
            &preview,
            &required_nonclaims,
        );
    if digest_index != expected_digest_index {
        return Err(
            GatewayFormalTinyDigestBackendZ3AuditPackageArtifactOutputError::DigestMismatch(
                "tiny-z3-audit-package/digests.json".to_owned(),
            ),
        );
    }
    let expected_file_digests: BTreeMap<String, Hash> = files
        .iter()
        .filter(|(logical_path, _)| logical_path.as_str() != "tiny-z3-audit-package/manifest.json")
        .map(|(logical_path, bytes)| (logical_path.clone(), hash_bytes(bytes)))
        .collect();
    if manifest.declared_file_digests != expected_file_digests {
        return Err(
            GatewayFormalTinyDigestBackendZ3AuditPackageArtifactOutputError::DigestMismatch(
                "tiny-z3-audit-package/manifest.json".to_owned(),
            ),
        );
    }
    Ok(manifest)
}

fn declared_gateway_formal_tiny_digest_backend_z3_audit_package_artifact_bytes<'a>(
    files: &'a BTreeMap<String, Vec<u8>>,
    logical_path: &str,
) -> Result<&'a [u8], GatewayFormalTinyDigestBackendZ3AuditPackageArtifactOutputError> {
    files
        .get(logical_path)
        .map(|bytes| bytes.as_slice())
        .ok_or_else(|| {
            GatewayFormalTinyDigestBackendZ3AuditPackageArtifactOutputError::Io(format!(
                "declared file missing: {logical_path}"
            ))
        })
}

fn parse_gateway_formal_tiny_digest_backend_z3_audit_package_artifact_declared_json<
    T: for<'de> Deserialize<'de>,
>(
    files: &BTreeMap<String, Vec<u8>>,
    logical_path: &str,
) -> Result<T, GatewayFormalTinyDigestBackendZ3AuditPackageArtifactOutputError> {
    let bytes = declared_gateway_formal_tiny_digest_backend_z3_audit_package_artifact_bytes(
        files,
        logical_path,
    )?;
    let text = std::str::from_utf8(bytes).map_err(|_| {
        GatewayFormalTinyDigestBackendZ3AuditPackageArtifactOutputError::MalformedDeclaredFile(
            logical_path.to_owned(),
        )
    })?;
    serde_json::from_str(text).map_err(|_| {
        GatewayFormalTinyDigestBackendZ3AuditPackageArtifactOutputError::MalformedDeclaredFile(
            logical_path.to_owned(),
        )
    })
}

fn reject_undeclared_gateway_formal_tiny_digest_backend_z3_audit_package_artifact_files(
    output_root: &Path,
) -> Result<(), GatewayFormalTinyDigestBackendZ3AuditPackageArtifactOutputError> {
    for entry in fs::read_dir(output_root)
        .map_err(gateway_formal_tiny_digest_backend_z3_audit_package_artifact_io_error)?
    {
        let entry =
            entry.map_err(gateway_formal_tiny_digest_backend_z3_audit_package_artifact_io_error)?;
        let name = entry.file_name().to_string_lossy().into_owned();
        if name != "tiny-z3-audit-package" {
            return Err(
                GatewayFormalTinyDigestBackendZ3AuditPackageArtifactOutputError::UndeclaredFile(
                    name,
                ),
            );
        }
    }
    let mut declared: BTreeSet<String> =
        GATEWAY_FORMAL_TINY_DIGEST_BACKEND_Z3_AUDIT_PACKAGE_ARTIFACT_DECLARED_FILES
            .iter()
            .map(|value| (*value).to_owned())
            .chain(gateway_formal_tiny_digest_backend_z3_audit_package_artifact_declared_sidecars())
            .collect();
    let bundle_dir = output_root.join("tiny-z3-audit-package");
    for entry in fs::read_dir(&bundle_dir)
        .map_err(gateway_formal_tiny_digest_backend_z3_audit_package_artifact_io_error)?
    {
        let entry =
            entry.map_err(gateway_formal_tiny_digest_backend_z3_audit_package_artifact_io_error)?;
        let logical_path = entry
            .path()
            .strip_prefix(output_root)
            .map_err(|error| {
                GatewayFormalTinyDigestBackendZ3AuditPackageArtifactOutputError::Io(
                    error.to_string(),
                )
            })?
            .to_string_lossy()
            .replace('\\', "/");
        if !declared.remove(&logical_path) {
            return Err(
                GatewayFormalTinyDigestBackendZ3AuditPackageArtifactOutputError::UndeclaredFile(
                    logical_path,
                ),
            );
        }
    }
    if let Some(missing) = declared.into_iter().next() {
        return Err(
            GatewayFormalTinyDigestBackendZ3AuditPackageArtifactOutputError::Io(format!(
                "declared file missing: {missing}"
            )),
        );
    }
    Ok(())
}

fn validate_gateway_formal_tiny_digest_backend_z3_audit_package_artifact_output_root(
    output_root: &Path,
    protected_roots: &[PathBuf],
    overwrite: bool,
) -> Result<(), GatewayFormalTinyDigestBackendZ3AuditPackageArtifactOutputError> {
    match validate_output_root(output_root, protected_roots, overwrite) {
        Ok(()) => Ok(()),
        Err(AdmissionJournalMaterializationError::EmptyOutputRoot) => {
            Err(GatewayFormalTinyDigestBackendZ3AuditPackageArtifactOutputError::EmptyOutputRoot)
        }
        Err(AdmissionJournalMaterializationError::ProtectedOutputRoot) => Err(
            GatewayFormalTinyDigestBackendZ3AuditPackageArtifactOutputError::ProtectedOutputRoot,
        ),
        Err(AdmissionJournalMaterializationError::OutputRootExistsWithoutOverwrite) => Err(
            GatewayFormalTinyDigestBackendZ3AuditPackageArtifactOutputError::OutputRootExistsWithoutOverwrite,
        ),
        Err(AdmissionJournalMaterializationError::OutputRootIsFile) => {
            Err(GatewayFormalTinyDigestBackendZ3AuditPackageArtifactOutputError::OutputRootIsFile)
        }
        Err(AdmissionJournalMaterializationError::OutputRootIsSymlink) => {
            Err(GatewayFormalTinyDigestBackendZ3AuditPackageArtifactOutputError::OutputRootIsSymlink)
        }
        Err(AdmissionJournalMaterializationError::Io(error)) => {
            Err(GatewayFormalTinyDigestBackendZ3AuditPackageArtifactOutputError::Io(error))
        }
        Err(other) => Err(GatewayFormalTinyDigestBackendZ3AuditPackageArtifactOutputError::Io(
            format!("{other:?}"),
        )),
    }
}

fn gateway_formal_tiny_digest_backend_z3_audit_package_artifact_staging_root_for(
    output_root: &Path,
    package_id: &str,
) -> Result<PathBuf, GatewayFormalTinyDigestBackendZ3AuditPackageArtifactOutputError> {
    let parent = output_root
        .parent()
        .ok_or(GatewayFormalTinyDigestBackendZ3AuditPackageArtifactOutputError::EmptyOutputRoot)?;
    let name = output_root
        .file_name()
        .map(|value| value.to_string_lossy().into_owned())
        .ok_or(GatewayFormalTinyDigestBackendZ3AuditPackageArtifactOutputError::EmptyOutputRoot)?;
    Ok(parent.join(format!(".{name}.{package_id}.staging")))
}

fn remove_gateway_formal_tiny_digest_backend_z3_audit_package_artifact_dir_all_checked(
    path: &Path,
) -> Result<(), GatewayFormalTinyDigestBackendZ3AuditPackageArtifactOutputError> {
    if !path.exists() {
        return Ok(());
    }
    if fs::symlink_metadata(path)
        .map_err(gateway_formal_tiny_digest_backend_z3_audit_package_artifact_io_error)?
        .file_type()
        .is_symlink()
    {
        return Err(
            GatewayFormalTinyDigestBackendZ3AuditPackageArtifactOutputError::OutputRootIsSymlink,
        );
    }
    fs::remove_dir_all(path)
        .map_err(gateway_formal_tiny_digest_backend_z3_audit_package_artifact_io_error)
}

fn gateway_formal_tiny_digest_backend_z3_audit_package_artifact_io_error(
    error: io::Error,
) -> GatewayFormalTinyDigestBackendZ3AuditPackageArtifactOutputError {
    GatewayFormalTinyDigestBackendZ3AuditPackageArtifactOutputError::Io(error.to_string())
}

fn gateway_formal_tiny_digest_backend_z3_audit_package_artifact_serde_error(
    error: serde_json::Error,
) -> GatewayFormalTinyDigestBackendZ3AuditPackageArtifactOutputError {
    GatewayFormalTinyDigestBackendZ3AuditPackageArtifactOutputError::Serialization(
        error.to_string(),
    )
}

pub fn build_gateway_formal_tiny_digest_backend_z3_audit_package_review(
    manifest: &GatewayFormalTinyDigestBackendZ3AuditPackageArtifactManifest,
    input: &GatewayFormalTinyDigestBackendZ3AuditPackageReviewInput,
) -> Result<
    GatewayFormalTinyDigestBackendZ3AuditPackageReview,
    GatewayFormalTinyDigestBackendZ3AuditPackageReviewValidation,
> {
    let validation =
        validate_gateway_formal_tiny_digest_backend_z3_audit_package_review_input(manifest, input);
    if !validation.valid {
        return Err(validation);
    }
    Ok(GatewayFormalTinyDigestBackendZ3AuditPackageReview {
        schema_version: GATEWAY_FORMAL_TINY_DIGEST_BACKEND_Z3_AUDIT_PACKAGE_REVIEW_SCHEMA_VERSION
            .to_owned(),
        review_id: input.review_id.clone(),
        state_slice: GATEWAY_FORMAL_TINY_DIGEST_BACKEND_Z3_AUDIT_PACKAGE_REVIEW_STATE_SLICE
            .to_owned(),
        reviewed_at_unix: input.reviewed_at_unix,
        review_input_digest: input.digest(),
        materialized_package_manifest_digest: manifest.digest(),
        phase431_output_request_digest: manifest.request_digest,
        phase429_review_digest: manifest.review_digest,
        phase427_serialization_preview_digest: manifest.serialization_preview_digest,
        phase425_audit_package_digest: manifest.audit_package_digest,
        phase423_review_record_digest: manifest.review_record_digest,
        phase421_metadata_digest: manifest.metadata_digest,
        phase405_output_manifest_digest: manifest.phase405_output_manifest_digest,
        phase404_execution_digest: manifest.phase404_execution_digest,
        declared_file_list_digest:
            gateway_formal_tiny_digest_backend_z3_audit_package_review_declared_file_list_digest(
                manifest,
            ),
        declared_sidecar_list_digest:
            gateway_formal_tiny_digest_backend_z3_audit_package_review_declared_sidecar_list_digest(
                manifest,
            ),
        declared_file_digest_map_digest:
            gateway_formal_tiny_digest_backend_z3_audit_package_review_declared_file_digest_map_digest(
                manifest,
            ),
        digest_index_digest:
            gateway_formal_tiny_digest_backend_z3_audit_package_review_declared_digest(
                manifest,
                "tiny-z3-audit-package/digests.json",
            ),
        claim_boundary_file_digest:
            gateway_formal_tiny_digest_backend_z3_audit_package_review_declared_digest(
                manifest,
                "tiny-z3-audit-package/claim-boundary.txt",
            ),
        reviewer_policy_id: input.reviewer_policy_id.clone(),
        reviewer_decision_id: input.reviewer_decision_id.clone(),
        reviewer_decision_at_unix: input.reviewer_decision_at_unix,
        current_accepted_append_blockers_digest: manifest.current_accepted_append_blockers_digest,
        review_label: input.review_label.clone(),
        review_summary: input.review_summary.clone(),
        previous_promotion_state: "tiny_z3_materialized_audit_package_artifact".to_owned(),
        promotion_state: "tiny_z3_materialized_audit_package_review_metadata".to_owned(),
        next_required_state: "tiny_z3_accepted_evidence_proposal_still_blocked".to_owned(),
        claim_boundary: gateway_formal_tiny_digest_backend_z3_audit_package_review_claim_boundary(
        ),
        explicit_nonclaims: input.explicit_nonclaims.clone(),
        creates_accepted_evidence: false,
        changes_accepted_append_policy: false,
        creates_level2_evidence: false,
        populates_score_axes: false,
        proof_artifact_created: false,
        checker_transcript_created: false,
        solver_certificate_created: false,
        semantic_correctness_claimed: false,
        production_readiness_claimed: false,
        sota_claimed: false,
        breakthrough_claimed: false,
        full_security_claimed: false,
        grants_authority: false,
    })
}

pub fn validate_gateway_formal_tiny_digest_backend_z3_audit_package_review_input(
    manifest: &GatewayFormalTinyDigestBackendZ3AuditPackageArtifactManifest,
    input: &GatewayFormalTinyDigestBackendZ3AuditPackageReviewInput,
) -> GatewayFormalTinyDigestBackendZ3AuditPackageReviewValidation {
    let mut issues = Vec::new();
    if input.schema_version
        != GATEWAY_FORMAL_TINY_DIGEST_BACKEND_Z3_AUDIT_PACKAGE_REVIEW_SCHEMA_VERSION
    {
        issues.push(GatewayFormalTinyDigestBackendZ3AuditPackageReviewIssue::InvalidSchemaVersion);
    }
    if !is_single_segment_id(&input.review_id) {
        issues.push(GatewayFormalTinyDigestBackendZ3AuditPackageReviewIssue::InvalidReviewId);
    }
    if !is_single_segment_id(&input.reviewer_policy_id) {
        issues
            .push(GatewayFormalTinyDigestBackendZ3AuditPackageReviewIssue::InvalidReviewerPolicyId);
    }
    if !is_single_segment_id(&input.reviewer_decision_id) {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AuditPackageReviewIssue::InvalidReviewerDecisionId,
        );
    }
    if input.reviewed_at_unix == 0 {
        issues.push(GatewayFormalTinyDigestBackendZ3AuditPackageReviewIssue::MissingReviewedAt);
    }
    if input.reviewer_decision_at_unix == 0 {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AuditPackageReviewIssue::MissingReviewerDecisionTimestamp,
        );
    }
    validate_gateway_formal_tiny_digest_backend_z3_audit_package_review_digests(input, &mut issues);
    validate_gateway_formal_tiny_digest_backend_z3_audit_package_review_manifest(
        manifest,
        input,
        &mut issues,
    );
    validate_gateway_formal_tiny_digest_backend_z3_audit_package_review_policy(input, &mut issues);
    GatewayFormalTinyDigestBackendZ3AuditPackageReviewValidation {
        valid: issues.is_empty(),
        issues,
    }
}

fn validate_gateway_formal_tiny_digest_backend_z3_audit_package_review_digests(
    input: &GatewayFormalTinyDigestBackendZ3AuditPackageReviewInput,
    issues: &mut Vec<GatewayFormalTinyDigestBackendZ3AuditPackageReviewIssue>,
) {
    for (label, digest) in [
        (
            "materialized_package_manifest_digest",
            input.materialized_package_manifest_digest,
        ),
        (
            "phase431_output_request_digest",
            input.phase431_output_request_digest,
        ),
        ("phase429_review_digest", input.phase429_review_digest),
        (
            "phase427_serialization_preview_digest",
            input.phase427_serialization_preview_digest,
        ),
        (
            "phase425_audit_package_digest",
            input.phase425_audit_package_digest,
        ),
        (
            "phase423_review_record_digest",
            input.phase423_review_record_digest,
        ),
        ("phase421_metadata_digest", input.phase421_metadata_digest),
        (
            "phase405_output_manifest_digest",
            input.phase405_output_manifest_digest,
        ),
        ("phase404_execution_digest", input.phase404_execution_digest),
        ("declared_file_list_digest", input.declared_file_list_digest),
        (
            "declared_sidecar_list_digest",
            input.declared_sidecar_list_digest,
        ),
        (
            "declared_file_digest_map_digest",
            input.declared_file_digest_map_digest,
        ),
        ("digest_index_digest", input.digest_index_digest),
        (
            "claim_boundary_file_digest",
            input.claim_boundary_file_digest,
        ),
        ("explicit_nonclaims_digest", input.explicit_nonclaims_digest),
        (
            "current_accepted_append_blockers_digest",
            input.current_accepted_append_blockers_digest,
        ),
    ] {
        if digest == Hash([0; 32]) {
            issues.push(
                GatewayFormalTinyDigestBackendZ3AuditPackageReviewIssue::MissingDigest(
                    label.to_owned(),
                ),
            );
        }
    }
}

fn validate_gateway_formal_tiny_digest_backend_z3_audit_package_review_manifest(
    manifest: &GatewayFormalTinyDigestBackendZ3AuditPackageArtifactManifest,
    input: &GatewayFormalTinyDigestBackendZ3AuditPackageReviewInput,
    issues: &mut Vec<GatewayFormalTinyDigestBackendZ3AuditPackageReviewIssue>,
) {
    if input.materialized_package_manifest_digest != manifest.digest()
        || input.phase431_output_request_digest != manifest.request_digest
        || input.phase429_review_digest != manifest.review_digest
        || input.phase427_serialization_preview_digest != manifest.serialization_preview_digest
        || input.phase425_audit_package_digest != manifest.audit_package_digest
        || input.phase423_review_record_digest != manifest.review_record_digest
        || input.phase421_metadata_digest != manifest.metadata_digest
        || input.phase405_output_manifest_digest != manifest.phase405_output_manifest_digest
        || input.phase404_execution_digest != manifest.phase404_execution_digest
        || input.current_accepted_append_blockers_digest
            != manifest.current_accepted_append_blockers_digest
    {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AuditPackageReviewIssue::MaterializedPackageManifestDrift,
        );
    }
    if manifest.schema_version
        != GATEWAY_FORMAL_TINY_DIGEST_BACKEND_Z3_AUDIT_PACKAGE_ARTIFACT_SCHEMA_VERSION
        || manifest.state_slice
            != GATEWAY_FORMAL_TINY_DIGEST_BACKEND_Z3_AUDIT_PACKAGE_ARTIFACT_STATE_SLICE
        || manifest.claim_boundary
            != gateway_formal_tiny_digest_backend_z3_audit_package_artifact_claim_boundary()
        || manifest.creates_accepted_evidence
        || manifest.changes_accepted_append_policy
        || manifest.creates_level2_evidence
        || manifest.populates_score_axes
        || manifest.proof_artifact_created
        || manifest.checker_transcript_created
        || manifest.solver_certificate_created
        || manifest.semantic_correctness_claimed
        || manifest.production_readiness_claimed
        || manifest.sota_claimed
        || manifest.breakthrough_claimed
        || manifest.full_security_claimed
        || manifest.grants_authority
    {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AuditPackageReviewIssue::MaterializedPackageStateMismatch,
        );
    }
    if manifest.declared_files
        != gateway_formal_tiny_digest_backend_z3_audit_package_artifact_declared_files()
        || manifest.declared_sidecars
            != gateway_formal_tiny_digest_backend_z3_audit_package_artifact_declared_sidecars()
        || input.declared_file_list_digest
            != gateway_formal_tiny_digest_backend_z3_audit_package_review_declared_file_list_digest(
                manifest,
            )
        || input.declared_sidecar_list_digest
            != gateway_formal_tiny_digest_backend_z3_audit_package_review_declared_sidecar_list_digest(
                manifest,
            )
        || input.declared_file_digest_map_digest
            != gateway_formal_tiny_digest_backend_z3_audit_package_review_declared_file_digest_map_digest(
                manifest,
            )
        || input.digest_index_digest
            != gateway_formal_tiny_digest_backend_z3_audit_package_review_declared_digest(
                manifest,
                "tiny-z3-audit-package/digests.json",
            )
        || input.claim_boundary_file_digest
            != gateway_formal_tiny_digest_backend_z3_audit_package_review_declared_digest(
                manifest,
                "tiny-z3-audit-package/claim-boundary.txt",
            )
    {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AuditPackageReviewIssue::DeclaredArtifactDigestDrift,
        );
    }
}

fn validate_gateway_formal_tiny_digest_backend_z3_audit_package_review_policy(
    input: &GatewayFormalTinyDigestBackendZ3AuditPackageReviewInput,
    issues: &mut Vec<GatewayFormalTinyDigestBackendZ3AuditPackageReviewIssue>,
) {
    let blockers = gateway_formal_tiny_digest_backend_z3_accepted_handoff_current_blockers();
    if input.current_accepted_append_blockers_digest
        != hash_tagged(
            "hsai-agent-admission:gateway-formal-tiny-digest-backend-z3-accepted-handoff-current-blockers:v1",
            &blockers,
        )
    {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AuditPackageReviewIssue::AcceptedAppendBlockerMismatch,
        );
    }
    let nonclaims = gateway_formal_tiny_digest_backend_z3_audit_package_review_required_nonclaims();
    if input.explicit_nonclaims != nonclaims
        || input.explicit_nonclaims_digest
            != hash_tagged(
                "hsai-agent-admission:gateway-formal-tiny-digest-backend-z3-audit-package-review-nonclaims:v1",
                &nonclaims,
            )
    {
        issues.push(GatewayFormalTinyDigestBackendZ3AuditPackageReviewIssue::NonclaimMismatch);
    }
    if gateway_formal_real_command_lane_local_review_audit_package_text_promotes(
        &input.review_summary,
    ) {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AuditPackageReviewIssue::ReviewSummaryPromotionClaim,
        );
    }
    if input.accepted_evidence_mutation_requested
        || input.accepted_append_policy_change_requested
        || input.accepted_formal_evidence_created
        || input.creates_level2_evidence
        || input.populates_score_axes
        || input.proof_artifact_promoted
        || input.checker_transcript_promoted
        || input.solver_certificate_promoted
        || input.benchmark_or_sota_comparison_claimed
        || input.semantic_correctness_claimed
        || input.production_readiness_claimed
        || input.sota_claimed
        || input.breakthrough_claimed
        || input.full_security_claimed
        || input.action_authority_claimed
    {
        issues.push(GatewayFormalTinyDigestBackendZ3AuditPackageReviewIssue::PromotionAttempt);
    }
}

