pub fn validate_gateway_formal_tiny_digest_backend_z3_accepted_append_decision_candidate_input(
    review: &GatewayFormalTinyDigestBackendZ3AcceptedAppendPreflightReview,
    input: &GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionCandidateInput,
) -> GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionCandidateValidation {
    let mut issues = Vec::new();
    if input.schema_version
        != GATEWAY_FORMAL_TINY_DIGEST_BACKEND_Z3_ACCEPTED_APPEND_DECISION_CANDIDATE_SCHEMA_VERSION
    {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionCandidateIssue::InvalidSchemaVersion,
        );
    }
    if !is_single_segment_id(&input.accepted_append_decision_candidate_id) {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionCandidateIssue::InvalidAcceptedAppendDecisionCandidateId,
        );
    }
    if !is_single_segment_id(&input.reviewer_policy_id) {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionCandidateIssue::InvalidReviewerPolicyId,
        );
    }
    if !is_single_segment_id(&input.reviewer_decision_id) {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionCandidateIssue::InvalidReviewerDecisionId,
        );
    }
    if !is_single_segment_id(&input.proposal_policy_id) {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionCandidateIssue::InvalidProposalPolicyId,
        );
    }
    if !is_single_segment_id(&input.proposal_candidate_id) {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionCandidateIssue::InvalidProposalCandidateId,
        );
    }
    if !is_single_segment_id(&input.proposal_review_id) {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionCandidateIssue::InvalidProposalReviewId,
        );
    }
    if !is_single_segment_id(&input.append_preflight_id) {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionCandidateIssue::InvalidAppendPreflightId,
        );
    }
    if !is_single_segment_id(&input.append_preflight_review_id) {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionCandidateIssue::InvalidAppendPreflightReviewId,
        );
    }
    if input.candidate_created_at_unix == 0 {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionCandidateIssue::MissingCandidateTimestamp,
        );
    }
    validate_gateway_formal_tiny_digest_backend_z3_accepted_append_decision_candidate_digests(
        input,
        &mut issues,
    );
    validate_gateway_formal_tiny_digest_backend_z3_accepted_append_decision_candidate_review(
        review,
        input,
        &mut issues,
    );
    validate_gateway_formal_tiny_digest_backend_z3_accepted_append_decision_candidate_policy(
        input,
        &mut issues,
    );
    GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionCandidateValidation {
        valid: issues.is_empty(),
        issues,
    }
}

fn validate_gateway_formal_tiny_digest_backend_z3_accepted_append_decision_candidate_digests(
    input: &GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionCandidateInput,
    issues: &mut Vec<GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionCandidateIssue>,
) {
    for (label, digest) in [
        ("phase441_review_digest", input.phase441_review_digest),
        (
            "phase441_review_input_digest",
            input.phase441_review_input_digest,
        ),
        ("phase439_preflight_digest", input.phase439_preflight_digest),
        (
            "phase439_preflight_input_digest",
            input.phase439_preflight_input_digest,
        ),
        ("phase437_review_digest", input.phase437_review_digest),
        (
            "phase437_review_input_digest",
            input.phase437_review_input_digest,
        ),
        ("phase435_candidate_digest", input.phase435_candidate_digest),
        (
            "phase435_candidate_input_digest",
            input.phase435_candidate_input_digest,
        ),
        ("phase433_review_digest", input.phase433_review_digest),
        (
            "phase431_materialized_manifest_digest",
            input.phase431_materialized_manifest_digest,
        ),
        ("phase429_review_digest", input.phase429_review_digest),
        (
            "phase427_serialization_preview_digest",
            input.phase427_serialization_preview_digest,
        ),
        (
            "phase425_audit_package_digest",
            input.phase425_audit_package_digest,
        ),
        (
            "phase423_review_record_digest",
            input.phase423_review_record_digest,
        ),
        ("phase421_metadata_digest", input.phase421_metadata_digest),
        (
            "phase405_output_manifest_digest",
            input.phase405_output_manifest_digest,
        ),
        ("phase404_execution_digest", input.phase404_execution_digest),
        (
            "declared_file_digest_map_digest",
            input.declared_file_digest_map_digest,
        ),
        ("explicit_nonclaims_digest", input.explicit_nonclaims_digest),
        (
            "current_accepted_append_blockers_digest",
            input.current_accepted_append_blockers_digest,
        ),
    ] {
        if digest == Hash([0; 32]) {
            issues.push(
                GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionCandidateIssue::MissingDigest(
                    label.to_owned(),
                ),
            );
        }
    }
}

