pub fn validate_gateway_formal_tiny_digest_backend_z3_accepted_append_decision_quarantine_resolution_escalation_terminal_review_closure_blocker_input(
    review: &GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionQuarantineResolutionEscalationTerminalBlockerReview,
    input: &GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerInput,
) -> GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerValidation{
    let mut issues = Vec::new();
    if input.schema_version
        != GATEWAY_FORMAL_TINY_DIGEST_BACKEND_Z3_ACCEPTED_APPEND_DECISION_QUARANTINE_RESOLUTION_ESCALATION_TERMINAL_REVIEW_CLOSURE_BLOCKER_SCHEMA_VERSION
    {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerIssue::InvalidSchemaVersion,
        );
    }
    if !is_single_segment_id(&input.closure_blocker_id) {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerIssue::InvalidClosureBlockerId,
        );
    }
    if !is_single_segment_id(&input.closure_policy_id) {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerIssue::InvalidClosurePolicyId,
        );
    }
    if !is_single_segment_id(&input.closure_decision_id) {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerIssue::InvalidClosureDecisionId,
        );
    }
    if input.closure_decision_at_unix == 0 {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerIssue::MissingClosureDecisionTimestamp,
        );
    }
    for (label, digest) in &input.digest_bindings {
        if *digest == Hash([0; 32]) {
            issues.push(
                GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerIssue::MissingDigest(
                    label.clone(),
                ),
            );
        }
    }
    let expected_digests =
        gateway_formal_tiny_digest_backend_z3_accepted_append_decision_quarantine_resolution_escalation_terminal_review_closure_blocker_digest_bindings(
            review,
        );
    if input.digest_bindings != expected_digests {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerIssue::DigestBindingMismatch,
        );
    }
    let expected_ids =
        gateway_formal_tiny_digest_backend_z3_accepted_append_decision_quarantine_resolution_escalation_terminal_review_closure_blocker_id_bindings(
            review,
            &input.closure_blocker_id,
            &input.closure_policy_id,
            &input.closure_decision_id,
        );
    for (label, value) in &input.id_bindings {
        if !is_single_segment_id(value) {
            issues.push(
                GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerIssue::InvalidIdBinding(
                    label.clone(),
                ),
            );
        }
    }
    if input.id_bindings != expected_ids {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerIssue::IdBindingMismatch,
        );
    }
    let expected_labels =
        gateway_formal_tiny_digest_backend_z3_accepted_append_decision_quarantine_resolution_escalation_terminal_review_closure_blocker_label_bindings(
            review,
            &input.closure_blocker_label,
        );
    if input.label_bindings != expected_labels {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerIssue::LabelBindingMismatch,
        );
    }
    if review.schema_version
        != GATEWAY_FORMAL_TINY_DIGEST_BACKEND_Z3_ACCEPTED_APPEND_DECISION_QUARANTINE_RESOLUTION_ESCALATION_TERMINAL_BLOCKER_REVIEW_SCHEMA_VERSION
        || review.state_slice
            != GATEWAY_FORMAL_TINY_DIGEST_BACKEND_Z3_ACCEPTED_APPEND_DECISION_QUARANTINE_RESOLUTION_ESCALATION_TERMINAL_BLOCKER_REVIEW_STATE_SLICE
        || review.promotion_state
            != "tiny_z3_accepted_append_decision_quarantine_resolution_escalation_terminal_blocker_review_metadata"
        || review.next_required_state != "tiny_z3_accepted_append_decision_still_blocked"
        || review.claim_boundary
            != gateway_formal_tiny_digest_backend_z3_accepted_append_decision_quarantine_resolution_escalation_terminal_blocker_review_claim_boundary()
        || review.makes_accepted_append_decision
        || review.creates_accepted_evidence
        || review.changes_accepted_append_policy
        || review.creates_level2_evidence
        || review.populates_score_axes
        || review.proof_artifact_created
        || review.checker_transcript_created
        || review.solver_certificate_created
        || review.semantic_correctness_claimed
        || review.production_readiness_claimed
        || review.sota_claimed
        || review.breakthrough_claimed
        || review.full_security_claimed
        || review.grants_authority
    {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerIssue::Phase465TerminalBlockerReviewStateMismatch,
        );
    }
    let blockers = gateway_formal_tiny_digest_backend_z3_accepted_handoff_current_blockers();
    if input.current_accepted_append_blockers_digest
        != hash_tagged(
            "hsai-agent-admission:gateway-formal-tiny-digest-backend-z3-accepted-handoff-current-blockers:v1",
            &blockers,
        )
    {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerIssue::AcceptedAppendBlockerMismatch,
        );
    }
    let nonclaims =
        gateway_formal_tiny_digest_backend_z3_accepted_append_decision_quarantine_resolution_escalation_terminal_review_closure_blocker_required_nonclaims();
    if input.explicit_nonclaims != nonclaims
        || input.explicit_nonclaims_digest
            != hash_tagged(
                "hsai-agent-admission:gateway-formal-tiny-digest-backend-z3-accepted-append-decision-quarantine-resolution-escalation-terminal-review-closure-blocker-nonclaims:v1",
                &nonclaims,
            )
    {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerIssue::NonclaimMismatch,
        );
    }
    if gateway_formal_real_command_lane_local_review_audit_package_text_promotes(
        &input.closure_summary,
    ) {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerIssue::ClosureSummaryPromotionClaim,
        );
    }
    if input.accepted_append_decision_requested
        || input.accepted_evidence_mutation_requested
        || input.accepted_append_policy_change_requested
        || input.accepted_formal_evidence_created
        || input.creates_level2_evidence
        || input.populates_score_axes
        || input.proof_artifact_promoted
        || input.checker_transcript_promoted
        || input.solver_certificate_promoted
        || input.benchmark_or_sota_comparison_claimed
        || input.semantic_correctness_claimed
        || input.production_readiness_claimed
        || input.sota_claimed
        || input.breakthrough_claimed
        || input.full_security_claimed
        || input.action_authority_claimed
    {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerIssue::PromotionAttempt,
        );
    }
    GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerValidation {
        valid: issues.is_empty(),
        issues,
    }
}

