pub fn validate_gateway_formal_tiny_digest_backend_z3_accepted_append_decision_quarantine_resolution_escalation_terminal_review_closure_blocker_review_terminal_closure_review_input(
    terminal_closure: &GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosure,
    input: &GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureReviewInput,
) -> GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureReviewValidation{
    let mut issues = Vec::new();
    if input.schema_version
        != GATEWAY_FORMAL_TINY_DIGEST_BACKEND_Z3_ACCEPTED_APPEND_DECISION_QUARANTINE_RESOLUTION_ESCALATION_TERMINAL_REVIEW_CLOSURE_BLOCKER_REVIEW_TERMINAL_CLOSURE_REVIEW_SCHEMA_VERSION
    {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureReviewIssue::InvalidSchemaVersion,
        );
    }
    if !is_single_segment_id(&input.terminal_closure_review_id) {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureReviewIssue::InvalidTerminalClosureReviewId,
        );
    }
    if !is_single_segment_id(&input.terminal_closure_review_policy_id) {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureReviewIssue::InvalidTerminalClosureReviewPolicyId,
        );
    }
    if !is_single_segment_id(&input.terminal_closure_review_decision_id) {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureReviewIssue::InvalidTerminalClosureReviewDecisionId,
        );
    }
    if input.terminal_closure_review_decision_at_unix == 0 {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureReviewIssue::MissingTerminalClosureReviewDecisionTimestamp,
        );
    }
    let expected_digests =
        gateway_formal_tiny_digest_backend_z3_accepted_append_decision_quarantine_resolution_escalation_terminal_review_closure_blocker_review_terminal_closure_review_digest_bindings(
            terminal_closure,
        );
    for (label, digest) in &input.digest_bindings {
        if *digest == Hash([0; 32]) {
            issues.push(
                GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureReviewIssue::MissingDigest(
                    label.clone(),
                ),
            );
        }
    }
    if input.digest_bindings != expected_digests {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureReviewIssue::DigestBindingMismatch,
        );
    }
    let expected_ids =
        gateway_formal_tiny_digest_backend_z3_accepted_append_decision_quarantine_resolution_escalation_terminal_review_closure_blocker_review_terminal_closure_review_id_bindings(
            terminal_closure,
            &input.terminal_closure_review_id,
            &input.terminal_closure_review_policy_id,
            &input.terminal_closure_review_decision_id,
        );
    for (label, value) in &input.id_bindings {
        if !is_single_segment_id(value) {
            issues.push(
                GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureReviewIssue::InvalidIdBinding(
                    label.clone(),
                ),
            );
        }
    }
    if input.id_bindings != expected_ids {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureReviewIssue::IdBindingMismatch,
        );
    }
    let expected_labels =
        gateway_formal_tiny_digest_backend_z3_accepted_append_decision_quarantine_resolution_escalation_terminal_review_closure_blocker_review_terminal_closure_review_label_bindings(
            terminal_closure,
            &input.terminal_closure_review_label,
        );
    if input.label_bindings != expected_labels
        || input.inherited_terminal_closure_label != terminal_closure.terminal_closure_label
    {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureReviewIssue::LabelBindingMismatch,
        );
    }
    if terminal_closure.schema_version
        != GATEWAY_FORMAL_TINY_DIGEST_BACKEND_Z3_ACCEPTED_APPEND_DECISION_QUARANTINE_RESOLUTION_ESCALATION_TERMINAL_REVIEW_CLOSURE_BLOCKER_REVIEW_TERMINAL_CLOSURE_SCHEMA_VERSION
        || terminal_closure.state_slice
            != GATEWAY_FORMAL_TINY_DIGEST_BACKEND_Z3_ACCEPTED_APPEND_DECISION_QUARANTINE_RESOLUTION_ESCALATION_TERMINAL_REVIEW_CLOSURE_BLOCKER_REVIEW_TERMINAL_CLOSURE_STATE_SLICE
        || terminal_closure.promotion_state
            != "tiny_z3_accepted_append_decision_quarantine_resolution_escalation_terminal_review_closure_blocker_review_terminal_closure_metadata"
        || terminal_closure.next_required_state
            != "tiny_z3_accepted_append_decision_terminally_closed_still_blocked"
        || terminal_closure.claim_boundary
            != gateway_formal_tiny_digest_backend_z3_accepted_append_decision_quarantine_resolution_escalation_terminal_review_closure_blocker_review_terminal_closure_claim_boundary()
        || terminal_closure.makes_accepted_append_decision
        || terminal_closure.creates_accepted_evidence
        || terminal_closure.changes_accepted_append_policy
        || terminal_closure.creates_level2_evidence
        || terminal_closure.populates_score_axes
        || terminal_closure.proof_artifact_created
        || terminal_closure.checker_transcript_created
        || terminal_closure.solver_certificate_created
        || terminal_closure.semantic_correctness_claimed
        || terminal_closure.production_readiness_claimed
        || terminal_closure.sota_claimed
        || terminal_closure.breakthrough_claimed
        || terminal_closure.full_security_claimed
        || terminal_closure.grants_authority
    {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureReviewIssue::Phase471TerminalClosureStateMismatch,
        );
    }
    let blockers = gateway_formal_tiny_digest_backend_z3_accepted_handoff_current_blockers();
    if input.current_accepted_append_blockers_digest
        != hash_tagged(
            "hsai-agent-admission:gateway-formal-tiny-digest-backend-z3-accepted-handoff-current-blockers:v1",
            &blockers,
        )
    {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureReviewIssue::AcceptedAppendBlockerMismatch,
        );
    }
    let nonclaims =
        gateway_formal_tiny_digest_backend_z3_accepted_append_decision_quarantine_resolution_escalation_terminal_review_closure_blocker_review_terminal_closure_review_required_nonclaims();
    if input.explicit_nonclaims != nonclaims
        || input.explicit_nonclaims_digest
            != hash_tagged(
                "hsai-agent-admission:gateway-formal-tiny-digest-backend-z3-accepted-append-decision-quarantine-resolution-escalation-terminal-review-closure-blocker-review-terminal-closure-review-nonclaims:v1",
                &nonclaims,
            )
    {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureReviewIssue::NonclaimMismatch,
        );
    }
    if gateway_formal_real_command_lane_local_review_audit_package_text_promotes(
        &input.terminal_closure_review_summary,
    ) {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureReviewIssue::TerminalClosureReviewSummaryPromotionClaim,
        );
    }
    if input.accepted_append_decision_requested
        || input.accepted_evidence_mutation_requested
        || input.accepted_append_policy_change_requested
        || input.accepted_formal_evidence_created
        || input.creates_level2_evidence
        || input.populates_score_axes
        || input.proof_artifact_promoted
        || input.checker_transcript_promoted
        || input.solver_certificate_promoted
        || input.benchmark_or_sota_comparison_claimed
        || input.semantic_correctness_claimed
        || input.production_readiness_claimed
        || input.sota_claimed
        || input.breakthrough_claimed
        || input.full_security_claimed
        || input.action_authority_claimed
    {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureReviewIssue::PromotionAttempt,
        );
    }
    GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureReviewValidation {
        valid: issues.is_empty(),
        issues,
    }
}

