pub fn validate_gateway_formal_real_command_lane_accepted_append_decision_quarantine_review_input(
    quarantine: &GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantine,
    input: &GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineReviewInput,
) -> GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineReviewValidation {
    let mut issues = Vec::new();
    if input.schema_version
        != GATEWAY_FORMAL_REAL_COMMAND_LANE_ACCEPTED_APPEND_DECISION_QUARANTINE_REVIEW_SCHEMA_VERSION
    {
        issues.push(
            GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineReviewIssue::InvalidSchemaVersion,
        );
    }
    if !is_single_segment_id(&input.accepted_append_decision_quarantine_review_id) {
        issues.push(
            GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineReviewIssue::InvalidAcceptedAppendDecisionQuarantineReviewId,
        );
    }
    if !is_single_segment_id(&input.quarantine_policy_id) {
        issues.push(
            GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineReviewIssue::InvalidQuarantinePolicyId,
        );
    }
    if !is_single_segment_id(&input.quarantine_decision_id) {
        issues.push(
            GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineReviewIssue::InvalidQuarantineDecisionId,
        );
    }
    if !is_single_segment_id(&input.reviewer_policy_id) {
        issues.push(
            GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineReviewIssue::InvalidReviewerPolicyId,
        );
    }
    if !is_single_segment_id(&input.reviewer_decision_id) {
        issues.push(
            GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineReviewIssue::InvalidReviewerDecisionId,
        );
    }
    if !is_single_segment_id(&input.proposal_policy_id) {
        issues.push(
            GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineReviewIssue::InvalidProposalPolicyId,
        );
    }
    if !is_single_segment_id(&input.proposal_candidate_id) {
        issues.push(
            GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineReviewIssue::InvalidProposalCandidateId,
        );
    }
    if !is_single_segment_id(&input.proposal_review_id) {
        issues.push(
            GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineReviewIssue::InvalidProposalReviewId,
        );
    }
    if !is_single_segment_id(&input.append_preflight_id) {
        issues.push(
            GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineReviewIssue::InvalidAppendPreflightId,
        );
    }
    if !is_single_segment_id(&input.append_preflight_review_id) {
        issues.push(
            GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineReviewIssue::InvalidAppendPreflightReviewId,
        );
    }
    if !is_single_segment_id(&input.accepted_append_decision_candidate_id) {
        issues.push(
            GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineReviewIssue::InvalidAcceptedAppendDecisionCandidateId,
        );
    }
    if !is_single_segment_id(&input.accepted_append_decision_candidate_review_id) {
        issues.push(
            GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineReviewIssue::InvalidAcceptedAppendDecisionCandidateReviewId,
        );
    }
    if !is_single_segment_id(&input.accepted_append_decision_blocker_id) {
        issues.push(
            GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineReviewIssue::InvalidAcceptedAppendDecisionBlockerId,
        );
    }
    if !is_single_segment_id(&input.accepted_append_decision_blocker_review_id) {
        issues.push(
            GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineReviewIssue::InvalidAcceptedAppendDecisionBlockerReviewId,
        );
    }
    if !is_single_segment_id(&input.accepted_append_decision_quarantine_id) {
        issues.push(
            GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineReviewIssue::InvalidAcceptedAppendDecisionQuarantineId,
        );
    }
    if input.review_decision_at_unix == 0 {
        issues.push(
            GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineReviewIssue::MissingReviewDecisionTimestamp,
        );
    }
    validate_gateway_formal_real_command_lane_accepted_append_decision_quarantine_review_digests(
        input,
        &mut issues,
    );
    validate_gateway_formal_real_command_lane_accepted_append_decision_quarantine_review_quarantine(
        quarantine,
        input,
        &mut issues,
    );
    validate_gateway_formal_real_command_lane_accepted_append_decision_quarantine_review_policy(
        input,
        &mut issues,
    );
    GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineReviewValidation {
        valid: issues.is_empty(),
        issues,
    }
}

fn validate_gateway_formal_real_command_lane_accepted_append_decision_quarantine_review_digests(
    input: &GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineReviewInput,
    issues: &mut Vec<GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineReviewIssue>,
) {
    for (label, digest) in [
        (
            "phase373_quarantine_digest",
            input.phase373_quarantine_digest,
        ),
        (
            "phase373_quarantine_input_digest",
            input.phase373_quarantine_input_digest,
        ),
        (
            "phase371_blocker_review_digest",
            input.phase371_blocker_review_digest,
        ),
        (
            "phase371_blocker_review_input_digest",
            input.phase371_blocker_review_input_digest,
        ),
        ("phase369_blocker_digest", input.phase369_blocker_digest),
        (
            "phase369_blocker_input_digest",
            input.phase369_blocker_input_digest,
        ),
        ("phase367_review_digest", input.phase367_review_digest),
        (
            "phase367_review_input_digest",
            input.phase367_review_input_digest,
        ),
        ("phase365_candidate_digest", input.phase365_candidate_digest),
        (
            "phase365_candidate_input_digest",
            input.phase365_candidate_input_digest,
        ),
        ("phase363_review_digest", input.phase363_review_digest),
        (
            "phase363_review_input_digest",
            input.phase363_review_input_digest,
        ),
        ("phase361_preflight_digest", input.phase361_preflight_digest),
        (
            "phase361_preflight_input_digest",
            input.phase361_preflight_input_digest,
        ),
        ("phase359_review_digest", input.phase359_review_digest),
        (
            "phase359_review_input_digest",
            input.phase359_review_input_digest,
        ),
        ("phase357_candidate_digest", input.phase357_candidate_digest),
        (
            "phase357_candidate_input_digest",
            input.phase357_candidate_input_digest,
        ),
        ("phase355_review_digest", input.phase355_review_digest),
        (
            "phase353_materialized_manifest_digest",
            input.phase353_materialized_manifest_digest,
        ),
        ("phase351_review_digest", input.phase351_review_digest),
        (
            "phase349_serialization_preview_digest",
            input.phase349_serialization_preview_digest,
        ),
        (
            "phase347_audit_package_digest",
            input.phase347_audit_package_digest,
        ),
        (
            "phase345_review_record_digest",
            input.phase345_review_record_digest,
        ),
        ("phase343_metadata_digest", input.phase343_metadata_digest),
        (
            "declared_file_digest_map_digest",
            input.declared_file_digest_map_digest,
        ),
        ("explicit_nonclaims_digest", input.explicit_nonclaims_digest),
        (
            "current_accepted_append_blockers_digest",
            input.current_accepted_append_blockers_digest,
        ),
    ] {
        if digest == Hash([0; 32]) {
            issues.push(
                GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineReviewIssue::MissingDigest(
                    label.to_owned(),
                ),
            );
        }
    }
}

fn validate_gateway_formal_real_command_lane_accepted_append_decision_quarantine_review_quarantine(
    quarantine: &GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantine,
    input: &GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineReviewInput,
    issues: &mut Vec<GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineReviewIssue>,
) {
    if input.phase373_quarantine_digest != quarantine.digest()
        || input.phase373_quarantine_input_digest != quarantine.quarantine_input_digest
        || input.phase371_blocker_review_digest != quarantine.phase371_blocker_review_digest
        || input.phase371_blocker_review_input_digest
            != quarantine.phase371_blocker_review_input_digest
        || input.phase369_blocker_digest != quarantine.phase369_blocker_digest
        || input.phase369_blocker_input_digest != quarantine.phase369_blocker_input_digest
        || input.phase367_review_digest != quarantine.phase367_review_digest
        || input.phase367_review_input_digest != quarantine.phase367_review_input_digest
        || input.phase365_candidate_digest != quarantine.phase365_candidate_digest
        || input.phase365_candidate_input_digest != quarantine.phase365_candidate_input_digest
        || input.phase363_review_digest != quarantine.phase363_review_digest
        || input.phase363_review_input_digest != quarantine.phase363_review_input_digest
        || input.phase361_preflight_digest != quarantine.phase361_preflight_digest
        || input.phase361_preflight_input_digest != quarantine.phase361_preflight_input_digest
        || input.phase359_review_digest != quarantine.phase359_review_digest
        || input.phase359_review_input_digest != quarantine.phase359_review_input_digest
        || input.phase357_candidate_digest != quarantine.phase357_candidate_digest
        || input.phase357_candidate_input_digest != quarantine.phase357_candidate_input_digest
        || input.phase355_review_digest != quarantine.phase355_review_digest
        || input.phase353_materialized_manifest_digest
            != quarantine.phase353_materialized_manifest_digest
        || input.phase351_review_digest != quarantine.phase351_review_digest
        || input.phase349_serialization_preview_digest
            != quarantine.phase349_serialization_preview_digest
        || input.phase347_audit_package_digest != quarantine.phase347_audit_package_digest
        || input.phase345_review_record_digest != quarantine.phase345_review_record_digest
        || input.phase343_metadata_digest != quarantine.phase343_metadata_digest
        || input.declared_file_digest_map_digest != quarantine.declared_file_digest_map_digest
        || input.current_accepted_append_blockers_digest
            != quarantine.current_accepted_append_blockers_digest
        || input.proposal_candidate_id != quarantine.proposal_candidate_id
        || input.proposal_policy_id != quarantine.proposal_policy_id
        || input.proposal_review_id != quarantine.proposal_review_id
        || input.append_preflight_id != quarantine.append_preflight_id
        || input.append_preflight_review_id != quarantine.append_preflight_review_id
        || input.accepted_append_decision_candidate_id
            != quarantine.accepted_append_decision_candidate_id
        || input.accepted_append_decision_candidate_review_id
            != quarantine.accepted_append_decision_candidate_review_id
        || input.accepted_append_decision_blocker_id
            != quarantine.accepted_append_decision_blocker_id
        || input.accepted_append_decision_blocker_review_id
            != quarantine.accepted_append_decision_blocker_review_id
        || input.accepted_append_decision_quarantine_id
            != quarantine.accepted_append_decision_quarantine_id
        || input.quarantine_policy_id != quarantine.quarantine_policy_id
        || input.quarantine_decision_id != quarantine.quarantine_decision_id
        || input.candidate_disposition != quarantine.candidate_disposition
        || input.candidate_review_label != quarantine.candidate_review_label
        || input.blocker_label != quarantine.blocker_label
        || input.blocker_review_label != quarantine.blocker_review_label
        || input.quarantine_label != quarantine.quarantine_label
    {
        issues.push(
            GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineReviewIssue::Phase373QuarantineDigestDrift,
        );
    }
    if quarantine.schema_version
        != GATEWAY_FORMAL_REAL_COMMAND_LANE_ACCEPTED_APPEND_DECISION_QUARANTINE_SCHEMA_VERSION
        || quarantine.state_slice
            != GATEWAY_FORMAL_REAL_COMMAND_LANE_ACCEPTED_APPEND_DECISION_QUARANTINE_STATE_SLICE
        || quarantine.promotion_state != "local_accepted_append_decision_quarantine_metadata"
        || quarantine.next_required_state != "accepted_append_decision_still_blocked"
        || quarantine.claim_boundary
            != gateway_formal_real_command_lane_accepted_append_decision_quarantine_claim_boundary()
        || quarantine.makes_accepted_append_decision
        || quarantine.creates_accepted_evidence
        || quarantine.changes_accepted_append_policy
        || quarantine.creates_level2_evidence
        || quarantine.populates_score_axes
        || quarantine.proof_artifact_created
        || quarantine.checker_transcript_created
        || quarantine.solver_certificate_created
        || quarantine.semantic_correctness_claimed
        || quarantine.production_readiness_claimed
        || quarantine.sota_claimed
        || quarantine.breakthrough_claimed
        || quarantine.full_security_claimed
        || quarantine.grants_authority
    {
        issues.push(
            GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineReviewIssue::Phase373QuarantineStateMismatch,
        );
    }
}

fn validate_gateway_formal_real_command_lane_accepted_append_decision_quarantine_review_policy(
    input: &GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineReviewInput,
    issues: &mut Vec<GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineReviewIssue>,
) {
    let blockers = gateway_formal_real_command_lane_accepted_handoff_current_blockers();
    if input.current_accepted_append_blockers_digest
        != hash_tagged(
            "hsai-agent-admission:gateway-formal-real-command-lane-accepted-handoff-current-blockers:v1",
            &blockers,
        )
    {
        issues.push(
            GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineReviewIssue::AcceptedAppendBlockerMismatch,
        );
    }
    let nonclaims =
        gateway_formal_real_command_lane_accepted_append_decision_quarantine_review_required_nonclaims();
    if input.explicit_nonclaims != nonclaims
        || input.explicit_nonclaims_digest
            != hash_tagged(
                "hsai-agent-admission:gateway-formal-real-command-lane-accepted-append-decision-quarantine-review-nonclaims:v1",
                &nonclaims,
            )
    {
        issues.push(
            GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineReviewIssue::NonclaimMismatch,
        );
    }
    if gateway_formal_real_command_lane_local_review_audit_package_text_promotes(
        &input.review_summary,
    ) {
        issues.push(
            GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineReviewIssue::ReviewSummaryPromotionClaim,
        );
    }
    if input.accepted_append_decision_requested
        || input.accepted_evidence_mutation_requested
        || input.accepted_append_policy_change_requested
        || input.accepted_formal_evidence_created
        || input.creates_level2_evidence
        || input.populates_score_axes
        || input.proof_artifact_promoted
        || input.checker_transcript_promoted
        || input.solver_certificate_promoted
        || input.benchmark_or_sota_comparison_claimed
        || input.semantic_correctness_claimed
        || input.production_readiness_claimed
        || input.sota_claimed
        || input.breakthrough_claimed
        || input.full_security_claimed
        || input.action_authority_claimed
    {
        issues.push(
            GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineReviewIssue::PromotionAttempt,
        );
    }
}

