fn validate_gateway_formal_real_command_lane_accepted_append_decision_quarantine_resolution_review_policy(
    input: &GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineResolutionReviewInput,
    issues: &mut Vec<
        GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineResolutionReviewIssue,
    >,
) {
    let blockers = gateway_formal_real_command_lane_accepted_handoff_current_blockers();
    if input.current_accepted_append_blockers_digest
        != hash_tagged(
            "hsai-agent-admission:gateway-formal-real-command-lane-accepted-handoff-current-blockers:v1",
            &blockers,
        )
    {
        issues.push(
            GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineResolutionReviewIssue::AcceptedAppendBlockerMismatch,
        );
    }
    let nonclaims =
        gateway_formal_real_command_lane_accepted_append_decision_quarantine_resolution_review_required_nonclaims();
    if input.explicit_nonclaims != nonclaims
        || input.explicit_nonclaims_digest
            != hash_tagged(
                "hsai-agent-admission:gateway-formal-real-command-lane-accepted-append-decision-quarantine-resolution-review-nonclaims:v1",
                &nonclaims,
            )
    {
        issues.push(
            GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineResolutionReviewIssue::NonclaimMismatch,
        );
    }
    if gateway_formal_real_command_lane_local_review_audit_package_text_promotes(
        &input.review_summary,
    ) {
        issues.push(
            GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineResolutionReviewIssue::ReviewSummaryPromotionClaim,
        );
    }
    if input.accepted_append_decision_requested
        || input.accepted_evidence_mutation_requested
        || input.accepted_append_policy_change_requested
        || input.accepted_formal_evidence_created
        || input.creates_level2_evidence
        || input.populates_score_axes
        || input.proof_artifact_promoted
        || input.checker_transcript_promoted
        || input.solver_certificate_promoted
        || input.benchmark_or_sota_comparison_claimed
        || input.semantic_correctness_claimed
        || input.production_readiness_claimed
        || input.sota_claimed
        || input.breakthrough_claimed
        || input.full_security_claimed
        || input.action_authority_claimed
    {
        issues.push(
            GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineResolutionReviewIssue::PromotionAttempt,
        );
    }
}

