pub fn validate_gateway_formal_real_command_lane_accepted_append_decision_quarantine_resolution_escalation_terminal_review_closure_blocker_review_terminal_closure_input(
    closure_blocker_review: &GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReview,
    input: &GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureInput,
) -> GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureValidation{
    let mut issues = Vec::new();
    if input.schema_version != GATEWAY_FORMAL_REAL_COMMAND_LANE_ACCEPTED_APPEND_DECISION_QUARANTINE_RESOLUTION_ESCALATION_TERMINAL_REVIEW_CLOSURE_BLOCKER_REVIEW_TERMINAL_CLOSURE_SCHEMA_VERSION {
        issues.push(GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureIssue::InvalidSchemaVersion);
    }
    if !is_single_segment_id(&input.terminal_closure_id) {
        issues.push(GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureIssue::InvalidTerminalClosureId);
    }
    if !is_single_segment_id(&input.terminal_closure_policy_id) {
        issues.push(GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureIssue::InvalidTerminalClosurePolicyId);
    }
    if !is_single_segment_id(&input.terminal_closure_decision_id) {
        issues.push(GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureIssue::InvalidTerminalClosureDecisionId);
    }
    if input.terminal_closure_decision_at_unix == 0 {
        issues.push(GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureIssue::MissingTerminalClosureDecisionTimestamp);
    }
    let expected_digests =
        gateway_formal_real_command_lane_accepted_append_decision_quarantine_resolution_escalation_terminal_review_closure_blocker_review_terminal_closure_digest_bindings(
            closure_blocker_review,
        );
    for (label, digest) in &input.digest_bindings {
        if *digest == Hash([0; 32]) {
            issues.push(GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureIssue::MissingDigest(label.clone()));
        }
    }
    if input.digest_bindings != expected_digests {
        issues.push(GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureIssue::DigestBindingMismatch);
    }
    let expected_ids =
        gateway_formal_real_command_lane_accepted_append_decision_quarantine_resolution_escalation_terminal_review_closure_blocker_review_terminal_closure_id_bindings(
            closure_blocker_review,
            &input.terminal_closure_id,
            &input.terminal_closure_policy_id,
            &input.terminal_closure_decision_id,
        );
    for (label, value) in &input.id_bindings {
        if !is_single_segment_id(value) {
            issues.push(GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureIssue::InvalidIdBinding(label.clone()));
        }
    }
    if input.id_bindings != expected_ids {
        issues.push(GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureIssue::IdBindingMismatch);
    }
    let expected_labels =
        gateway_formal_real_command_lane_accepted_append_decision_quarantine_resolution_escalation_terminal_review_closure_blocker_review_terminal_closure_label_bindings(
            closure_blocker_review,
            &input.terminal_closure_label,
        );
    if input.label_bindings != expected_labels
        || input.inherited_closure_blocker_review_label
            != closure_blocker_review.closure_blocker_review_label
    {
        issues.push(GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureIssue::LabelBindingMismatch);
    }
    if closure_blocker_review.schema_version != GATEWAY_FORMAL_REAL_COMMAND_LANE_ACCEPTED_APPEND_DECISION_QUARANTINE_RESOLUTION_ESCALATION_TERMINAL_REVIEW_CLOSURE_BLOCKER_REVIEW_SCHEMA_VERSION
        || closure_blocker_review.state_slice != GATEWAY_FORMAL_REAL_COMMAND_LANE_ACCEPTED_APPEND_DECISION_QUARANTINE_RESOLUTION_ESCALATION_TERMINAL_REVIEW_CLOSURE_BLOCKER_REVIEW_STATE_SLICE
        || closure_blocker_review.promotion_state != "local_accepted_append_decision_quarantine_resolution_escalation_terminal_review_closure_blocker_review_metadata"
        || closure_blocker_review.next_required_state != "accepted_append_decision_still_blocked"
        || closure_blocker_review.claim_boundary != gateway_formal_real_command_lane_accepted_append_decision_quarantine_resolution_escalation_terminal_review_closure_blocker_review_claim_boundary()
        || closure_blocker_review.makes_accepted_append_decision
        || closure_blocker_review.creates_accepted_evidence
        || closure_blocker_review.changes_accepted_append_policy
        || closure_blocker_review.creates_level2_evidence
        || closure_blocker_review.populates_score_axes
        || closure_blocker_review.proof_artifact_created
        || closure_blocker_review.checker_transcript_created
        || closure_blocker_review.solver_certificate_created
        || closure_blocker_review.semantic_correctness_claimed
        || closure_blocker_review.production_readiness_claimed
        || closure_blocker_review.sota_claimed
        || closure_blocker_review.breakthrough_claimed
        || closure_blocker_review.full_security_claimed
        || closure_blocker_review.grants_authority
    {
        issues.push(GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureIssue::Phase391ClosureBlockerReviewStateMismatch);
    }
    let blockers = gateway_formal_real_command_lane_accepted_handoff_current_blockers();
    if input.current_accepted_append_blockers_digest != hash_tagged("hsai-agent-admission:gateway-formal-real-command-lane-accepted-handoff-current-blockers:v1", &blockers) {
        issues.push(GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureIssue::AcceptedAppendBlockerMismatch);
    }
    let nonclaims = gateway_formal_real_command_lane_accepted_append_decision_quarantine_resolution_escalation_terminal_review_closure_blocker_review_terminal_closure_required_nonclaims();
    if input.explicit_nonclaims != nonclaims || input.explicit_nonclaims_digest != hash_tagged("hsai-agent-admission:gateway-formal-real-command-lane-accepted-append-decision-quarantine-resolution-escalation-terminal-review-closure-blocker-review-terminal-closure-nonclaims:v1", &nonclaims) {
        issues.push(GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureIssue::NonclaimMismatch);
    }
    if gateway_formal_real_command_lane_local_review_audit_package_text_promotes(
        &input.terminal_closure_summary,
    ) {
        issues.push(GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureIssue::TerminalClosureSummaryPromotionClaim);
    }
    if input.accepted_append_decision_requested
        || input.accepted_evidence_mutation_requested
        || input.accepted_append_policy_change_requested
        || input.accepted_formal_evidence_created
        || input.creates_level2_evidence
        || input.populates_score_axes
        || input.proof_artifact_promoted
        || input.checker_transcript_promoted
        || input.solver_certificate_promoted
        || input.benchmark_or_sota_comparison_claimed
        || input.semantic_correctness_claimed
        || input.production_readiness_claimed
        || input.sota_claimed
        || input.breakthrough_claimed
        || input.full_security_claimed
        || input.action_authority_claimed
    {
        issues.push(GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureIssue::PromotionAttempt);
    }
    GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureValidation {
        valid: issues.is_empty(),
        issues,
    }
}

