pub fn validate_gateway_formal_real_command_lane_accepted_append_decision_quarantine_resolution_escalation_terminal_review_closure_blocker_review_terminal_closure_review_input(
    terminal_closure: &GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosure,
    input: &GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureReviewInput,
) -> GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureReviewValidation{
    let mut issues = Vec::new();
    if input.schema_version != GATEWAY_FORMAL_REAL_COMMAND_LANE_ACCEPTED_APPEND_DECISION_QUARANTINE_RESOLUTION_ESCALATION_TERMINAL_REVIEW_CLOSURE_BLOCKER_REVIEW_TERMINAL_CLOSURE_REVIEW_SCHEMA_VERSION {
        issues.push(GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureReviewIssue::InvalidSchemaVersion);
    }
    if !is_single_segment_id(&input.terminal_closure_review_id) {
        issues.push(GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureReviewIssue::InvalidTerminalClosureReviewId);
    }
    if !is_single_segment_id(&input.terminal_closure_review_policy_id) {
        issues.push(GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureReviewIssue::InvalidTerminalClosureReviewPolicyId);
    }
    if !is_single_segment_id(&input.terminal_closure_review_decision_id) {
        issues.push(GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureReviewIssue::InvalidTerminalClosureReviewDecisionId);
    }
    if input.terminal_closure_review_decision_at_unix == 0 {
        issues.push(GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureReviewIssue::MissingTerminalClosureReviewDecisionTimestamp);
    }
    let expected_digests =
        gateway_formal_real_command_lane_accepted_append_decision_quarantine_resolution_escalation_terminal_review_closure_blocker_review_terminal_closure_review_digest_bindings(
            terminal_closure,
        );
    for (label, digest) in &input.digest_bindings {
        if *digest == Hash([0; 32]) {
            issues.push(GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureReviewIssue::MissingDigest(label.clone()));
        }
    }
    if input.digest_bindings != expected_digests {
        issues.push(GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureReviewIssue::DigestBindingMismatch);
    }
    let expected_ids =
        gateway_formal_real_command_lane_accepted_append_decision_quarantine_resolution_escalation_terminal_review_closure_blocker_review_terminal_closure_review_id_bindings(
            terminal_closure,
            &input.terminal_closure_review_id,
            &input.terminal_closure_review_policy_id,
            &input.terminal_closure_review_decision_id,
        );
    for (label, value) in &input.id_bindings {
        if !is_single_segment_id(value) {
            issues.push(GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureReviewIssue::InvalidIdBinding(label.clone()));
        }
    }
    if input.id_bindings != expected_ids {
        issues.push(GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureReviewIssue::IdBindingMismatch);
    }
    let expected_labels =
        gateway_formal_real_command_lane_accepted_append_decision_quarantine_resolution_escalation_terminal_review_closure_blocker_review_terminal_closure_review_label_bindings(
            terminal_closure,
            &input.terminal_closure_review_label,
        );
    if input.label_bindings != expected_labels
        || input.inherited_terminal_closure_label != terminal_closure.terminal_closure_label
    {
        issues.push(GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureReviewIssue::LabelBindingMismatch);
    }
    if terminal_closure.schema_version != GATEWAY_FORMAL_REAL_COMMAND_LANE_ACCEPTED_APPEND_DECISION_QUARANTINE_RESOLUTION_ESCALATION_TERMINAL_REVIEW_CLOSURE_BLOCKER_REVIEW_TERMINAL_CLOSURE_SCHEMA_VERSION
        || terminal_closure.state_slice != GATEWAY_FORMAL_REAL_COMMAND_LANE_ACCEPTED_APPEND_DECISION_QUARANTINE_RESOLUTION_ESCALATION_TERMINAL_REVIEW_CLOSURE_BLOCKER_REVIEW_TERMINAL_CLOSURE_STATE_SLICE
        || terminal_closure.promotion_state != "local_accepted_append_decision_quarantine_resolution_escalation_terminal_review_closure_blocker_review_terminal_closure_metadata"
        || terminal_closure.next_required_state != "accepted_append_decision_still_blocked"
        || terminal_closure.claim_boundary != gateway_formal_real_command_lane_accepted_append_decision_quarantine_resolution_escalation_terminal_review_closure_blocker_review_terminal_closure_claim_boundary()
        || terminal_closure.makes_accepted_append_decision
        || terminal_closure.creates_accepted_evidence
        || terminal_closure.changes_accepted_append_policy
        || terminal_closure.creates_level2_evidence
        || terminal_closure.populates_score_axes
        || terminal_closure.proof_artifact_created
        || terminal_closure.checker_transcript_created
        || terminal_closure.solver_certificate_created
        || terminal_closure.semantic_correctness_claimed
        || terminal_closure.production_readiness_claimed
        || terminal_closure.sota_claimed
        || terminal_closure.breakthrough_claimed
        || terminal_closure.full_security_claimed
        || terminal_closure.grants_authority
    {
        issues.push(GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureReviewIssue::Phase393TerminalClosureStateMismatch);
    }
    let blockers = gateway_formal_real_command_lane_accepted_handoff_current_blockers();
    if input.current_accepted_append_blockers_digest != hash_tagged("hsai-agent-admission:gateway-formal-real-command-lane-accepted-handoff-current-blockers:v1", &blockers) {
        issues.push(GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureReviewIssue::AcceptedAppendBlockerMismatch);
    }
    let nonclaims = gateway_formal_real_command_lane_accepted_append_decision_quarantine_resolution_escalation_terminal_review_closure_blocker_review_terminal_closure_review_required_nonclaims();
    if input.explicit_nonclaims != nonclaims || input.explicit_nonclaims_digest != hash_tagged("hsai-agent-admission:gateway-formal-real-command-lane-accepted-append-decision-quarantine-resolution-escalation-terminal-review-closure-blocker-review-terminal-closure-review-nonclaims:v1", &nonclaims) {
        issues.push(GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureReviewIssue::NonclaimMismatch);
    }
    if gateway_formal_real_command_lane_local_review_audit_package_text_promotes(
        &input.terminal_closure_review_summary,
    ) {
        issues.push(GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureReviewIssue::TerminalClosureReviewSummaryPromotionClaim);
    }
    if input.accepted_append_decision_requested
        || input.accepted_evidence_mutation_requested
        || input.accepted_append_policy_change_requested
        || input.accepted_formal_evidence_created
        || input.creates_level2_evidence
        || input.populates_score_axes
        || input.proof_artifact_promoted
        || input.checker_transcript_promoted
        || input.solver_certificate_promoted
        || input.benchmark_or_sota_comparison_claimed
        || input.semantic_correctness_claimed
        || input.production_readiness_claimed
        || input.sota_claimed
        || input.breakthrough_claimed
        || input.full_security_claimed
        || input.action_authority_claimed
    {
        issues.push(GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureReviewIssue::PromotionAttempt);
    }
    GatewayFormalRealCommandLaneAcceptedAppendDecisionQuarantineResolutionEscalationTerminalReviewClosureBlockerReviewTerminalClosureReviewValidation {
        valid: issues.is_empty(),
        issues,
    }
}

fn validate_gateway_formal_real_command_lane_execution_preflight_manifest(
    manifest: &GatewayFormalRealCommandLaneOutputManifest,
    command_request: &GatewayFormalRealCommandLaneRequest,
    input: &GatewayFormalRealCommandLaneExecutionPreflightInput,
    issues: &mut Vec<GatewayFormalRealCommandLaneExecutionPreflightIssue>,
) {
    if input.phase323_manifest_digest != manifest.digest()
        || manifest.schema_version != GATEWAY_FORMAL_REAL_COMMAND_LANE_OUTPUT_SCHEMA_VERSION
        || manifest.state_slice != GATEWAY_FORMAL_REAL_COMMAND_LANE_STATE_SLICE
        || manifest.request_digest != command_request.digest()
        || manifest.command_descriptor_digest != input.command_descriptor_digest
        || manifest.obligation_digest != input.obligation_digest
        || manifest.claim_boundary != gateway_formal_real_command_lane_claim_boundary()
    {
        issues.push(GatewayFormalRealCommandLaneExecutionPreflightIssue::ManifestDrift);
    }
    if manifest.process_spawned
        || manifest.backend_executed
        || manifest.proof_artifact_created
        || manifest.checker_transcript_created
        || manifest.solver_certificate_created
        || manifest.creates_accepted_evidence
        || manifest.creates_level2_evidence
        || manifest.populates_score_axes
        || manifest.semantic_correctness_claimed
        || manifest.production_readiness_claimed
        || manifest.sota_claimed
        || manifest.breakthrough_claimed
        || manifest.full_security_claimed
        || manifest.grants_authority
    {
        issues.push(GatewayFormalRealCommandLaneExecutionPreflightIssue::PromotionAttempt);
    }
}

fn validate_gateway_formal_real_command_lane_execution_preflight_command_request(
    command_request: &GatewayFormalRealCommandLaneRequest,
    input: &GatewayFormalRealCommandLaneExecutionPreflightInput,
    issues: &mut Vec<GatewayFormalRealCommandLaneExecutionPreflightIssue>,
) {
    if input.command_request_digest != command_request.digest() {
        issues.push(GatewayFormalRealCommandLaneExecutionPreflightIssue::CommandRequestDigestDrift);
    }
    if input.obligation_digest != command_request.obligation_digest {
        issues.push(GatewayFormalRealCommandLaneExecutionPreflightIssue::ObligationDigestDrift);
    }
    if input.expected_output_grammar_digest != command_request.expected_output_grammar_digest {
        issues.push(
            GatewayFormalRealCommandLaneExecutionPreflightIssue::ExpectedOutputGrammarDigestDrift,
        );
    }
    if !input.operator_acknowledged || !command_request.operator_acknowledged {
        issues.push(
            GatewayFormalRealCommandLaneExecutionPreflightIssue::MissingOperatorAcknowledgement,
        );
    }
}

fn validate_gateway_formal_real_command_lane_execution_preflight_command(
    command: &GatewayFormalRealCommandLaneCommandDescriptor,
    input: &GatewayFormalRealCommandLaneExecutionPreflightInput,
    issues: &mut Vec<GatewayFormalRealCommandLaneExecutionPreflightIssue>,
) {
    if input.command_descriptor_digest != command.digest() {
        issues.push(
            GatewayFormalRealCommandLaneExecutionPreflightIssue::CommandDescriptorDigestDrift,
        );
    }
    if input.executable_digest == Hash([0; 32]) {
        issues.push(GatewayFormalRealCommandLaneExecutionPreflightIssue::MissingExecutableDigest);
    }
    if input.executable_policy_id != command.executable_policy_id
        || !command.fixed_executable_policy
        || command.executable_policy_id.trim().is_empty()
    {
        issues.push(GatewayFormalRealCommandLaneExecutionPreflightIssue::ExecutablePolicyMismatch);
    }
    if input.fixed_executable_label != command.executable_path_label
        || command.executable_path_label.trim().is_empty()
        || command.executable_path_label.starts_with('/')
        || !is_safe_relative_path(&command.executable_path_label)
    {
        issues.push(
            GatewayFormalRealCommandLaneExecutionPreflightIssue::FixedExecutableLabelMismatch,
        );
    }
    if command.caller_executable_path_allowed {
        issues
            .push(GatewayFormalRealCommandLaneExecutionPreflightIssue::CallerExecutablePathAllowed);
    }
    if command.caller_argv_allowed || !command.fixed_argv_template {
        issues.push(GatewayFormalRealCommandLaneExecutionPreflightIssue::CallerArgvAllowed);
    }
    if command.command_kind != "direct_process_no_shell"
        || !command.direct_process_no_shell
        || !command.no_shell
        || has_shell_metacharacters(&command.executable_path_label)
        || command
            .argv_template
            .iter()
            .any(|arg| has_shell_metacharacters(arg))
    {
        issues.push(GatewayFormalRealCommandLaneExecutionPreflightIssue::ShellFragment);
    }
    if command.inherit_environment || !command.environment_variables.is_empty() {
        issues.push(GatewayFormalRealCommandLaneExecutionPreflightIssue::InheritedEnvironment);
    }
    if !command.no_stdin {
        issues.push(GatewayFormalRealCommandLaneExecutionPreflightIssue::StdinAllowed);
    }
    if !command.no_network {
        issues.push(GatewayFormalRealCommandLaneExecutionPreflightIssue::NetworkAllowed);
    }
}

fn validate_gateway_formal_real_command_lane_execution_preflight_paths(
    input: &GatewayFormalRealCommandLaneExecutionPreflightInput,
    issues: &mut Vec<GatewayFormalRealCommandLaneExecutionPreflightIssue>,
) {
    if input.output_root_label.trim().is_empty()
        || !is_safe_relative_path(&input.output_root_label)
        || path_label_is_protected(&input.output_root_label)
    {
        issues.push(GatewayFormalRealCommandLaneExecutionPreflightIssue::ProtectedOutputRoot);
    }
    if input.accepted_evidence_path_requested {
        issues.push(
            GatewayFormalRealCommandLaneExecutionPreflightIssue::AcceptedEvidencePathRequested,
        );
    }
    if input.level2_evidence_path_requested {
        issues
            .push(GatewayFormalRealCommandLaneExecutionPreflightIssue::Level2EvidencePathRequested);
    }
    if input.score_axis_path_requested {
        issues.push(GatewayFormalRealCommandLaneExecutionPreflightIssue::ScoreAxisPathRequested);
    }
    if input.benchmark_output_path_requested {
        issues.push(
            GatewayFormalRealCommandLaneExecutionPreflightIssue::BenchmarkOutputPathRequested,
        );
    }
    if input.proof_promotion_path_requested {
        issues
            .push(GatewayFormalRealCommandLaneExecutionPreflightIssue::ProofPromotionPathRequested);
    }
}

