#[allow(clippy::too_many_arguments)]
fn gateway_formal_backend_hermetic_fixture_runner_output_manifest_for_files(
    descriptor: &GatewayFormalBackendHermeticExecutionDescriptor,
    descriptor_report_manifest: &GatewayFormalBackendHermeticDescriptorReportOutputManifest,
    input_binding: &GatewayFormalBackendHermeticExecutionResultInputBinding,
    command_contract: &GatewayFormalBackendHermeticDescriptorReportCommandContract,
    execution_status: &GatewayFormalBackendHermeticExecutionResultExecutionStatus,
    stdout_summary: &GatewayFormalBackendHermeticExecutionResultBoundedSummary,
    stderr_summary: &GatewayFormalBackendHermeticExecutionResultBoundedSummary,
    redaction_report: &GatewayFormalBackendHermeticExecutionResultRedactionReport,
    output_inventory: &GatewayFormalBackendHermeticExecutionResultOutputInventory,
    invariant_verdict: &GatewayFormalBackendHermeticExecutionResultInvariantVerdictReport,
    nonpromotion_report: &GatewayFormalBackendHermeticExecutionResultNonpromotionReport,
    validation_report: &GatewayFormalBackendHermeticExecutionResultOutputValidationReport,
    request: &GatewayFormalBackendHermeticFixtureRunnerRequest,
    files: &BTreeMap<String, Vec<u8>>,
) -> GatewayFormalBackendHermeticExecutionResultQuarantineOutputManifest {
    let mut declared_file_digests = BTreeMap::new();
    for (logical_path, bytes) in files {
        declared_file_digests.insert(logical_path.clone(), hash_bytes(bytes));
    }
    GatewayFormalBackendHermeticExecutionResultQuarantineOutputManifest {
        schema_version:
            GATEWAY_FORMAL_BACKEND_HERMETIC_EXECUTION_RESULT_QUARANTINE_OUTPUT_SCHEMA_VERSION
                .to_owned(),
        bundle_id: request.run_id.clone(),
        state_slice: GATEWAY_FORMAL_BACKEND_HERMETIC_FIXTURE_RUNNER_STATE_SLICE.to_owned(),
        created_at_unix: request.created_at_unix,
        descriptor_digest: descriptor.digest(),
        descriptor_report_output_manifest_digest: descriptor_report_manifest.digest(),
        descriptor_report_validation_digest: descriptor_report_manifest.validation_digest,
        input_binding_digest: input_binding.digest(),
        command_contract_digest: command_contract.digest(),
        execution_status_digest: execution_status.digest(),
        stdout_summary_digest: stdout_summary.digest(),
        stderr_summary_digest: stderr_summary.digest(),
        redaction_report_digest: redaction_report.digest(),
        output_inventory_digest: output_inventory.digest(),
        invariant_verdict_digest: invariant_verdict.digest(),
        nonpromotion_report_digest: nonpromotion_report.digest(),
        validation_digest: validation_report.digest(),
        nonclaims_digest: hash_bytes(
            files
                .get("gateway-formal-backend-hermetic-execution-result-quarantine/nonclaims.md")
                .map(Vec::as_slice)
                .unwrap_or_default(),
        ),
        backend_id: "local_smt_tiny_gateway_invariant".to_owned(),
        backend_kind: descriptor.backend_kind.clone(),
        tool_name: descriptor.tool_name.clone(),
        tool_version: descriptor.tool_version.clone(),
        executable_path_label: descriptor.executable_path_label.clone(),
        argv_template_digest: gateway_formal_backend_hermetic_argv_template_digest(
            &descriptor.argv_template,
        ),
        environment_policy_digest:
            gateway_formal_backend_hermetic_execution_result_environment_policy_digest(descriptor),
        output_root_label_digest:
            gateway_formal_backend_hermetic_execution_result_output_root_label_digest(
                &descriptor.output_root_label,
            ),
        timeout_millis: descriptor.timeout_millis,
        max_stdout_bytes: descriptor.max_stdout_bytes,
        max_stderr_bytes: descriptor.max_stderr_bytes,
        process_exit_code_label: execution_status.process_exit_code_label.clone(),
        timeout: execution_status.timeout,
        signal: execution_status.signal,
        solver_status: execution_status.solver_status.clone(),
        invariant_verdict: GatewayFormalBackendHermeticExecutionInvariantVerdict::NotEvaluated,
        declared_files:
            gateway_formal_backend_hermetic_execution_result_quarantine_output_declared_files(),
        declared_file_digests,
        claim_boundary: gateway_formal_backend_hermetic_fixture_runner_claim_boundary(),
        process_spawned: true,
        backend_executed: true,
        proof_artifact_created: false,
        checker_transcript_created: false,
        solver_certificate_created: false,
        creates_accepted_evidence: false,
        creates_level2_evidence: false,
        populates_score_axes: false,
        semantic_correctness_claimed: false,
        production_readiness_claimed: false,
        sota_claimed: false,
        breakthrough_claimed: false,
        full_security_claimed: false,
        grants_authority: false,
        nonclaims: gateway_formal_backend_hermetic_fixture_runner_required_nonclaims(),
    }
}

fn validate_gateway_formal_backend_hermetic_fixture_runner_bundle_semantics(
    files: &BTreeMap<String, Vec<u8>>,
) -> Result<
    GatewayFormalBackendHermeticExecutionResultQuarantineOutputManifest,
    GatewayFormalBackendHermeticFixtureRunnerError,
> {
    let manifest: GatewayFormalBackendHermeticExecutionResultQuarantineOutputManifest =
        parse_gateway_formal_backend_hermetic_execution_result_quarantine_declared_json(
            files,
            "gateway-formal-backend-hermetic-execution-result-quarantine/manifest.json",
        )
        .map_err(GatewayFormalBackendHermeticFixtureRunnerError::Output)?;
    let input_binding: GatewayFormalBackendHermeticExecutionResultInputBinding =
        parse_gateway_formal_backend_hermetic_execution_result_quarantine_declared_json(
            files,
            "gateway-formal-backend-hermetic-execution-result-quarantine/input-binding.json",
        )
        .map_err(GatewayFormalBackendHermeticFixtureRunnerError::Output)?;
    let command_contract: GatewayFormalBackendHermeticDescriptorReportCommandContract =
        parse_gateway_formal_backend_hermetic_execution_result_quarantine_declared_json(
            files,
            "gateway-formal-backend-hermetic-execution-result-quarantine/command-contract.json",
        )
        .map_err(GatewayFormalBackendHermeticFixtureRunnerError::Output)?;
    let execution_status: GatewayFormalBackendHermeticExecutionResultExecutionStatus =
        parse_gateway_formal_backend_hermetic_execution_result_quarantine_declared_json(
            files,
            "gateway-formal-backend-hermetic-execution-result-quarantine/execution-status.json",
        )
        .map_err(GatewayFormalBackendHermeticFixtureRunnerError::Output)?;
    let stdout_summary: GatewayFormalBackendHermeticExecutionResultBoundedSummary =
        parse_gateway_formal_backend_hermetic_execution_result_quarantine_declared_json(
            files,
            "gateway-formal-backend-hermetic-execution-result-quarantine/stdout-summary.json",
        )
        .map_err(GatewayFormalBackendHermeticFixtureRunnerError::Output)?;
    let stderr_summary: GatewayFormalBackendHermeticExecutionResultBoundedSummary =
        parse_gateway_formal_backend_hermetic_execution_result_quarantine_declared_json(
            files,
            "gateway-formal-backend-hermetic-execution-result-quarantine/stderr-summary.json",
        )
        .map_err(GatewayFormalBackendHermeticFixtureRunnerError::Output)?;
    let redaction_report: GatewayFormalBackendHermeticExecutionResultRedactionReport =
        parse_gateway_formal_backend_hermetic_execution_result_quarantine_declared_json(
            files,
            "gateway-formal-backend-hermetic-execution-result-quarantine/redaction-report.json",
        )
        .map_err(GatewayFormalBackendHermeticFixtureRunnerError::Output)?;
    let output_inventory: GatewayFormalBackendHermeticExecutionResultOutputInventory =
        parse_gateway_formal_backend_hermetic_execution_result_quarantine_declared_json(
            files,
            "gateway-formal-backend-hermetic-execution-result-quarantine/output-inventory.json",
        )
        .map_err(GatewayFormalBackendHermeticFixtureRunnerError::Output)?;
    let invariant_verdict: GatewayFormalBackendHermeticExecutionResultInvariantVerdictReport =
        parse_gateway_formal_backend_hermetic_execution_result_quarantine_declared_json(
            files,
            "gateway-formal-backend-hermetic-execution-result-quarantine/invariant-verdict.json",
        )
        .map_err(GatewayFormalBackendHermeticFixtureRunnerError::Output)?;
    let nonpromotion_report: GatewayFormalBackendHermeticExecutionResultNonpromotionReport =
        parse_gateway_formal_backend_hermetic_execution_result_quarantine_declared_json(
            files,
            "gateway-formal-backend-hermetic-execution-result-quarantine/nonpromotion-report.json",
        )
        .map_err(GatewayFormalBackendHermeticFixtureRunnerError::Output)?;
    let validation_report: GatewayFormalBackendHermeticExecutionResultOutputValidationReport =
        parse_gateway_formal_backend_hermetic_execution_result_quarantine_declared_json(
            files,
            "gateway-formal-backend-hermetic-execution-result-quarantine/validation.json",
        )
        .map_err(GatewayFormalBackendHermeticFixtureRunnerError::Output)?;
    let nonclaims = declared_gateway_formal_backend_hermetic_execution_result_quarantine_bytes(
        files,
        "gateway-formal-backend-hermetic-execution-result-quarantine/nonclaims.md",
    )
    .map_err(GatewayFormalBackendHermeticFixtureRunnerError::Output)?;
    let nonclaims_text = std::str::from_utf8(nonclaims).map_err(|_| {
        GatewayFormalBackendHermeticFixtureRunnerError::Output(
            GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::NonclaimMismatch,
        )
    })?;
    for required in gateway_formal_backend_hermetic_fixture_runner_required_nonclaims() {
        if !nonclaims_text.contains(&required.0) || !manifest.nonclaims.contains(&required) {
            return Err(GatewayFormalBackendHermeticFixtureRunnerError::Output(
                GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::NonclaimMismatch,
            ));
        }
    }
    let mut actual_digest_paths = manifest
        .declared_file_digests
        .keys()
        .cloned()
        .collect::<Vec<_>>();
    actual_digest_paths.sort();
    let mut expected_digest_paths =
        gateway_formal_backend_hermetic_execution_result_quarantine_output_declared_files();
    expected_digest_paths.retain(|path| {
        path != "gateway-formal-backend-hermetic-execution-result-quarantine/manifest.json"
    });
    expected_digest_paths.sort();
    if manifest.schema_version
        != GATEWAY_FORMAL_BACKEND_HERMETIC_EXECUTION_RESULT_QUARANTINE_OUTPUT_SCHEMA_VERSION
        || manifest.state_slice != GATEWAY_FORMAL_BACKEND_HERMETIC_FIXTURE_RUNNER_STATE_SLICE
        || manifest.input_binding_digest != input_binding.digest()
        || manifest.command_contract_digest != command_contract.digest()
        || manifest.execution_status_digest != execution_status.digest()
        || manifest.stdout_summary_digest != stdout_summary.digest()
        || manifest.stderr_summary_digest != stderr_summary.digest()
        || manifest.redaction_report_digest != redaction_report.digest()
        || manifest.output_inventory_digest != output_inventory.digest()
        || manifest.invariant_verdict_digest != invariant_verdict.digest()
        || manifest.nonpromotion_report_digest != nonpromotion_report.digest()
        || manifest.validation_digest != validation_report.digest()
        || manifest.nonclaims_digest != hash_bytes(nonclaims)
        || manifest.backend_id != "local_smt_tiny_gateway_invariant"
        || manifest.backend_kind != command_contract.backend_kind
        || manifest.executable_path_label != command_contract.executable_path_label
        || manifest.argv_template_digest != command_contract.argv_template_digest
        || manifest.output_root_label_digest
            != gateway_formal_backend_hermetic_execution_result_output_root_label_digest(
                &command_contract.output_root_label,
            )
        || manifest.timeout_millis != command_contract.timeout_millis
        || manifest.max_stdout_bytes != command_contract.max_stdout_bytes
        || manifest.max_stderr_bytes != command_contract.max_stderr_bytes
        || manifest.solver_status != execution_status.solver_status
        || manifest.invariant_verdict
            != GatewayFormalBackendHermeticExecutionInvariantVerdict::NotEvaluated
        || manifest.declared_files
            != gateway_formal_backend_hermetic_execution_result_quarantine_output_declared_files()
        || actual_digest_paths != expected_digest_paths
        || manifest.claim_boundary
            != gateway_formal_backend_hermetic_fixture_runner_claim_boundary()
        || !manifest.process_spawned
        || !manifest.backend_executed
        || manifest.proof_artifact_created
        || manifest.checker_transcript_created
        || manifest.solver_certificate_created
        || manifest.creates_accepted_evidence
        || manifest.creates_level2_evidence
        || manifest.populates_score_axes
        || manifest.semantic_correctness_claimed
        || manifest.production_readiness_claimed
        || manifest.sota_claimed
        || manifest.breakthrough_claimed
        || manifest.full_security_claimed
        || manifest.grants_authority
    {
        return Err(GatewayFormalBackendHermeticFixtureRunnerError::Output(
            GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::ManifestSemanticMismatch,
        ));
    }
    if !command_contract.no_spawn
        || !command_contract.no_stdin
        || !command_contract.no_shell
        || !command_contract.no_network
        || command_contract.inherit_environment
    {
        return Err(GatewayFormalBackendHermeticFixtureRunnerError::Output(
            GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::CommandContractMismatch,
        ));
    }
    if !execution_status.process_spawned
        || !execution_status.backend_executed
        || execution_status.process_exit_code_label.trim().is_empty()
        || execution_status.solver_status
            == GatewayFormalBackendHermeticExecutionSolverStatus::NotRun
        || execution_status.invariant_verdict
            != GatewayFormalBackendHermeticExecutionInvariantVerdict::NotEvaluated
        || execution_status.command_contract_digest != command_contract.digest()
        || execution_status.input_binding_digest != input_binding.digest()
        || execution_status.output_inventory_digest != output_inventory.digest()
    {
        return Err(GatewayFormalBackendHermeticFixtureRunnerError::Output(
            GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::ExecutionStatusMismatch,
        ));
    }
    if stdout_summary.stream_label != "stdout"
        || stdout_summary.raw_retained
        || !stdout_summary.secret_scan_passed
        || stdout_summary.raw_solver_trace_retained
        || stdout_summary.proof_artifact_retained
        || stdout_summary.checker_transcript_retained
        || stdout_summary.claim_boundary
            != gateway_formal_backend_hermetic_fixture_runner_claim_boundary()
    {
        return Err(GatewayFormalBackendHermeticFixtureRunnerError::Output(
            GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::StdoutSummaryMismatch,
        ));
    }
    if stderr_summary.stream_label != "stderr"
        || stderr_summary.raw_retained
        || !stderr_summary.secret_scan_passed
        || stderr_summary.raw_solver_trace_retained
        || stderr_summary.proof_artifact_retained
        || stderr_summary.checker_transcript_retained
        || stderr_summary.claim_boundary
            != gateway_formal_backend_hermetic_fixture_runner_claim_boundary()
    {
        return Err(GatewayFormalBackendHermeticFixtureRunnerError::Output(
            GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::StderrSummaryMismatch,
        ));
    }
    if !redaction_report.valid
        || !redaction_report.stdout_summary_bounded
        || !redaction_report.stderr_summary_bounded
        || redaction_report.credential_looking_value_found
        || redaction_report.secret_looking_value_found
        || redaction_report.raw_solver_trace_found
        || redaction_report.proof_artifact_found
        || redaction_report.checker_transcript_found
        || redaction_report.solver_certificate_found
        || !redaction_report.retained_summary_only
        || redaction_report.claim_boundary
            != gateway_formal_backend_hermetic_fixture_runner_claim_boundary()
    {
        return Err(GatewayFormalBackendHermeticFixtureRunnerError::Output(
            GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::RedactionReportMismatch,
        ));
    }
    if output_inventory.raw_stdout_retained
        || output_inventory.raw_stderr_retained
        || output_inventory.raw_solver_trace_retained
        || output_inventory.raw_prover_log_retained
        || output_inventory.raw_checker_log_retained
        || output_inventory.proof_artifact_retained
        || output_inventory.checker_transcript_retained
        || output_inventory.solver_certificate_retained
        || output_inventory.accepted_evidence_file_retained
        || output_inventory.level2_evidence_file_retained
        || output_inventory.benchmark_output_retained
        || output_inventory.score_axis_output_retained
    {
        return Err(GatewayFormalBackendHermeticFixtureRunnerError::Output(
            GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::OutputInventoryMismatch,
        ));
    }
    if invariant_verdict.verdict
        != GatewayFormalBackendHermeticExecutionInvariantVerdict::NotEvaluated
        || invariant_verdict.solver_status != execution_status.solver_status
        || invariant_verdict.proof_artifact_created
        || invariant_verdict.checker_transcript_created
        || invariant_verdict.solver_certificate_created
        || invariant_verdict.semantic_correctness_claimed
    {
        return Err(GatewayFormalBackendHermeticFixtureRunnerError::Output(
            GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::InvariantVerdictMismatch,
        ));
    }
    if nonpromotion_report.proof_artifact_created
        || nonpromotion_report.checker_transcript_created
        || nonpromotion_report.solver_certificate_created
        || nonpromotion_report.creates_accepted_evidence
        || nonpromotion_report.creates_level2_evidence
        || nonpromotion_report.populates_score_axes
        || nonpromotion_report.grants_authority
        || nonpromotion_report.semantic_correctness_claimed
        || nonpromotion_report.production_readiness_claimed
        || nonpromotion_report.sota_claimed
        || nonpromotion_report.breakthrough_claimed
        || nonpromotion_report.full_security_claimed
        || nonpromotion_report.claim_boundary
            != gateway_formal_backend_hermetic_execution_result_quarantine_output_claim_boundary()
    {
        return Err(GatewayFormalBackendHermeticFixtureRunnerError::Output(
            GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::NonpromotionReportMismatch,
        ));
    }
    if !validation_report.valid
        || validation_report.claim_boundary
            != gateway_formal_backend_hermetic_fixture_runner_claim_boundary()
        || !validation_report.process_spawned
        || !validation_report.backend_executed
        || validation_report.proof_artifact_created
        || validation_report.checker_transcript_created
        || validation_report.solver_certificate_created
        || validation_report.creates_accepted_evidence
        || validation_report.creates_level2_evidence
        || validation_report.populates_score_axes
        || validation_report.grants_authority
    {
        return Err(GatewayFormalBackendHermeticFixtureRunnerError::Output(
            GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::ValidationReportMismatch,
        ));
    }
    for (logical_path, expected_digest) in &manifest.declared_file_digests {
        let bytes = declared_gateway_formal_backend_hermetic_execution_result_quarantine_bytes(
            files,
            logical_path,
        )
        .map_err(GatewayFormalBackendHermeticFixtureRunnerError::Output)?;
        if *expected_digest != hash_bytes(bytes) {
            return Err(GatewayFormalBackendHermeticFixtureRunnerError::Output(
                GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::DigestMismatch(
                    logical_path.clone(),
                ),
            ));
        }
    }
    Ok(manifest)
}

fn gateway_formal_backend_hermetic_fixture_runner_report(
    interface: &GatewayFormalBackendHermeticProcessSpawnInterface,
    descriptor: &GatewayFormalBackendHermeticExecutionDescriptor,
    descriptor_report_manifest: &GatewayFormalBackendHermeticDescriptorReportOutputManifest,
    source_result_quarantine_manifest: &GatewayFormalBackendHermeticExecutionResultQuarantineOutputManifest,
    output_manifest: &GatewayFormalBackendHermeticExecutionResultQuarantineOutputManifest,
    request: &GatewayFormalBackendHermeticFixtureRunnerRequest,
) -> GatewayFormalBackendHermeticFixtureRunnerReport {
    GatewayFormalBackendHermeticFixtureRunnerReport {
        schema_version: GATEWAY_FORMAL_BACKEND_HERMETIC_FIXTURE_RUNNER_SCHEMA_VERSION.to_owned(),
        run_id: request.run_id.clone(),
        state_slice: GATEWAY_FORMAL_BACKEND_HERMETIC_FIXTURE_RUNNER_STATE_SLICE.to_owned(),
        interface_digest: interface.digest(),
        descriptor_digest: descriptor.digest(),
        descriptor_report_output_manifest_digest: descriptor_report_manifest.digest(),
        source_result_quarantine_output_manifest_digest: source_result_quarantine_manifest.digest(),
        output_manifest_digest: output_manifest.digest(),
        process_spawned: output_manifest.process_spawned,
        backend_executed: output_manifest.backend_executed,
        timeout: output_manifest.timeout,
        process_exit_code_label: output_manifest.process_exit_code_label.clone(),
        stdout_summary_digest: output_manifest.stdout_summary_digest,
        stderr_summary_digest: output_manifest.stderr_summary_digest,
        claim_boundary: gateway_formal_backend_hermetic_fixture_runner_claim_boundary(),
        creates_accepted_evidence: false,
        creates_level2_evidence: false,
        populates_score_axes: false,
        grants_authority: false,
        semantic_correctness_claimed: false,
        production_readiness_claimed: false,
        sota_claimed: false,
        breakthrough_claimed: false,
        full_security_claimed: false,
        nonclaims: gateway_formal_backend_hermetic_fixture_runner_required_nonclaims(),
    }
}

fn gateway_formal_backend_hermetic_fixture_runner_io_error(
    error: io::Error,
) -> GatewayFormalBackendHermeticFixtureRunnerError {
    GatewayFormalBackendHermeticFixtureRunnerError::Io(error.to_string())
}

fn gateway_formal_backend_hermetic_fixture_runner_serde_error(
    error: serde_json::Error,
) -> GatewayFormalBackendHermeticFixtureRunnerError {
    GatewayFormalBackendHermeticFixtureRunnerError::Serialization(error.to_string())
}

fn required_string_set(values: &[&str]) -> BTreeSet<String> {
    values.iter().map(|value| (*value).to_owned()).collect()
}

fn validate_gateway_formal_backend_quarantine_summary_label_set(
    actual: &BTreeSet<String>,
    required: &BTreeSet<String>,
    issues: &mut Vec<GatewayFormalBackendExecutionQuarantineValidationSummaryIssue>,
) {
    for label in required {
        if !actual.contains(label) {
            issues.push(
                GatewayFormalBackendExecutionQuarantineValidationSummaryIssue::MissingCoverageLabel(
                    label.clone(),
                ),
            );
        }
    }
    for label in actual {
        if !required.contains(label) {
            issues.push(
                GatewayFormalBackendExecutionQuarantineValidationSummaryIssue::UnknownCoverageLabel(
                    label.clone(),
                ),
            );
        }
    }
}

pub fn materialize_gateway_formal_backend_execution_quarantine_output_bundle(
    output_root: &Path,
    metadata: &GatewayFormalBackendExecutionQuarantineArtifactMetadata,
    authorization: &GatewayFormalBackendExecutionAuthorizationRequest,
    authorization_output_manifest: &GatewayFormalBackendExecutionAuthorizationOutputManifest,
    request: &GatewayFormalBackendExecutionQuarantineOutputRequest,
) -> Result<
    GatewayFormalBackendExecutionQuarantineOutputManifest,
    GatewayFormalBackendExecutionQuarantineOutputError,
> {
    validate_gateway_formal_backend_execution_quarantine_output_request(
        output_root,
        metadata,
        authorization,
        authorization_output_manifest,
        request,
    )?;
    let staging_root =
        gateway_formal_backend_quarantine_staging_root_for(output_root, &request.bundle_id)?;
    if staging_root.exists() {
        remove_gateway_formal_backend_quarantine_dir_all_checked(&staging_root)?;
    }
    fs::create_dir_all(staging_root.join("gateway-formal-backend-quarantine"))
        .map_err(gateway_formal_backend_quarantine_io_error)?;

    let files = build_gateway_formal_backend_quarantine_bundle_files(metadata, request)?;
    for (logical_path, bytes) in &files {
        let target = staging_root.join(logical_path);
        if let Some(parent) = target.parent() {
            fs::create_dir_all(parent).map_err(gateway_formal_backend_quarantine_io_error)?;
        }
        fs::write(&target, bytes).map_err(gateway_formal_backend_quarantine_io_error)?;
        fs::write(
            sidecar_path(&target),
            hash_hex(hash_bytes(bytes)).into_bytes(),
        )
        .map_err(gateway_formal_backend_quarantine_io_error)?;
    }

    if output_root.exists() {
        if !request.overwrite {
            remove_gateway_formal_backend_quarantine_dir_all_checked(&staging_root)?;
            return Err(
                GatewayFormalBackendExecutionQuarantineOutputError::OutputRootExistsWithoutOverwrite,
            );
        }
        remove_gateway_formal_backend_quarantine_dir_all_checked(output_root)?;
    }
    fs::rename(&staging_root, output_root).map_err(gateway_formal_backend_quarantine_io_error)?;
    read_gateway_formal_backend_execution_quarantine_output_bundle(output_root)
}

pub fn read_gateway_formal_backend_execution_quarantine_output_bundle(
    output_root: &Path,
) -> Result<
    GatewayFormalBackendExecutionQuarantineOutputManifest,
    GatewayFormalBackendExecutionQuarantineOutputError,
> {
    let output_metadata =
        fs::symlink_metadata(output_root).map_err(gateway_formal_backend_quarantine_io_error)?;
    if output_metadata.file_type().is_symlink() {
        return Err(GatewayFormalBackendExecutionQuarantineOutputError::OutputRootIsSymlink);
    }
    if !output_metadata.is_dir() {
        return Err(GatewayFormalBackendExecutionQuarantineOutputError::OutputRootIsFile);
    }
    let bundle_dir = output_root.join("gateway-formal-backend-quarantine");
    let bundle_metadata =
        fs::symlink_metadata(&bundle_dir).map_err(gateway_formal_backend_quarantine_io_error)?;
    if bundle_metadata.file_type().is_symlink() {
        return Err(
            GatewayFormalBackendExecutionQuarantineOutputError::BundleFileIsSymlink(
                "gateway-formal-backend-quarantine".to_owned(),
            ),
        );
    }
    if !bundle_metadata.is_dir() {
        return Err(
            GatewayFormalBackendExecutionQuarantineOutputError::DeclaredFileTypeMismatch(
                "gateway-formal-backend-quarantine".to_owned(),
            ),
        );
    }

    reject_undeclared_gateway_formal_backend_quarantine_files(output_root)?;
    let mut file_bytes = BTreeMap::new();
    for logical_path in GATEWAY_FORMAL_BACKEND_QUARANTINE_DECLARED_FILES {
        let path = output_root.join(logical_path);
        let metadata =
            fs::symlink_metadata(&path).map_err(gateway_formal_backend_quarantine_io_error)?;
        if metadata.file_type().is_symlink() {
            return Err(
                GatewayFormalBackendExecutionQuarantineOutputError::BundleFileIsSymlink(
                    (*logical_path).to_owned(),
                ),
            );
        }
        if !metadata.is_file() {
            return Err(
                GatewayFormalBackendExecutionQuarantineOutputError::DeclaredFileTypeMismatch(
                    (*logical_path).to_owned(),
                ),
            );
        }
        let sidecar = sidecar_path(&path);
        let sidecar_metadata =
            fs::symlink_metadata(&sidecar).map_err(gateway_formal_backend_quarantine_io_error)?;
        if sidecar_metadata.file_type().is_symlink() {
            return Err(
                GatewayFormalBackendExecutionQuarantineOutputError::BundleFileIsSymlink(format!(
                    "{logical_path}.sha256"
                )),
            );
        }
        if !sidecar_metadata.is_file() {
            return Err(
                GatewayFormalBackendExecutionQuarantineOutputError::DeclaredFileTypeMismatch(
                    format!("{logical_path}.sha256"),
                ),
            );
        }
        let bytes = fs::read(&path).map_err(gateway_formal_backend_quarantine_io_error)?;
        let expected =
            fs::read_to_string(sidecar).map_err(gateway_formal_backend_quarantine_io_error)?;
        if expected != hash_hex(hash_bytes(&bytes)) {
            return Err(
                GatewayFormalBackendExecutionQuarantineOutputError::DigestMismatch(
                    (*logical_path).to_owned(),
                ),
            );
        }
        file_bytes.insert((*logical_path).to_owned(), bytes);
    }

    validate_gateway_formal_backend_quarantine_bundle_semantics(&file_bytes)
}

