#[allow(clippy::too_many_arguments)]
fn validate_gateway_formal_backend_execution_authorization_output_request(
    output_root: &Path,
    authorization: &GatewayFormalBackendExecutionAuthorizationRequest,
    preflight_request: &GatewayFormalBackendExecutionPreflightRequest,
    preflight_report: &GatewayFormalBackendExecutionPreflightReport,
    preflight_manifest: &GatewayFormalBackendPreflightOutputManifest,
    transcript_metadata: &GatewayFormalBackendExecutionTranscriptMetadata,
    transcript_output_manifest: &GatewayFormalBackendTranscriptOutputManifest,
    request: &GatewayFormalBackendExecutionAuthorizationOutputRequest,
) -> Result<(), GatewayFormalBackendExecutionAuthorizationOutputError> {
    if request.bundle_id.trim().is_empty()
        || !is_safe_relative_path(&request.bundle_id)
        || request.bundle_id.contains(['/', '\\'])
    {
        return Err(GatewayFormalBackendExecutionAuthorizationOutputError::EmptyBundleId);
    }
    let validation = validate_gateway_formal_backend_execution_authorization_request(
        authorization,
        preflight_request,
        preflight_report,
        preflight_manifest,
        transcript_metadata,
        transcript_output_manifest,
    );
    if !validation.valid {
        return Err(
            GatewayFormalBackendExecutionAuthorizationOutputError::InvalidAuthorization(
                validation.issues,
            ),
        );
    }
    let expected_authorization = build_gateway_formal_backend_execution_authorization_request(
        authorization.authorization_id.clone(),
        preflight_request,
        preflight_report,
        preflight_manifest,
        transcript_metadata,
        transcript_output_manifest,
        authorization.quarantine_descriptor.clone(),
        authorization.operator_acknowledgement.clone(),
    );
    if authorization != &expected_authorization {
        return Err(
            GatewayFormalBackendExecutionAuthorizationOutputError::AuthorizationRequestMismatch,
        );
    }
    validate_gateway_formal_backend_authorization_output_root(
        output_root,
        &request.protected_roots,
        request.overwrite,
    )
}

fn build_gateway_formal_backend_authorization_bundle_files(
    authorization: &GatewayFormalBackendExecutionAuthorizationRequest,
    request: &GatewayFormalBackendExecutionAuthorizationOutputRequest,
) -> Result<BTreeMap<String, Vec<u8>>, GatewayFormalBackendExecutionAuthorizationOutputError> {
    let preflight_binding = gateway_formal_backend_authorization_preflight_binding(authorization);
    let transcript_binding = gateway_formal_backend_authorization_transcript_binding(authorization);
    let command_binding = gateway_formal_backend_authorization_command_binding(authorization);
    let environment_binding =
        gateway_formal_backend_authorization_environment_binding(authorization);
    let nonclaims = render_gateway_formal_backend_authorization_nonclaims(&authorization.nonclaims);
    let mut files = BTreeMap::from([
        (
            "gateway-formal-backend-authorization/authorization-request.json".to_owned(),
            serde_json::to_vec_pretty(authorization)
                .map_err(gateway_formal_backend_authorization_serde_error)?,
        ),
        (
            "gateway-formal-backend-authorization/preflight-binding.json".to_owned(),
            serde_json::to_vec_pretty(&preflight_binding)
                .map_err(gateway_formal_backend_authorization_serde_error)?,
        ),
        (
            "gateway-formal-backend-authorization/transcript-binding.json".to_owned(),
            serde_json::to_vec_pretty(&transcript_binding)
                .map_err(gateway_formal_backend_authorization_serde_error)?,
        ),
        (
            "gateway-formal-backend-authorization/command-binding.json".to_owned(),
            serde_json::to_vec_pretty(&command_binding)
                .map_err(gateway_formal_backend_authorization_serde_error)?,
        ),
        (
            "gateway-formal-backend-authorization/environment-binding.json".to_owned(),
            serde_json::to_vec_pretty(&environment_binding)
                .map_err(gateway_formal_backend_authorization_serde_error)?,
        ),
        (
            "gateway-formal-backend-authorization/quarantine-descriptor.json".to_owned(),
            serde_json::to_vec_pretty(&authorization.quarantine_descriptor)
                .map_err(gateway_formal_backend_authorization_serde_error)?,
        ),
        (
            "gateway-formal-backend-authorization/operator-acknowledgement.json".to_owned(),
            serde_json::to_vec_pretty(&authorization.operator_acknowledgement)
                .map_err(gateway_formal_backend_authorization_serde_error)?,
        ),
        (
            "gateway-formal-backend-authorization/nonclaims.md".to_owned(),
            nonclaims.into_bytes(),
        ),
    ]);
    let manifest = gateway_formal_backend_authorization_output_manifest_for_files(
        authorization,
        request,
        &files,
    );
    files.insert(
        "gateway-formal-backend-authorization/manifest.json".to_owned(),
        serde_json::to_vec_pretty(&manifest)
            .map_err(gateway_formal_backend_authorization_serde_error)?,
    );
    Ok(files)
}

fn gateway_formal_backend_authorization_output_manifest_for_files(
    authorization: &GatewayFormalBackendExecutionAuthorizationRequest,
    request: &GatewayFormalBackendExecutionAuthorizationOutputRequest,
    files: &BTreeMap<String, Vec<u8>>,
) -> GatewayFormalBackendExecutionAuthorizationOutputManifest {
    let mut declared_file_digests = BTreeMap::new();
    for (logical_path, bytes) in files {
        declared_file_digests.insert(logical_path.clone(), hash_bytes(bytes));
    }
    GatewayFormalBackendExecutionAuthorizationOutputManifest {
        schema_version: GATEWAY_FORMAL_BACKEND_AUTHORIZATION_OUTPUT_SCHEMA_VERSION.to_owned(),
        bundle_id: request.bundle_id.clone(),
        state_slice: GATEWAY_FORMAL_BACKEND_EXECUTION_AUTHORIZATION_OUTPUT_STATE_SLICE.to_owned(),
        created_at_unix: request.created_at_unix,
        authorization_request_digest: authorization.digest(),
        preflight_bundle_manifest_digest: authorization.preflight_bundle_manifest_digest,
        preflight_request_digest: authorization.preflight_request_digest,
        preflight_report_digest: authorization.preflight_report_digest,
        transcript_metadata_digest: authorization.transcript_metadata_digest,
        transcript_output_manifest_digest: authorization.transcript_output_manifest_digest,
        command_descriptor_digest: authorization.command_descriptor_digest,
        environment_descriptor_digest: authorization.environment_descriptor_digest,
        artifact_root_descriptor_digest: authorization.artifact_root_descriptor_digest,
        operator_acknowledgement_digest: authorization.operator_acknowledgement_digest,
        redaction_policy_digest: authorization.redaction_policy_digest,
        backend_kind: authorization.backend_kind.clone(),
        tool_name: authorization.tool_name.clone(),
        tool_version: authorization.tool_version.clone(),
        toolchain_lock_digest: authorization.toolchain_lock_digest,
        executable_path_label: authorization.executable_path_label.clone(),
        argv_digest: hash_tagged(
            "hsai-agent-admission:gateway-formal-backend-authorization-argv:v1",
            &authorization.argv,
        ),
        environment_binding_digest: hash_bytes(
            files
                .get("gateway-formal-backend-authorization/environment-binding.json")
                .map(Vec::as_slice)
                .unwrap_or_default(),
        ),
        quarantine_descriptor_digest: hash_bytes(
            files
                .get("gateway-formal-backend-authorization/quarantine-descriptor.json")
                .map(Vec::as_slice)
                .unwrap_or_default(),
        ),
        nonclaims_digest: hash_bytes(
            files
                .get("gateway-formal-backend-authorization/nonclaims.md")
                .map(Vec::as_slice)
                .unwrap_or_default(),
        ),
        declared_files: gateway_formal_backend_execution_authorization_output_declared_files(),
        declared_file_digests,
        claim_boundary: gateway_formal_backend_execution_authorization_output_claim_boundary(),
        command_spawned: false,
        backend_executed: false,
        proof_artifact_created: false,
        checker_transcript_created: false,
        checker_succeeded: false,
        creates_accepted_evidence: false,
        creates_level2_evidence: false,
        populates_score_axes: false,
        grants_authority: false,
        nonclaims: authorization.nonclaims.clone(),
    }
}

fn validate_gateway_formal_backend_authorization_bundle_semantics(
    files: &BTreeMap<String, Vec<u8>>,
) -> Result<
    GatewayFormalBackendExecutionAuthorizationOutputManifest,
    GatewayFormalBackendExecutionAuthorizationOutputError,
> {
    let manifest: GatewayFormalBackendExecutionAuthorizationOutputManifest =
        parse_gateway_formal_backend_authorization_declared_json(
            files,
            "gateway-formal-backend-authorization/manifest.json",
        )?;
    let authorization: GatewayFormalBackendExecutionAuthorizationRequest =
        parse_gateway_formal_backend_authorization_declared_json(
            files,
            "gateway-formal-backend-authorization/authorization-request.json",
        )?;
    let preflight_binding: GatewayFormalBackendExecutionAuthorizationPreflightBinding =
        parse_gateway_formal_backend_authorization_declared_json(
            files,
            "gateway-formal-backend-authorization/preflight-binding.json",
        )?;
    let transcript_binding: GatewayFormalBackendExecutionAuthorizationTranscriptBinding =
        parse_gateway_formal_backend_authorization_declared_json(
            files,
            "gateway-formal-backend-authorization/transcript-binding.json",
        )?;
    let command_binding: GatewayFormalBackendExecutionAuthorizationCommandBinding =
        parse_gateway_formal_backend_authorization_declared_json(
            files,
            "gateway-formal-backend-authorization/command-binding.json",
        )?;
    let environment_binding: GatewayFormalBackendExecutionAuthorizationEnvironmentBinding =
        parse_gateway_formal_backend_authorization_declared_json(
            files,
            "gateway-formal-backend-authorization/environment-binding.json",
        )?;
    let quarantine_descriptor: GatewayFormalBackendExecutionAuthorizationQuarantineDescriptor =
        parse_gateway_formal_backend_authorization_declared_json(
            files,
            "gateway-formal-backend-authorization/quarantine-descriptor.json",
        )?;
    let operator_acknowledgement:
        GatewayFormalBackendExecutionAuthorizationOperatorAcknowledgement =
        parse_gateway_formal_backend_authorization_declared_json(
            files,
            "gateway-formal-backend-authorization/operator-acknowledgement.json",
        )?;

    let shape_validation =
        validate_gateway_formal_backend_execution_authorization_request_shape(&authorization);
    if !shape_validation.valid {
        return Err(
            GatewayFormalBackendExecutionAuthorizationOutputError::InvalidAuthorization(
                shape_validation.issues,
            ),
        );
    }
    if preflight_binding != gateway_formal_backend_authorization_preflight_binding(&authorization) {
        return Err(
            GatewayFormalBackendExecutionAuthorizationOutputError::PreflightBindingMismatch,
        );
    }
    if transcript_binding != gateway_formal_backend_authorization_transcript_binding(&authorization)
    {
        return Err(
            GatewayFormalBackendExecutionAuthorizationOutputError::TranscriptBindingMismatch,
        );
    }
    if command_binding != gateway_formal_backend_authorization_command_binding(&authorization) {
        return Err(GatewayFormalBackendExecutionAuthorizationOutputError::CommandBindingMismatch);
    }
    if environment_binding
        != gateway_formal_backend_authorization_environment_binding(&authorization)
    {
        return Err(
            GatewayFormalBackendExecutionAuthorizationOutputError::EnvironmentBindingMismatch,
        );
    }
    if quarantine_descriptor != authorization.quarantine_descriptor {
        return Err(
            GatewayFormalBackendExecutionAuthorizationOutputError::QuarantineDescriptorMismatch,
        );
    }
    if operator_acknowledgement != authorization.operator_acknowledgement {
        return Err(
            GatewayFormalBackendExecutionAuthorizationOutputError::OperatorAcknowledgementMismatch,
        );
    }
    if declared_gateway_formal_backend_authorization_bytes(
        files,
        "gateway-formal-backend-authorization/nonclaims.md",
    )? != render_gateway_formal_backend_authorization_nonclaims(&authorization.nonclaims)
        .as_bytes()
    {
        return Err(GatewayFormalBackendExecutionAuthorizationOutputError::NonclaimMismatch);
    }

    let expected_request = GatewayFormalBackendExecutionAuthorizationOutputRequest {
        bundle_id: manifest.bundle_id.clone(),
        created_at_unix: manifest.created_at_unix,
        overwrite: false,
        protected_roots: Vec::new(),
    };
    validate_gateway_formal_backend_authorization_manifest_semantics(
        &manifest,
        &authorization,
        &expected_request,
        files,
    )?;
    Ok(manifest)
}

fn validate_gateway_formal_backend_execution_authorization_request_shape(
    request: &GatewayFormalBackendExecutionAuthorizationRequest,
) -> GatewayFormalBackendExecutionAuthorizationValidation {
    let mut issues = Vec::new();
    if request.schema_version != GATEWAY_FORMAL_BACKEND_EXECUTION_AUTHORIZATION_SCHEMA_VERSION {
        issues.push(GatewayFormalBackendExecutionAuthorizationIssue::InvalidSchemaVersion);
    }
    if request.authorization_id.trim().is_empty()
        || !is_safe_relative_path(&request.authorization_id)
        || request.authorization_id.contains(['/', '\\'])
    {
        issues.push(GatewayFormalBackendExecutionAuthorizationIssue::InvalidAuthorizationId);
    }
    if request.state_slice != GATEWAY_FORMAL_BACKEND_EXECUTION_AUTHORIZATION_STATE_SLICE {
        issues.push(GatewayFormalBackendExecutionAuthorizationIssue::StateSliceMismatch);
    }
    if request.preflight_bundle_manifest_digest == Hash([0; 32]) {
        issues
            .push(GatewayFormalBackendExecutionAuthorizationIssue::PreflightManifestDigestMismatch);
    }
    if request.preflight_request_digest == Hash([0; 32]) {
        issues
            .push(GatewayFormalBackendExecutionAuthorizationIssue::PreflightRequestDigestMismatch);
    }
    if request.preflight_report_digest == Hash([0; 32]) {
        issues.push(GatewayFormalBackendExecutionAuthorizationIssue::PreflightReportDigestMismatch);
    }
    if request.transcript_metadata_digest == Hash([0; 32]) {
        issues.push(
            GatewayFormalBackendExecutionAuthorizationIssue::TranscriptMetadataDigestMismatch,
        );
    }
    if request.transcript_output_manifest_digest == Hash([0; 32]) {
        issues.push(
            GatewayFormalBackendExecutionAuthorizationIssue::TranscriptOutputManifestDigestMismatch,
        );
    }
    if request.command_descriptor_digest == Hash([0; 32]) {
        issues
            .push(GatewayFormalBackendExecutionAuthorizationIssue::CommandDescriptorDigestMismatch);
    }
    if request.environment_descriptor_digest == Hash([0; 32]) {
        issues.push(
            GatewayFormalBackendExecutionAuthorizationIssue::EnvironmentDescriptorDigestMismatch,
        );
    }
    if request.artifact_root_descriptor_digest == Hash([0; 32]) {
        issues.push(
            GatewayFormalBackendExecutionAuthorizationIssue::ArtifactRootDescriptorDigestMismatch,
        );
    }
    if request.operator_acknowledgement_digest != request.operator_acknowledgement.digest()
        || request.operator_acknowledgement_digest == Hash([0; 32])
    {
        issues.push(
            GatewayFormalBackendExecutionAuthorizationIssue::OperatorAcknowledgementDigestMismatch,
        );
    }
    if request.redaction_policy_digest == Hash([0; 32]) {
        issues.push(GatewayFormalBackendExecutionAuthorizationIssue::RedactionPolicyDigestMismatch);
    }
    if request.tool_name.trim().is_empty() {
        issues.push(GatewayFormalBackendExecutionAuthorizationIssue::ToolNameMismatch);
    }
    if request.tool_version.trim().is_empty() {
        issues.push(GatewayFormalBackendExecutionAuthorizationIssue::ToolVersionMismatch);
    }
    if request.toolchain_lock_digest == Hash([0; 32]) {
        issues.push(GatewayFormalBackendExecutionAuthorizationIssue::ToolchainLockDigestMismatch);
    }
    if request.executable_path_label.trim().is_empty()
        || !is_safe_relative_path(&request.executable_path_label)
        || path_label_is_protected(&request.executable_path_label)
        || has_shell_metacharacters(&request.executable_path_label)
    {
        issues.push(GatewayFormalBackendExecutionAuthorizationIssue::ExecutablePathMismatch);
    }
    if request.argv.is_empty()
        || request
            .argv
            .iter()
            .any(|arg| arg.trim().is_empty() || arg.contains('\0') || has_shell_metacharacters(arg))
    {
        issues.push(GatewayFormalBackendExecutionAuthorizationIssue::ArgvMismatch);
    }
    if request.timeout_seconds == 0 || request.timeout_seconds > 3_600 {
        issues.push(GatewayFormalBackendExecutionAuthorizationIssue::InvalidTimeout);
    }
    if request.max_output_bytes_retained == 0 || request.max_output_bytes_retained > 1_048_576 {
        issues.push(GatewayFormalBackendExecutionAuthorizationIssue::InvalidOutputRetentionLimit);
    }
    validate_gateway_formal_backend_execution_authorization_environment_shape(request, &mut issues);
    validate_gateway_formal_backend_execution_authorization_quarantine_shape(request, &mut issues);
    validate_gateway_formal_backend_execution_authorization_operator_ack_shape(
        request,
        &mut issues,
    );
    validate_gateway_formal_backend_execution_authorization_nonpromotion_shape(
        request,
        &mut issues,
    );

    GatewayFormalBackendExecutionAuthorizationValidation {
        valid: issues.is_empty(),
        issues,
    }
}

fn validate_gateway_formal_backend_execution_authorization_environment_shape(
    request: &GatewayFormalBackendExecutionAuthorizationRequest,
    issues: &mut Vec<GatewayFormalBackendExecutionAuthorizationIssue>,
) {
    if !request.network_disabled {
        issues.push(GatewayFormalBackendExecutionAuthorizationIssue::NetworkPolicyEnabled);
    }
    if !request.no_secrets {
        issues.push(GatewayFormalBackendExecutionAuthorizationIssue::SecretPolicyEnabled);
    }
    for name in &request.allowed_environment_variables {
        if !is_safe_environment_variable_name(name) {
            issues.push(
                GatewayFormalBackendExecutionAuthorizationIssue::InvalidEnvironmentVariableName(
                    name.clone(),
                ),
            );
        }
    }
    for (name, value) in &request.environment_variables {
        if !is_safe_environment_variable_name(name) {
            issues.push(
                GatewayFormalBackendExecutionAuthorizationIssue::InvalidEnvironmentVariableName(
                    name.clone(),
                ),
            );
        }
        if !request.allowed_environment_variables.contains(name) {
            issues.push(
                GatewayFormalBackendExecutionAuthorizationIssue::EnvironmentVariableNotAllowed(
                    name.clone(),
                ),
            );
        }
        if looks_like_credential_name(name) || looks_like_credential_value(value) {
            issues.push(
                GatewayFormalBackendExecutionAuthorizationIssue::CredentialLookingEnvironmentValue(
                    name.clone(),
                ),
            );
        }
    }
}

fn validate_gateway_formal_backend_execution_authorization_quarantine_shape(
    request: &GatewayFormalBackendExecutionAuthorizationRequest,
    issues: &mut Vec<GatewayFormalBackendExecutionAuthorizationIssue>,
) {
    let quarantine = &request.quarantine_descriptor;
    if quarantine.logical_root.trim().is_empty()
        || !is_safe_relative_path(&quarantine.logical_root)
        || quarantine.path_label.trim().is_empty()
        || !is_safe_relative_path(&quarantine.path_label)
        || path_label_is_protected(&quarantine.path_label)
    {
        issues.push(GatewayFormalBackendExecutionAuthorizationIssue::InvalidQuarantineRoot);
    }
    if quarantine.overwrite {
        issues.push(
            GatewayFormalBackendExecutionAuthorizationIssue::QuarantineRootOverwriteRequested,
        );
    }
    if quarantine.repository_root {
        issues
            .push(GatewayFormalBackendExecutionAuthorizationIssue::QuarantineRootIsRepositoryRoot);
    }
    if quarantine.inside_protected_root {
        issues.push(
            GatewayFormalBackendExecutionAuthorizationIssue::QuarantineRootInsideProtectedRoot,
        );
    }
    if quarantine.existing_file {
        issues.push(GatewayFormalBackendExecutionAuthorizationIssue::QuarantineRootIsFile);
    }
    if quarantine.symlink {
        issues.push(GatewayFormalBackendExecutionAuthorizationIssue::QuarantineRootIsSymlink);
    }
    if quarantine.traverses_symlink_parent {
        issues.push(
            GatewayFormalBackendExecutionAuthorizationIssue::QuarantineRootTraversesSymlinkParent,
        );
    }
    if quarantine.accepted_evidence_ledger_path {
        issues.push(
            GatewayFormalBackendExecutionAuthorizationIssue::QuarantineRootAcceptedEvidenceLedgerPath,
        );
    }
    if quarantine.benchmark_output_path {
        issues.push(
            GatewayFormalBackendExecutionAuthorizationIssue::QuarantineRootBenchmarkOutputPath,
        );
    }
    if quarantine.source_correspondence_bundle_path {
        issues.push(
            GatewayFormalBackendExecutionAuthorizationIssue::QuarantineRootSourceCorrespondenceBundlePath,
        );
    }
    if quarantine.backend_run_input_bundle_path {
        issues.push(
            GatewayFormalBackendExecutionAuthorizationIssue::QuarantineRootBackendRunInputBundlePath,
        );
    }
    if quarantine.preflight_output_bundle_path {
        issues.push(
            GatewayFormalBackendExecutionAuthorizationIssue::QuarantineRootPreflightOutputBundlePath,
        );
    }
    if quarantine.transcript_output_bundle_path {
        issues.push(
            GatewayFormalBackendExecutionAuthorizationIssue::QuarantineRootTranscriptOutputBundlePath,
        );
    }
}

fn validate_gateway_formal_backend_execution_authorization_operator_ack_shape(
    request: &GatewayFormalBackendExecutionAuthorizationRequest,
    issues: &mut Vec<GatewayFormalBackendExecutionAuthorizationIssue>,
) {
    let acknowledgement = &request.operator_acknowledgement;
    if acknowledgement.operator_id.trim().is_empty()
        || acknowledgement.acknowledgement_id.trim().is_empty()
        || !is_safe_relative_path(&acknowledgement.acknowledgement_id)
        || acknowledgement.acknowledged_at_unix == 0
    {
        issues
            .push(GatewayFormalBackendExecutionAuthorizationIssue::MissingOperatorAcknowledgement);
    }
    if acknowledgement.authorization_id_acknowledged != request.authorization_id
        || acknowledgement.backend_kind_acknowledged != request.backend_kind
        || acknowledgement.command_descriptor_digest_acknowledged
            != request.command_descriptor_digest
        || acknowledgement.preflight_bundle_manifest_digest_acknowledged
            != request.preflight_bundle_manifest_digest
        || acknowledgement.transcript_output_manifest_digest_acknowledged
            != request.transcript_output_manifest_digest
        || acknowledgement.quarantine_descriptor_digest_acknowledged
            != request.quarantine_descriptor.digest()
        || !acknowledgement.no_process_spawn_acknowledged
        || !acknowledgement.no_network_policy_acknowledged
        || !acknowledgement.no_secret_policy_acknowledged
        || !acknowledgement.quarantine_only_acknowledged
        || !acknowledgement.nonpromotion_policy_acknowledged
        || !acknowledgement.checker_success_not_semantic_correctness_acknowledged
        || !acknowledgement.proof_checker_artifacts_not_accepted_evidence_acknowledged
    {
        issues
            .push(GatewayFormalBackendExecutionAuthorizationIssue::OperatorAcknowledgementMismatch);
    }
    if acknowledgement.grants_authority {
        issues.push(
            GatewayFormalBackendExecutionAuthorizationIssue::OperatorAcknowledgementGrantsAuthority,
        );
    }
}

fn validate_gateway_formal_backend_execution_authorization_nonpromotion_shape(
    request: &GatewayFormalBackendExecutionAuthorizationRequest,
    issues: &mut Vec<GatewayFormalBackendExecutionAuthorizationIssue>,
) {
    if !request.proof_obligations_requested.is_empty() {
        issues.push(
            GatewayFormalBackendExecutionAuthorizationIssue::ProofObligationsRequestedBeforeExecution,
        );
    }
    if request.claim_boundary != gateway_formal_backend_execution_authorization_claim_boundary() {
        issues.push(GatewayFormalBackendExecutionAuthorizationIssue::ClaimBoundaryMismatch);
    }
    if request.command_spawned {
        issues.push(GatewayFormalBackendExecutionAuthorizationIssue::CommandSpawned);
    }
    if request.backend_executed {
        issues.push(GatewayFormalBackendExecutionAuthorizationIssue::BackendExecuted);
    }
    if request.proof_artifact_created {
        issues.push(GatewayFormalBackendExecutionAuthorizationIssue::ProofArtifactCreated);
    }
    if request.checker_transcript_created {
        issues.push(GatewayFormalBackendExecutionAuthorizationIssue::CheckerTranscriptCreated);
    }
    if request.checker_succeeded {
        issues.push(GatewayFormalBackendExecutionAuthorizationIssue::CheckerSucceeded);
    }
    if request.creates_accepted_evidence {
        issues.push(GatewayFormalBackendExecutionAuthorizationIssue::AcceptedEvidenceCreated);
    }
    if request.creates_level2_evidence {
        issues.push(GatewayFormalBackendExecutionAuthorizationIssue::Level2EvidenceCreated);
    }
    if request.populates_score_axes {
        issues.push(GatewayFormalBackendExecutionAuthorizationIssue::ScoreAxesPopulated);
    }
    if request.grants_authority {
        issues.push(GatewayFormalBackendExecutionAuthorizationIssue::AuthorityGranted);
    }
    if request.semantic_correctness_claimed {
        issues.push(GatewayFormalBackendExecutionAuthorizationIssue::SemanticCorrectnessClaimed);
    }
    if request.production_readiness_claimed {
        issues.push(GatewayFormalBackendExecutionAuthorizationIssue::ProductionReadinessClaimed);
    }
    if request.sota_claimed {
        issues.push(GatewayFormalBackendExecutionAuthorizationIssue::SotaClaimed);
    }
    if request.full_security_claimed {
        issues.push(GatewayFormalBackendExecutionAuthorizationIssue::FullSecurityClaimed);
    }
    for forbidden in gateway_formal_evidence_forbidden_claim_fragments() {
        if request
            .claim_text
            .iter()
            .any(|text| text.to_ascii_lowercase().contains(forbidden))
        {
            issues.push(
                GatewayFormalBackendExecutionAuthorizationIssue::ForbiddenClaimText(
                    (*forbidden).to_owned(),
                ),
            );
        }
    }
    for required in gateway_formal_backend_execution_authorization_required_nonclaims() {
        if !request.nonclaims.contains(&required) {
            issues.push(
                GatewayFormalBackendExecutionAuthorizationIssue::MissingRequiredNonclaim(
                    required.0,
                ),
            );
        }
    }
}

fn validate_gateway_formal_backend_authorization_manifest_semantics(
    manifest: &GatewayFormalBackendExecutionAuthorizationOutputManifest,
    authorization: &GatewayFormalBackendExecutionAuthorizationRequest,
    request: &GatewayFormalBackendExecutionAuthorizationOutputRequest,
    files: &BTreeMap<String, Vec<u8>>,
) -> Result<(), GatewayFormalBackendExecutionAuthorizationOutputError> {
    let expected_digest_paths: BTreeSet<String> =
        GATEWAY_FORMAL_BACKEND_AUTHORIZATION_DECLARED_FILES
            .iter()
            .filter(|path| **path != "gateway-formal-backend-authorization/manifest.json")
            .map(|path| (*path).to_owned())
            .collect();
    let actual_digest_paths: BTreeSet<String> =
        manifest.declared_file_digests.keys().cloned().collect();
    if manifest.schema_version != GATEWAY_FORMAL_BACKEND_AUTHORIZATION_OUTPUT_SCHEMA_VERSION
        || manifest.bundle_id != request.bundle_id
        || manifest.state_slice != GATEWAY_FORMAL_BACKEND_EXECUTION_AUTHORIZATION_OUTPUT_STATE_SLICE
        || manifest.created_at_unix != request.created_at_unix
        || manifest.authorization_request_digest != authorization.digest()
        || manifest.preflight_bundle_manifest_digest
            != authorization.preflight_bundle_manifest_digest
        || manifest.preflight_request_digest != authorization.preflight_request_digest
        || manifest.preflight_report_digest != authorization.preflight_report_digest
        || manifest.transcript_metadata_digest != authorization.transcript_metadata_digest
        || manifest.transcript_output_manifest_digest
            != authorization.transcript_output_manifest_digest
        || manifest.command_descriptor_digest != authorization.command_descriptor_digest
        || manifest.environment_descriptor_digest != authorization.environment_descriptor_digest
        || manifest.artifact_root_descriptor_digest != authorization.artifact_root_descriptor_digest
        || manifest.operator_acknowledgement_digest != authorization.operator_acknowledgement_digest
        || manifest.redaction_policy_digest != authorization.redaction_policy_digest
        || manifest.backend_kind != authorization.backend_kind
        || manifest.tool_name != authorization.tool_name
        || manifest.tool_version != authorization.tool_version
        || manifest.toolchain_lock_digest != authorization.toolchain_lock_digest
        || manifest.executable_path_label != authorization.executable_path_label
        || manifest.argv_digest
            != hash_tagged(
                "hsai-agent-admission:gateway-formal-backend-authorization-argv:v1",
                &authorization.argv,
            )
        || manifest.environment_binding_digest
            != hash_bytes(declared_gateway_formal_backend_authorization_bytes(
                files,
                "gateway-formal-backend-authorization/environment-binding.json",
            )?)
        || manifest.quarantine_descriptor_digest
            != hash_bytes(declared_gateway_formal_backend_authorization_bytes(
                files,
                "gateway-formal-backend-authorization/quarantine-descriptor.json",
            )?)
        || manifest.nonclaims_digest
            != hash_bytes(declared_gateway_formal_backend_authorization_bytes(
                files,
                "gateway-formal-backend-authorization/nonclaims.md",
            )?)
        || manifest.declared_files
            != gateway_formal_backend_execution_authorization_output_declared_files()
        || actual_digest_paths != expected_digest_paths
        || manifest
            .declared_file_digests
            .values()
            .any(|digest| *digest == Hash([0; 32]))
        || manifest.claim_boundary
            != gateway_formal_backend_execution_authorization_output_claim_boundary()
        || manifest.command_spawned
        || manifest.backend_executed
        || manifest.proof_artifact_created
        || manifest.checker_transcript_created
        || manifest.checker_succeeded
        || manifest.creates_accepted_evidence
        || manifest.creates_level2_evidence
        || manifest.populates_score_axes
        || manifest.grants_authority
        || manifest.nonclaims != authorization.nonclaims
    {
        return Err(
            GatewayFormalBackendExecutionAuthorizationOutputError::ManifestSemanticMismatch,
        );
    }
    for (logical_path, expected_digest) in &manifest.declared_file_digests {
        if hash_bytes(declared_gateway_formal_backend_authorization_bytes(
            files,
            logical_path,
        )?) != *expected_digest
        {
            return Err(
                GatewayFormalBackendExecutionAuthorizationOutputError::DigestMismatch(
                    logical_path.clone(),
                ),
            );
        }
    }
    Ok(())
}

fn gateway_formal_backend_authorization_preflight_binding(
    authorization: &GatewayFormalBackendExecutionAuthorizationRequest,
) -> GatewayFormalBackendExecutionAuthorizationPreflightBinding {
    GatewayFormalBackendExecutionAuthorizationPreflightBinding {
        preflight_bundle_manifest_digest: authorization.preflight_bundle_manifest_digest,
        preflight_request_digest: authorization.preflight_request_digest,
        preflight_report_digest: authorization.preflight_report_digest,
        command_descriptor_digest: authorization.command_descriptor_digest,
        environment_descriptor_digest: authorization.environment_descriptor_digest,
        artifact_root_descriptor_digest: authorization.artifact_root_descriptor_digest,
        redaction_policy_digest: authorization.redaction_policy_digest,
    }
}

fn gateway_formal_backend_authorization_transcript_binding(
    authorization: &GatewayFormalBackendExecutionAuthorizationRequest,
) -> GatewayFormalBackendExecutionAuthorizationTranscriptBinding {
    GatewayFormalBackendExecutionAuthorizationTranscriptBinding {
        transcript_metadata_digest: authorization.transcript_metadata_digest,
        transcript_output_manifest_digest: authorization.transcript_output_manifest_digest,
    }
}

fn gateway_formal_backend_authorization_command_binding(
    authorization: &GatewayFormalBackendExecutionAuthorizationRequest,
) -> GatewayFormalBackendExecutionAuthorizationCommandBinding {
    GatewayFormalBackendExecutionAuthorizationCommandBinding {
        command_descriptor_digest: authorization.command_descriptor_digest,
        backend_kind: authorization.backend_kind.clone(),
        tool_name: authorization.tool_name.clone(),
        tool_version: authorization.tool_version.clone(),
        toolchain_lock_digest: authorization.toolchain_lock_digest,
        executable_path_label: authorization.executable_path_label.clone(),
        argv: authorization.argv.clone(),
        timeout_seconds: authorization.timeout_seconds,
        max_output_bytes_retained: authorization.max_output_bytes_retained,
    }
}

fn gateway_formal_backend_authorization_environment_binding(
    authorization: &GatewayFormalBackendExecutionAuthorizationRequest,
) -> GatewayFormalBackendExecutionAuthorizationEnvironmentBinding {
    GatewayFormalBackendExecutionAuthorizationEnvironmentBinding {
        environment_descriptor_digest: authorization.environment_descriptor_digest,
        allowed_environment_variables: authorization.allowed_environment_variables.clone(),
        environment_variables: authorization.environment_variables.clone(),
        network_disabled: authorization.network_disabled,
        no_secrets: authorization.no_secrets,
    }
}

fn render_gateway_formal_backend_authorization_nonclaims(
    nonclaims: &BTreeSet<NonClaimLabel>,
) -> String {
    let mut out = String::from("# Gateway Formal Backend Authorization Nonclaims\n\n");
    for nonclaim in nonclaims {
        out.push_str("- ");
        out.push_str(&nonclaim.0);
        out.push('\n');
    }
    out
}

fn declared_gateway_formal_backend_authorization_bytes<'a>(
    files: &'a BTreeMap<String, Vec<u8>>,
    logical_path: &str,
) -> Result<&'a [u8], GatewayFormalBackendExecutionAuthorizationOutputError> {
    files.get(logical_path).map(Vec::as_slice).ok_or_else(|| {
        GatewayFormalBackendExecutionAuthorizationOutputError::Io(format!(
            "declared file missing: {logical_path}"
        ))
    })
}

fn parse_gateway_formal_backend_authorization_declared_json<T: for<'de> Deserialize<'de>>(
    files: &BTreeMap<String, Vec<u8>>,
    logical_path: &str,
) -> Result<T, GatewayFormalBackendExecutionAuthorizationOutputError> {
    let bytes = declared_gateway_formal_backend_authorization_bytes(files, logical_path)?;
    let text = std::str::from_utf8(bytes).map_err(|_| {
        GatewayFormalBackendExecutionAuthorizationOutputError::MalformedDeclaredFile(
            logical_path.to_owned(),
        )
    })?;
    serde_json::from_str(text).map_err(|_| {
        GatewayFormalBackendExecutionAuthorizationOutputError::MalformedDeclaredFile(
            logical_path.to_owned(),
        )
    })
}

fn reject_undeclared_gateway_formal_backend_authorization_files(
    output_root: &Path,
) -> Result<(), GatewayFormalBackendExecutionAuthorizationOutputError> {
    let mut declared: BTreeSet<String> = GATEWAY_FORMAL_BACKEND_AUTHORIZATION_DECLARED_FILES
        .iter()
        .chain(GATEWAY_FORMAL_BACKEND_AUTHORIZATION_DECLARED_SIDECARS.iter())
        .map(|value| (*value).to_owned())
        .collect();
    let bundle_dir = output_root.join("gateway-formal-backend-authorization");
    for entry in fs::read_dir(&bundle_dir).map_err(gateway_formal_backend_authorization_io_error)? {
        let entry = entry.map_err(gateway_formal_backend_authorization_io_error)?;
        let logical_path = entry
            .path()
            .strip_prefix(output_root)
            .map_err(|error| {
                GatewayFormalBackendExecutionAuthorizationOutputError::Io(error.to_string())
            })?
            .to_string_lossy()
            .replace('\\', "/");
        if !declared.remove(&logical_path) {
            return Err(
                GatewayFormalBackendExecutionAuthorizationOutputError::UndeclaredFile(logical_path),
            );
        }
    }
    if let Some(missing) = declared.into_iter().next() {
        return Err(GatewayFormalBackendExecutionAuthorizationOutputError::Io(
            format!("declared file missing: {missing}"),
        ));
    }
    Ok(())
}

fn validate_gateway_formal_backend_authorization_output_root(
    output_root: &Path,
    protected_roots: &[PathBuf],
    overwrite: bool,
) -> Result<(), GatewayFormalBackendExecutionAuthorizationOutputError> {
    match validate_output_root(output_root, protected_roots, overwrite) {
        Ok(()) => Ok(()),
        Err(AdmissionJournalMaterializationError::EmptyOutputRoot) => {
            Err(GatewayFormalBackendExecutionAuthorizationOutputError::EmptyOutputRoot)
        }
        Err(AdmissionJournalMaterializationError::ProtectedOutputRoot) => {
            Err(GatewayFormalBackendExecutionAuthorizationOutputError::ProtectedOutputRoot)
        }
        Err(AdmissionJournalMaterializationError::OutputRootExistsWithoutOverwrite) => Err(
            GatewayFormalBackendExecutionAuthorizationOutputError::OutputRootExistsWithoutOverwrite,
        ),
        Err(AdmissionJournalMaterializationError::OutputRootIsFile) => {
            Err(GatewayFormalBackendExecutionAuthorizationOutputError::OutputRootIsFile)
        }
        Err(AdmissionJournalMaterializationError::OutputRootIsSymlink) => {
            Err(GatewayFormalBackendExecutionAuthorizationOutputError::OutputRootIsSymlink)
        }
        Err(AdmissionJournalMaterializationError::Io(error)) => Err(
            GatewayFormalBackendExecutionAuthorizationOutputError::Io(error),
        ),
        Err(other) => Err(GatewayFormalBackendExecutionAuthorizationOutputError::Io(
            format!("{other:?}"),
        )),
    }
}

fn gateway_formal_backend_authorization_staging_root_for(
    output_root: &Path,
    bundle_id: &str,
) -> Result<PathBuf, GatewayFormalBackendExecutionAuthorizationOutputError> {
    let parent = output_root
        .parent()
        .ok_or(GatewayFormalBackendExecutionAuthorizationOutputError::EmptyOutputRoot)?;
    let name = output_root
        .file_name()
        .map(|value| value.to_string_lossy().into_owned())
        .ok_or(GatewayFormalBackendExecutionAuthorizationOutputError::EmptyOutputRoot)?;
    Ok(parent.join(format!(".{name}.{bundle_id}.staging")))
}

fn remove_gateway_formal_backend_authorization_dir_all_checked(
    path: &Path,
) -> Result<(), GatewayFormalBackendExecutionAuthorizationOutputError> {
    if !path.exists() {
        return Ok(());
    }
    if fs::symlink_metadata(path)
        .map_err(gateway_formal_backend_authorization_io_error)?
        .file_type()
        .is_symlink()
    {
        return Err(GatewayFormalBackendExecutionAuthorizationOutputError::OutputRootIsSymlink);
    }
    fs::remove_dir_all(path).map_err(gateway_formal_backend_authorization_io_error)
}

fn gateway_formal_backend_authorization_io_error(
    error: io::Error,
) -> GatewayFormalBackendExecutionAuthorizationOutputError {
    GatewayFormalBackendExecutionAuthorizationOutputError::Io(error.to_string())
}

fn gateway_formal_backend_authorization_serde_error(
    error: serde_json::Error,
) -> GatewayFormalBackendExecutionAuthorizationOutputError {
    GatewayFormalBackendExecutionAuthorizationOutputError::Serialization(error.to_string())
}

fn validate_gateway_formal_backend_execution_quarantine_output_request(
    output_root: &Path,
    metadata: &GatewayFormalBackendExecutionQuarantineArtifactMetadata,
    authorization: &GatewayFormalBackendExecutionAuthorizationRequest,
    authorization_output_manifest: &GatewayFormalBackendExecutionAuthorizationOutputManifest,
    request: &GatewayFormalBackendExecutionQuarantineOutputRequest,
) -> Result<(), GatewayFormalBackendExecutionQuarantineOutputError> {
    if request.bundle_id.trim().is_empty()
        || !is_safe_relative_path(&request.bundle_id)
        || request.bundle_id.contains(['/', '\\'])
    {
        return Err(GatewayFormalBackendExecutionQuarantineOutputError::EmptyBundleId);
    }
    let validation = validate_gateway_formal_backend_execution_quarantine_artifact_metadata(
        metadata,
        authorization,
        authorization_output_manifest,
    );
    if !validation.valid {
        return Err(
            GatewayFormalBackendExecutionQuarantineOutputError::InvalidQuarantineArtifact(
                validation.issues,
            ),
        );
    }
    let expected_metadata = build_gateway_formal_backend_execution_quarantine_artifact_metadata(
        metadata.artifact_id.clone(),
        authorization,
        authorization_output_manifest,
        metadata.started_at_unix,
        metadata.finished_at_unix,
        metadata.process_exit_status,
        metadata.timed_out,
        metadata.signaled,
        metadata.stdout_summary.clone(),
        metadata.stderr_summary.clone(),
        metadata.redaction_report.clone(),
        metadata.output_file_inventory.clone(),
        metadata.proof_checker_nonpromotion_report.clone(),
        metadata.checker_succeeded,
    );
    if metadata != &expected_metadata {
        return Err(GatewayFormalBackendExecutionQuarantineOutputError::QuarantineArtifactMismatch);
    }
    validate_gateway_formal_backend_quarantine_output_root(
        output_root,
        &request.protected_roots,
        request.overwrite,
    )
}

fn build_gateway_formal_backend_quarantine_bundle_files(
    metadata: &GatewayFormalBackendExecutionQuarantineArtifactMetadata,
    request: &GatewayFormalBackendExecutionQuarantineOutputRequest,
) -> Result<BTreeMap<String, Vec<u8>>, GatewayFormalBackendExecutionQuarantineOutputError> {
    let mut files = BTreeMap::new();
    let nonclaims = render_gateway_formal_backend_quarantine_nonclaims(&metadata.nonclaims);
    files.extend([
        (
            "gateway-formal-backend-quarantine/quarantine-artifact.json".to_owned(),
            serde_json::to_vec_pretty(metadata)
                .map_err(gateway_formal_backend_quarantine_serde_error)?,
        ),
        (
            "gateway-formal-backend-quarantine/authorization-binding.json".to_owned(),
            serde_json::to_vec_pretty(&gateway_formal_backend_quarantine_authorization_binding(
                metadata,
            ))
            .map_err(gateway_formal_backend_quarantine_serde_error)?,
        ),
        (
            "gateway-formal-backend-quarantine/process-status.json".to_owned(),
            serde_json::to_vec_pretty(&gateway_formal_backend_quarantine_process_status(metadata))
                .map_err(gateway_formal_backend_quarantine_serde_error)?,
        ),
        (
            "gateway-formal-backend-quarantine/stdout-summary.json".to_owned(),
            serde_json::to_vec_pretty(&metadata.stdout_summary)
                .map_err(gateway_formal_backend_quarantine_serde_error)?,
        ),
        (
            "gateway-formal-backend-quarantine/stderr-summary.json".to_owned(),
            serde_json::to_vec_pretty(&metadata.stderr_summary)
                .map_err(gateway_formal_backend_quarantine_serde_error)?,
        ),
        (
            "gateway-formal-backend-quarantine/redaction-report.json".to_owned(),
            serde_json::to_vec_pretty(&metadata.redaction_report)
                .map_err(gateway_formal_backend_quarantine_serde_error)?,
        ),
        (
            "gateway-formal-backend-quarantine/output-inventory.json".to_owned(),
            serde_json::to_vec_pretty(&metadata.output_file_inventory)
                .map_err(gateway_formal_backend_quarantine_serde_error)?,
        ),
        (
            "gateway-formal-backend-quarantine/proof-checker-nonpromotion.json".to_owned(),
            serde_json::to_vec_pretty(&metadata.proof_checker_nonpromotion_report)
                .map_err(gateway_formal_backend_quarantine_serde_error)?,
        ),
        (
            "gateway-formal-backend-quarantine/nonclaims.md".to_owned(),
            nonclaims.into_bytes(),
        ),
    ]);
    let manifest =
        gateway_formal_backend_quarantine_output_manifest_for_files(metadata, request, &files);
    files.insert(
        "gateway-formal-backend-quarantine/manifest.json".to_owned(),
        serde_json::to_vec_pretty(&manifest)
            .map_err(gateway_formal_backend_quarantine_serde_error)?,
    );
    Ok(files)
}

fn gateway_formal_backend_quarantine_output_manifest_for_files(
    metadata: &GatewayFormalBackendExecutionQuarantineArtifactMetadata,
    request: &GatewayFormalBackendExecutionQuarantineOutputRequest,
    files: &BTreeMap<String, Vec<u8>>,
) -> GatewayFormalBackendExecutionQuarantineOutputManifest {
    let mut declared_file_digests = BTreeMap::new();
    for (logical_path, bytes) in files {
        declared_file_digests.insert(logical_path.clone(), hash_bytes(bytes));
    }
    GatewayFormalBackendExecutionQuarantineOutputManifest {
        schema_version: GATEWAY_FORMAL_BACKEND_QUARANTINE_OUTPUT_SCHEMA_VERSION.to_owned(),
        bundle_id: request.bundle_id.clone(),
        state_slice: GATEWAY_FORMAL_BACKEND_EXECUTION_QUARANTINE_OUTPUT_STATE_SLICE.to_owned(),
        created_at_unix: request.created_at_unix,
        quarantine_artifact_digest: metadata.digest(),
        authorization_output_manifest_digest: metadata.authorization_output_manifest_digest,
        authorization_request_digest: metadata.authorization_request_digest,
        preflight_output_manifest_digest: metadata.preflight_output_manifest_digest,
        transcript_output_manifest_digest: metadata.transcript_output_manifest_digest,
        command_descriptor_digest: metadata.command_descriptor_digest,
        environment_descriptor_digest: metadata.environment_descriptor_digest,
        quarantine_descriptor_digest: metadata.quarantine_descriptor_digest,
        operator_acknowledgement_digest: metadata.operator_acknowledgement_digest,
        backend_kind: metadata.backend_kind.clone(),
        tool_name: metadata.tool_name.clone(),
        tool_version: metadata.tool_version.clone(),
        toolchain_lock_digest: metadata.toolchain_lock_digest,
        executable_path_label: metadata.executable_path_label.clone(),
        argv_digest: metadata.argv_digest,
        process_status_digest: hash_bytes(
            files
                .get("gateway-formal-backend-quarantine/process-status.json")
                .map(Vec::as_slice)
                .unwrap_or_default(),
        ),
        stdout_summary_digest: hash_bytes(
            files
                .get("gateway-formal-backend-quarantine/stdout-summary.json")
                .map(Vec::as_slice)
                .unwrap_or_default(),
        ),
        stderr_summary_digest: hash_bytes(
            files
                .get("gateway-formal-backend-quarantine/stderr-summary.json")
                .map(Vec::as_slice)
                .unwrap_or_default(),
        ),
        redaction_report_digest: hash_bytes(
            files
                .get("gateway-formal-backend-quarantine/redaction-report.json")
                .map(Vec::as_slice)
                .unwrap_or_default(),
        ),
        output_inventory_digest: hash_bytes(
            files
                .get("gateway-formal-backend-quarantine/output-inventory.json")
                .map(Vec::as_slice)
                .unwrap_or_default(),
        ),
        proof_checker_nonpromotion_report_digest: hash_bytes(
            files
                .get("gateway-formal-backend-quarantine/proof-checker-nonpromotion.json")
                .map(Vec::as_slice)
                .unwrap_or_default(),
        ),
        nonclaims_digest: hash_bytes(
            files
                .get("gateway-formal-backend-quarantine/nonclaims.md")
                .map(Vec::as_slice)
                .unwrap_or_default(),
        ),
        declared_files: gateway_formal_backend_execution_quarantine_output_declared_files(),
        declared_file_digests,
        claim_boundary: gateway_formal_backend_execution_quarantine_output_claim_boundary(),
        command_spawned_by_this_crate: false,
        creates_accepted_evidence: false,
        creates_level2_evidence: false,
        populates_score_axes: false,
        grants_authority: false,
        nonclaims: metadata.nonclaims.clone(),
    }
}

fn validate_gateway_formal_backend_quarantine_bundle_semantics(
    files: &BTreeMap<String, Vec<u8>>,
) -> Result<
    GatewayFormalBackendExecutionQuarantineOutputManifest,
    GatewayFormalBackendExecutionQuarantineOutputError,
> {
    let manifest: GatewayFormalBackendExecutionQuarantineOutputManifest =
        parse_gateway_formal_backend_quarantine_declared_json(
            files,
            "gateway-formal-backend-quarantine/manifest.json",
        )?;
    let metadata: GatewayFormalBackendExecutionQuarantineArtifactMetadata =
        parse_gateway_formal_backend_quarantine_declared_json(
            files,
            "gateway-formal-backend-quarantine/quarantine-artifact.json",
        )?;
    let authorization_binding: GatewayFormalBackendExecutionQuarantineAuthorizationBinding =
        parse_gateway_formal_backend_quarantine_declared_json(
            files,
            "gateway-formal-backend-quarantine/authorization-binding.json",
        )?;
    let process_status: GatewayFormalBackendExecutionQuarantineProcessStatus =
        parse_gateway_formal_backend_quarantine_declared_json(
            files,
            "gateway-formal-backend-quarantine/process-status.json",
        )?;
    let stdout_summary: GatewayFormalBackendExecutionQuarantineOutputSummary =
        parse_gateway_formal_backend_quarantine_declared_json(
            files,
            "gateway-formal-backend-quarantine/stdout-summary.json",
        )?;
    let stderr_summary: GatewayFormalBackendExecutionQuarantineOutputSummary =
        parse_gateway_formal_backend_quarantine_declared_json(
            files,
            "gateway-formal-backend-quarantine/stderr-summary.json",
        )?;
    let redaction_report: GatewayFormalBackendExecutionQuarantineRedactionReport =
        parse_gateway_formal_backend_quarantine_declared_json(
            files,
            "gateway-formal-backend-quarantine/redaction-report.json",
        )?;
    let output_inventory: Vec<GatewayFormalBackendExecutionQuarantineFileReference> =
        parse_gateway_formal_backend_quarantine_declared_json(
            files,
            "gateway-formal-backend-quarantine/output-inventory.json",
        )?;
    let proof_checker_nonpromotion:
        GatewayFormalBackendExecutionQuarantineProofCheckerNonpromotionReport =
        parse_gateway_formal_backend_quarantine_declared_json(
            files,
            "gateway-formal-backend-quarantine/proof-checker-nonpromotion.json",
        )?;

    let shape_validation =
        validate_gateway_formal_backend_execution_quarantine_artifact_metadata_shape(&metadata);
    if !shape_validation.valid {
        return Err(
            GatewayFormalBackendExecutionQuarantineOutputError::InvalidQuarantineArtifact(
                shape_validation.issues,
            ),
        );
    }
    if authorization_binding != gateway_formal_backend_quarantine_authorization_binding(&metadata) {
        return Err(
            GatewayFormalBackendExecutionQuarantineOutputError::AuthorizationBindingMismatch,
        );
    }
    if process_status != gateway_formal_backend_quarantine_process_status(&metadata) {
        return Err(GatewayFormalBackendExecutionQuarantineOutputError::ProcessStatusMismatch);
    }
    if stdout_summary != metadata.stdout_summary
        || metadata.bounded_stdout_summary_digest != stdout_summary.digest()
    {
        return Err(GatewayFormalBackendExecutionQuarantineOutputError::StdoutSummaryMismatch);
    }
    if stderr_summary != metadata.stderr_summary
        || metadata.bounded_stderr_summary_digest != stderr_summary.digest()
    {
        return Err(GatewayFormalBackendExecutionQuarantineOutputError::StderrSummaryMismatch);
    }
    if redaction_report != metadata.redaction_report
        || metadata.redaction_report_digest != redaction_report.digest()
    {
        return Err(GatewayFormalBackendExecutionQuarantineOutputError::RedactionReportMismatch);
    }
    if output_inventory != metadata.output_file_inventory
        || metadata.output_file_inventory_digest
            != gateway_formal_backend_execution_quarantine_output_inventory_digest(
                &output_inventory,
            )
    {
        return Err(GatewayFormalBackendExecutionQuarantineOutputError::OutputInventoryMismatch);
    }
    if proof_checker_nonpromotion != metadata.proof_checker_nonpromotion_report
        || metadata.proof_checker_nonpromotion_report_digest != proof_checker_nonpromotion.digest()
    {
        return Err(
            GatewayFormalBackendExecutionQuarantineOutputError::ProofCheckerNonpromotionMismatch,
        );
    }
    if declared_gateway_formal_backend_quarantine_bytes(
        files,
        "gateway-formal-backend-quarantine/nonclaims.md",
    )? != render_gateway_formal_backend_quarantine_nonclaims(&metadata.nonclaims).as_bytes()
    {
        return Err(GatewayFormalBackendExecutionQuarantineOutputError::NonclaimMismatch);
    }

    let expected_request = GatewayFormalBackendExecutionQuarantineOutputRequest {
        bundle_id: manifest.bundle_id.clone(),
        created_at_unix: manifest.created_at_unix,
        overwrite: false,
        protected_roots: Vec::new(),
    };
    validate_gateway_formal_backend_quarantine_manifest_semantics(
        &manifest,
        &metadata,
        &expected_request,
        files,
    )?;
    Ok(manifest)
}

fn validate_gateway_formal_backend_execution_quarantine_artifact_metadata_shape(
    metadata: &GatewayFormalBackendExecutionQuarantineArtifactMetadata,
) -> GatewayFormalBackendExecutionQuarantineArtifactValidation {
    let mut issues = Vec::new();
    if metadata.schema_version
        != GATEWAY_FORMAL_BACKEND_EXECUTION_QUARANTINE_ARTIFACT_SCHEMA_VERSION
    {
        issues.push(GatewayFormalBackendExecutionQuarantineArtifactIssue::InvalidSchemaVersion);
    }
    if metadata.artifact_id.trim().is_empty()
        || !is_safe_relative_path(&metadata.artifact_id)
        || metadata.artifact_id.contains(['/', '\\'])
    {
        issues.push(GatewayFormalBackendExecutionQuarantineArtifactIssue::InvalidArtifactId);
    }
    if metadata.state_slice != GATEWAY_FORMAL_BACKEND_EXECUTION_QUARANTINE_ARTIFACT_STATE_SLICE {
        issues.push(GatewayFormalBackendExecutionQuarantineArtifactIssue::StateSliceMismatch);
    }
    if metadata.authorization_output_manifest_digest == Hash([0; 32]) {
        issues.push(
            GatewayFormalBackendExecutionQuarantineArtifactIssue::AuthorizationOutputManifestDigestMismatch,
        );
    }
    if metadata.authorization_request_digest == Hash([0; 32]) {
        issues.push(
            GatewayFormalBackendExecutionQuarantineArtifactIssue::AuthorizationRequestDigestMismatch,
        );
    }
    if metadata.preflight_output_manifest_digest == Hash([0; 32]) {
        issues.push(
            GatewayFormalBackendExecutionQuarantineArtifactIssue::PreflightOutputManifestDigestMismatch,
        );
    }
    if metadata.transcript_output_manifest_digest == Hash([0; 32]) {
        issues.push(
            GatewayFormalBackendExecutionQuarantineArtifactIssue::TranscriptOutputManifestDigestMismatch,
        );
    }
    if metadata.command_descriptor_digest == Hash([0; 32]) {
        issues.push(
            GatewayFormalBackendExecutionQuarantineArtifactIssue::CommandDescriptorDigestMismatch,
        );
    }
    if metadata.environment_descriptor_digest == Hash([0; 32]) {
        issues.push(
            GatewayFormalBackendExecutionQuarantineArtifactIssue::EnvironmentDescriptorDigestMismatch,
        );
    }
    if metadata.quarantine_descriptor_digest == Hash([0; 32]) {
        issues.push(
            GatewayFormalBackendExecutionQuarantineArtifactIssue::QuarantineDescriptorDigestMismatch,
        );
    }
    if metadata.operator_acknowledgement_digest == Hash([0; 32]) {
        issues.push(
            GatewayFormalBackendExecutionQuarantineArtifactIssue::OperatorAcknowledgementDigestMismatch,
        );
    }
    if metadata.tool_name.trim().is_empty() {
        issues.push(GatewayFormalBackendExecutionQuarantineArtifactIssue::ToolNameMismatch);
    }
    if metadata.tool_version.trim().is_empty() {
        issues.push(GatewayFormalBackendExecutionQuarantineArtifactIssue::ToolVersionMismatch);
    }
    if metadata.toolchain_lock_digest == Hash([0; 32]) {
        issues.push(
            GatewayFormalBackendExecutionQuarantineArtifactIssue::ToolchainLockDigestMismatch,
        );
    }
    if metadata.executable_path_label.trim().is_empty()
        || !is_safe_relative_path(&metadata.executable_path_label)
        || path_label_is_protected(&metadata.executable_path_label)
    {
        issues.push(GatewayFormalBackendExecutionQuarantineArtifactIssue::ExecutablePathMismatch);
    }
    let expected_argv_digest = hash_tagged(
        "hsai-agent-admission:gateway-formal-backend-execution-quarantine-argv:v1",
        &metadata.argv,
    );
    if metadata.argv.is_empty() || metadata.argv_digest != expected_argv_digest {
        issues.push(GatewayFormalBackendExecutionQuarantineArtifactIssue::ArgvDigestMismatch);
    }
    validate_gateway_formal_backend_execution_quarantine_process_status(metadata, &mut issues);
    validate_gateway_formal_backend_execution_quarantine_output_summary(
        &metadata.stdout_summary,
        "stdout",
        metadata.max_output_bytes_retained,
        &mut issues,
    );
    validate_gateway_formal_backend_execution_quarantine_output_summary(
        &metadata.stderr_summary,
        "stderr",
        metadata.max_output_bytes_retained,
        &mut issues,
    );
    validate_gateway_formal_backend_execution_quarantine_redaction_report(metadata, &mut issues);
    validate_gateway_formal_backend_execution_quarantine_output_inventory(metadata, &mut issues);
    validate_gateway_formal_backend_execution_quarantine_nonpromotion_report(metadata, &mut issues);
    validate_gateway_formal_backend_execution_quarantine_claims(metadata, &mut issues);
    GatewayFormalBackendExecutionQuarantineArtifactValidation {
        valid: issues.is_empty(),
        issues,
    }
}

fn validate_gateway_formal_backend_quarantine_manifest_semantics(
    manifest: &GatewayFormalBackendExecutionQuarantineOutputManifest,
    metadata: &GatewayFormalBackendExecutionQuarantineArtifactMetadata,
    request: &GatewayFormalBackendExecutionQuarantineOutputRequest,
    files: &BTreeMap<String, Vec<u8>>,
) -> Result<(), GatewayFormalBackendExecutionQuarantineOutputError> {
    let expected_digest_paths: BTreeSet<String> = GATEWAY_FORMAL_BACKEND_QUARANTINE_DECLARED_FILES
        .iter()
        .filter(|path| **path != "gateway-formal-backend-quarantine/manifest.json")
        .map(|path| (*path).to_owned())
        .collect();
    let actual_digest_paths: BTreeSet<String> =
        manifest.declared_file_digests.keys().cloned().collect();
    if manifest.schema_version != GATEWAY_FORMAL_BACKEND_QUARANTINE_OUTPUT_SCHEMA_VERSION
        || manifest.bundle_id != request.bundle_id
        || manifest.state_slice != GATEWAY_FORMAL_BACKEND_EXECUTION_QUARANTINE_OUTPUT_STATE_SLICE
        || manifest.created_at_unix != request.created_at_unix
        || manifest.quarantine_artifact_digest != metadata.digest()
        || manifest.authorization_output_manifest_digest
            != metadata.authorization_output_manifest_digest
        || manifest.authorization_request_digest != metadata.authorization_request_digest
        || manifest.preflight_output_manifest_digest != metadata.preflight_output_manifest_digest
        || manifest.transcript_output_manifest_digest != metadata.transcript_output_manifest_digest
        || manifest.command_descriptor_digest != metadata.command_descriptor_digest
        || manifest.environment_descriptor_digest != metadata.environment_descriptor_digest
        || manifest.quarantine_descriptor_digest != metadata.quarantine_descriptor_digest
        || manifest.operator_acknowledgement_digest != metadata.operator_acknowledgement_digest
        || manifest.backend_kind != metadata.backend_kind
        || manifest.tool_name != metadata.tool_name
        || manifest.tool_version != metadata.tool_version
        || manifest.toolchain_lock_digest != metadata.toolchain_lock_digest
        || manifest.executable_path_label != metadata.executable_path_label
        || manifest.argv_digest != metadata.argv_digest
        || manifest.process_status_digest
            != hash_bytes(declared_gateway_formal_backend_quarantine_bytes(
                files,
                "gateway-formal-backend-quarantine/process-status.json",
            )?)
        || manifest.stdout_summary_digest
            != hash_bytes(declared_gateway_formal_backend_quarantine_bytes(
                files,
                "gateway-formal-backend-quarantine/stdout-summary.json",
            )?)
        || manifest.stderr_summary_digest
            != hash_bytes(declared_gateway_formal_backend_quarantine_bytes(
                files,
                "gateway-formal-backend-quarantine/stderr-summary.json",
            )?)
        || manifest.redaction_report_digest
            != hash_bytes(declared_gateway_formal_backend_quarantine_bytes(
                files,
                "gateway-formal-backend-quarantine/redaction-report.json",
            )?)
        || manifest.output_inventory_digest
            != hash_bytes(declared_gateway_formal_backend_quarantine_bytes(
                files,
                "gateway-formal-backend-quarantine/output-inventory.json",
            )?)
        || manifest.proof_checker_nonpromotion_report_digest
            != hash_bytes(declared_gateway_formal_backend_quarantine_bytes(
                files,
                "gateway-formal-backend-quarantine/proof-checker-nonpromotion.json",
            )?)
        || manifest.nonclaims_digest
            != hash_bytes(declared_gateway_formal_backend_quarantine_bytes(
                files,
                "gateway-formal-backend-quarantine/nonclaims.md",
            )?)
        || manifest.declared_files
            != gateway_formal_backend_execution_quarantine_output_declared_files()
        || actual_digest_paths != expected_digest_paths
        || manifest.claim_boundary
            != gateway_formal_backend_execution_quarantine_output_claim_boundary()
        || manifest.command_spawned_by_this_crate
        || manifest.creates_accepted_evidence
        || manifest.creates_level2_evidence
        || manifest.populates_score_axes
        || manifest.grants_authority
        || manifest.nonclaims != metadata.nonclaims
    {
        return Err(GatewayFormalBackendExecutionQuarantineOutputError::ManifestSemanticMismatch);
    }
    for (logical_path, expected_digest) in &manifest.declared_file_digests {
        let bytes = declared_gateway_formal_backend_quarantine_bytes(files, logical_path)?;
        if *expected_digest != hash_bytes(bytes) {
            return Err(
                GatewayFormalBackendExecutionQuarantineOutputError::DigestMismatch(
                    logical_path.clone(),
                ),
            );
        }
    }
    Ok(())
}

