fn render_gateway_formal_backend_quarantine_nonclaims(
    nonclaims: &BTreeSet<NonClaimLabel>,
) -> String {
    let mut out = String::from("# Gateway Formal Backend Quarantine Nonclaims\n\n");
    for nonclaim in nonclaims {
        out.push_str("- ");
        out.push_str(&nonclaim.0);
        out.push('\n');
    }
    out
}

fn declared_gateway_formal_backend_quarantine_bytes<'a>(
    files: &'a BTreeMap<String, Vec<u8>>,
    logical_path: &str,
) -> Result<&'a [u8], GatewayFormalBackendExecutionQuarantineOutputError> {
    files.get(logical_path).map(Vec::as_slice).ok_or_else(|| {
        GatewayFormalBackendExecutionQuarantineOutputError::Io(format!(
            "declared file missing: {logical_path}"
        ))
    })
}

fn parse_gateway_formal_backend_quarantine_declared_json<T: for<'de> Deserialize<'de>>(
    files: &BTreeMap<String, Vec<u8>>,
    logical_path: &str,
) -> Result<T, GatewayFormalBackendExecutionQuarantineOutputError> {
    let bytes = declared_gateway_formal_backend_quarantine_bytes(files, logical_path)?;
    let text = std::str::from_utf8(bytes).map_err(|_| {
        GatewayFormalBackendExecutionQuarantineOutputError::MalformedDeclaredFile(
            logical_path.to_owned(),
        )
    })?;
    serde_json::from_str(text).map_err(|_| {
        GatewayFormalBackendExecutionQuarantineOutputError::MalformedDeclaredFile(
            logical_path.to_owned(),
        )
    })
}

fn reject_undeclared_gateway_formal_backend_quarantine_files(
    output_root: &Path,
) -> Result<(), GatewayFormalBackendExecutionQuarantineOutputError> {
    let mut declared: BTreeSet<String> = GATEWAY_FORMAL_BACKEND_QUARANTINE_DECLARED_FILES
        .iter()
        .chain(GATEWAY_FORMAL_BACKEND_QUARANTINE_DECLARED_SIDECARS.iter())
        .map(|value| (*value).to_owned())
        .collect();
    let bundle_dir = output_root.join("gateway-formal-backend-quarantine");
    for entry in fs::read_dir(&bundle_dir).map_err(gateway_formal_backend_quarantine_io_error)? {
        let entry = entry.map_err(gateway_formal_backend_quarantine_io_error)?;
        let logical_path = entry
            .path()
            .strip_prefix(output_root)
            .map_err(|error| {
                GatewayFormalBackendExecutionQuarantineOutputError::Io(error.to_string())
            })?
            .to_string_lossy()
            .replace('\\', "/");
        if !declared.remove(&logical_path) {
            return Err(
                GatewayFormalBackendExecutionQuarantineOutputError::UndeclaredFile(logical_path),
            );
        }
    }
    if let Some(missing) = declared.into_iter().next() {
        return Err(GatewayFormalBackendExecutionQuarantineOutputError::Io(
            format!("declared file missing: {missing}"),
        ));
    }
    Ok(())
}

fn validate_gateway_formal_backend_quarantine_output_root(
    output_root: &Path,
    protected_roots: &[PathBuf],
    overwrite: bool,
) -> Result<(), GatewayFormalBackendExecutionQuarantineOutputError> {
    match validate_output_root(output_root, protected_roots, overwrite) {
        Ok(()) => Ok(()),
        Err(AdmissionJournalMaterializationError::EmptyOutputRoot) => {
            Err(GatewayFormalBackendExecutionQuarantineOutputError::EmptyOutputRoot)
        }
        Err(AdmissionJournalMaterializationError::ProtectedOutputRoot) => {
            Err(GatewayFormalBackendExecutionQuarantineOutputError::ProtectedOutputRoot)
        }
        Err(AdmissionJournalMaterializationError::OutputRootExistsWithoutOverwrite) => Err(
            GatewayFormalBackendExecutionQuarantineOutputError::OutputRootExistsWithoutOverwrite,
        ),
        Err(AdmissionJournalMaterializationError::OutputRootIsFile) => {
            Err(GatewayFormalBackendExecutionQuarantineOutputError::OutputRootIsFile)
        }
        Err(AdmissionJournalMaterializationError::OutputRootIsSymlink) => {
            Err(GatewayFormalBackendExecutionQuarantineOutputError::OutputRootIsSymlink)
        }
        Err(AdmissionJournalMaterializationError::Io(error)) => Err(
            GatewayFormalBackendExecutionQuarantineOutputError::Io(error),
        ),
        Err(other) => Err(GatewayFormalBackendExecutionQuarantineOutputError::Io(
            format!("{other:?}"),
        )),
    }
}

fn gateway_formal_backend_quarantine_staging_root_for(
    output_root: &Path,
    bundle_id: &str,
) -> Result<PathBuf, GatewayFormalBackendExecutionQuarantineOutputError> {
    let parent = output_root
        .parent()
        .ok_or(GatewayFormalBackendExecutionQuarantineOutputError::EmptyOutputRoot)?;
    let name = output_root
        .file_name()
        .map(|value| value.to_string_lossy().into_owned())
        .ok_or(GatewayFormalBackendExecutionQuarantineOutputError::EmptyOutputRoot)?;
    Ok(parent.join(format!(".{name}.{bundle_id}.staging")))
}

fn remove_gateway_formal_backend_quarantine_dir_all_checked(
    path: &Path,
) -> Result<(), GatewayFormalBackendExecutionQuarantineOutputError> {
    if !path.exists() {
        return Ok(());
    }
    if fs::symlink_metadata(path)
        .map_err(gateway_formal_backend_quarantine_io_error)?
        .file_type()
        .is_symlink()
    {
        return Err(GatewayFormalBackendExecutionQuarantineOutputError::OutputRootIsSymlink);
    }
    fs::remove_dir_all(path).map_err(gateway_formal_backend_quarantine_io_error)
}

fn gateway_formal_backend_quarantine_io_error(
    error: io::Error,
) -> GatewayFormalBackendExecutionQuarantineOutputError {
    GatewayFormalBackendExecutionQuarantineOutputError::Io(error.to_string())
}

fn gateway_formal_backend_quarantine_serde_error(
    error: serde_json::Error,
) -> GatewayFormalBackendExecutionQuarantineOutputError {
    GatewayFormalBackendExecutionQuarantineOutputError::Serialization(error.to_string())
}

fn gateway_formal_backend_execution_quarantine_output_inventory_digest(
    inventory: &[GatewayFormalBackendExecutionQuarantineFileReference],
) -> Hash {
    let inventory = inventory.to_vec();
    hash_tagged(
        "hsai-agent-admission:gateway-formal-backend-execution-quarantine-output-inventory:v1",
        &inventory,
    )
}

fn validate_gateway_formal_backend_execution_quarantine_authorization(
    authorization: &GatewayFormalBackendExecutionAuthorizationRequest,
    issues: &mut Vec<GatewayFormalBackendExecutionQuarantineArtifactIssue>,
) {
    let mut authorization_issues = Vec::new();
    if authorization.schema_version != GATEWAY_FORMAL_BACKEND_EXECUTION_AUTHORIZATION_SCHEMA_VERSION
    {
        authorization_issues
            .push(GatewayFormalBackendExecutionAuthorizationIssue::InvalidSchemaVersion);
    }
    if authorization.authorization_id.trim().is_empty()
        || !is_safe_relative_path(&authorization.authorization_id)
        || authorization.authorization_id.contains(['/', '\\'])
    {
        authorization_issues
            .push(GatewayFormalBackendExecutionAuthorizationIssue::InvalidAuthorizationId);
    }
    if authorization.state_slice != GATEWAY_FORMAL_BACKEND_EXECUTION_AUTHORIZATION_STATE_SLICE {
        authorization_issues
            .push(GatewayFormalBackendExecutionAuthorizationIssue::StateSliceMismatch);
    }
    if authorization.claim_boundary
        != gateway_formal_backend_execution_authorization_claim_boundary()
    {
        authorization_issues
            .push(GatewayFormalBackendExecutionAuthorizationIssue::ClaimBoundaryMismatch);
    }
    if authorization.command_spawned {
        authorization_issues.push(GatewayFormalBackendExecutionAuthorizationIssue::CommandSpawned);
    }
    if authorization.backend_executed {
        authorization_issues.push(GatewayFormalBackendExecutionAuthorizationIssue::BackendExecuted);
    }
    if authorization.proof_artifact_created {
        authorization_issues
            .push(GatewayFormalBackendExecutionAuthorizationIssue::ProofArtifactCreated);
    }
    if authorization.checker_transcript_created {
        authorization_issues
            .push(GatewayFormalBackendExecutionAuthorizationIssue::CheckerTranscriptCreated);
    }
    if authorization.checker_succeeded {
        authorization_issues
            .push(GatewayFormalBackendExecutionAuthorizationIssue::CheckerSucceeded);
    }
    if authorization.creates_accepted_evidence {
        authorization_issues
            .push(GatewayFormalBackendExecutionAuthorizationIssue::AcceptedEvidenceCreated);
    }
    if authorization.creates_level2_evidence {
        authorization_issues
            .push(GatewayFormalBackendExecutionAuthorizationIssue::Level2EvidenceCreated);
    }
    if authorization.populates_score_axes {
        authorization_issues
            .push(GatewayFormalBackendExecutionAuthorizationIssue::ScoreAxesPopulated);
    }
    if authorization.grants_authority {
        authorization_issues
            .push(GatewayFormalBackendExecutionAuthorizationIssue::AuthorityGranted);
    }
    if authorization.semantic_correctness_claimed {
        authorization_issues
            .push(GatewayFormalBackendExecutionAuthorizationIssue::SemanticCorrectnessClaimed);
    }
    if authorization.production_readiness_claimed {
        authorization_issues
            .push(GatewayFormalBackendExecutionAuthorizationIssue::ProductionReadinessClaimed);
    }
    if authorization.sota_claimed {
        authorization_issues.push(GatewayFormalBackendExecutionAuthorizationIssue::SotaClaimed);
    }
    if authorization.full_security_claimed {
        authorization_issues
            .push(GatewayFormalBackendExecutionAuthorizationIssue::FullSecurityClaimed);
    }
    if !authorization.network_disabled {
        authorization_issues
            .push(GatewayFormalBackendExecutionAuthorizationIssue::NetworkPolicyEnabled);
    }
    if !authorization.no_secrets {
        authorization_issues
            .push(GatewayFormalBackendExecutionAuthorizationIssue::SecretPolicyEnabled);
    }
    for forbidden in gateway_formal_evidence_forbidden_claim_fragments() {
        if authorization
            .claim_text
            .iter()
            .any(|text| text.to_ascii_lowercase().contains(forbidden))
        {
            authorization_issues.push(
                GatewayFormalBackendExecutionAuthorizationIssue::ForbiddenClaimText(
                    (*forbidden).to_owned(),
                ),
            );
        }
    }
    for required in gateway_formal_backend_execution_authorization_required_nonclaims() {
        if !authorization.nonclaims.contains(&required) {
            authorization_issues.push(
                GatewayFormalBackendExecutionAuthorizationIssue::MissingRequiredNonclaim(
                    required.0,
                ),
            );
        }
    }
    if !authorization_issues.is_empty() {
        issues.push(
            GatewayFormalBackendExecutionQuarantineArtifactIssue::InvalidAuthorization(
                authorization_issues,
            ),
        );
    }
}

fn validate_gateway_formal_backend_execution_quarantine_authorization_output_manifest(
    authorization: &GatewayFormalBackendExecutionAuthorizationRequest,
    manifest: &GatewayFormalBackendExecutionAuthorizationOutputManifest,
    issues: &mut Vec<GatewayFormalBackendExecutionQuarantineArtifactIssue>,
) {
    if manifest.authorization_request_digest != authorization.digest()
        || manifest.command_descriptor_digest != authorization.command_descriptor_digest
        || manifest.environment_descriptor_digest != authorization.environment_descriptor_digest
        || manifest.quarantine_descriptor_digest == Hash([0; 32])
        || manifest.operator_acknowledgement_digest
            != authorization.operator_acknowledgement.digest()
        || manifest.backend_kind != authorization.backend_kind
        || manifest.tool_name != authorization.tool_name
        || manifest.tool_version != authorization.tool_version
        || manifest.toolchain_lock_digest != authorization.toolchain_lock_digest
        || manifest.executable_path_label != authorization.executable_path_label
        || manifest.argv_digest
            != hash_tagged(
                "hsai-agent-admission:gateway-formal-backend-authorization-argv:v1",
                &authorization.argv,
            )
    {
        issues.push(
            GatewayFormalBackendExecutionQuarantineArtifactIssue::AuthorizationOutputManifestDigestMismatch,
        );
    }
    if manifest.claim_boundary
        != gateway_formal_backend_execution_authorization_output_claim_boundary()
        || manifest.command_spawned
        || manifest.backend_executed
        || manifest.proof_artifact_created
        || manifest.checker_transcript_created
        || manifest.checker_succeeded
        || manifest.creates_accepted_evidence
        || manifest.creates_level2_evidence
        || manifest.populates_score_axes
        || manifest.grants_authority
    {
        issues.push(
            GatewayFormalBackendExecutionQuarantineArtifactIssue::AuthorizationOutputManifestEscalated,
        );
    }
}

