    fn gateway_formal_backend_hermetic_fixture_runner_fixture_with_argv(
        prefix: &str,
        argv_template: Vec<String>,
        max_stdout_bytes: Option<u64>,
        max_stderr_bytes: Option<u64>,
    ) -> (
        GatewayFormalBackendHermeticExecutionDescriptor,
        GatewayFormalBackendHermeticDescriptorReportOutputManifest,
        GatewayFormalBackendHermeticExecutionResultQuarantineOutputManifest,
        GatewayFormalBackendHermeticProcessSpawnInterface,
        PathBuf,
        PathBuf,
    ) {
        let (mut descriptor, _) = gateway_formal_backend_hermetic_descriptor_report_fixture(prefix);
        descriptor.argv_template = argv_template;
        if let Some(max_stdout_bytes) = max_stdout_bytes {
            descriptor.max_stdout_bytes = max_stdout_bytes;
        }
        if let Some(max_stderr_bytes) = max_stderr_bytes {
            descriptor.max_stderr_bytes = max_stderr_bytes;
        }
        let report = build_gateway_formal_backend_hermetic_execution_descriptor_report(&descriptor);
        let descriptor_output_root =
            temp_output_root(&format!("{prefix}-fixture-runner-descriptor-output"));
        let descriptor_report_manifest =
            materialize_gateway_formal_backend_hermetic_descriptor_report_output_bundle(
                &descriptor_output_root,
                &descriptor,
                &report,
                &gateway_formal_backend_hermetic_descriptor_report_output_request(
                    &format!("{prefix}-descriptor-report"),
                    &descriptor_output_root,
                ),
            )
            .expect("fixture runner descriptor report output materializes");
        let source_result_output_root =
            temp_output_root(&format!("{prefix}-fixture-runner-source-result-output"));
        let source_result_manifest =
            materialize_gateway_formal_backend_hermetic_execution_result_quarantine_output_bundle(
                &source_result_output_root,
                &descriptor,
                &descriptor_report_manifest,
                &gateway_formal_backend_hermetic_execution_result_quarantine_output_request(
                    &format!("{prefix}-source-result"),
                    &source_result_output_root,
                ),
            )
            .expect("fixture runner source result output materializes");
        let interface = build_gateway_formal_backend_hermetic_process_spawn_interface(
            format!("{prefix}-interface"),
            &descriptor,
            &descriptor_report_manifest,
            &source_result_manifest,
        );
        (
            descriptor,
            descriptor_report_manifest,
            source_result_manifest,
            interface,
            descriptor_output_root,
            source_result_output_root,
        )
    }

