    fn validation_summary_bundle_path(output_root: &Path, logical_path: &str) -> PathBuf {
        output_root.join(logical_path)
    }

    fn write_validation_summary_bytes_with_sidecar(
        output_root: &Path,
        logical_path: &str,
        bytes: &[u8],
    ) {
        let path = validation_summary_bundle_path(output_root, logical_path);
        fs::write(&path, bytes).expect("validation summary drift write succeeds");
        fs::write(
            sidecar_path(&path),
            hash_hex(hash_bytes(bytes)).into_bytes(),
        )
        .expect("validation summary sidecar update succeeds");
    }

    fn write_validation_summary_json_with_sidecar<T: Serialize>(
        output_root: &Path,
        logical_path: &str,
        value: &T,
    ) {
        let bytes = serde_json::to_vec_pretty(value).expect("validation summary drift serializes");
        write_validation_summary_bytes_with_sidecar(output_root, logical_path, &bytes);
    }

    fn cleanup_validation_summary_output_fixture(output_root: &Path) {
        if output_root.exists() {
            fs::remove_dir_all(output_root).expect("validation summary output cleanup succeeds");
        }
    }

