    #[test]
    fn accepted_candidate_exports_envelope_and_appends_journal_entry() {
        let candidate = accepted_candidate();
        let admission_policy = policy();
        let decision = evaluate_admission(&candidate, &admission_policy);

        assert_eq!(decision.verdict, AdmissionVerdict::Accepted);
        assert!(decision.reasons.is_empty());
        assert_eq!(
            accepted_claim_envelope(&candidate, &admission_policy, &decision),
            candidate.proposed_envelope.as_ref()
        );

        let mut journal = AgentAdmissionJournal::default();
        let entry = journal
            .append_decision(&candidate, &admission_policy, decision)
            .expect("accepted decision should append");

        assert_eq!(entry.sequence_number, 0);
        assert_eq!(entry.previous_entry_digest, None);
        assert_eq!(
            entry.source_artifact_digests,
            candidate.source_artifact_digests
        );
        assert!(journal.validate().is_empty());
    }

    #[test]
    fn gateway_attestation_binding_uses_proposal_digest_as_case_hash() {
        let proposal = gateway_proposal("gateway-attestation-action");
        let binding = build_gateway_attestation_challenge_binding(
            &proposal,
            AdmissionPolicyId("gateway-attestation-policy-v1".to_owned()),
            "anchor-gateway-runtime-1",
            gateway_attestation_pubkey_hex(),
            42,
            100,
            200,
        )
        .expect("gateway attestation binding should build");

        let pubkey = decode_lower_hex("agent_pubkey_spki_hex", &gateway_attestation_pubkey_hex())
            .expect("test pubkey hex decodes");
        let expected = bytes_hex(&report_data_binding(
            &pubkey,
            42,
            proposal.digest().0.as_slice(),
        ));

        assert_eq!(
            binding.schema_version,
            GATEWAY_ATTESTATION_BINDING_SCHEMA_VERSION
        );
        assert_eq!(binding.gateway_case_hash_hex, hash_hex(proposal.digest()));
        assert_eq!(binding.expected_report_data_hex, expected);
        assert_eq!(
            validate_gateway_attestation_challenge_binding(
                &proposal,
                &AdmissionPolicyId("gateway-attestation-policy-v1".to_owned()),
                &binding,
                150,
            ),
            Vec::new()
        );
        assert!(!binding.challenge_id.is_empty());
        assert!(!binding.authority_granted);
    }

    #[test]
    fn gateway_attestation_binding_is_deterministic_and_nonce_sensitive() {
        let proposal = gateway_proposal("gateway-attestation-action");
        let first = build_gateway_attestation_challenge_binding(
            &proposal,
            AdmissionPolicyId("gateway-attestation-policy-v1".to_owned()),
            "anchor-gateway-runtime-1",
            gateway_attestation_pubkey_hex(),
            42,
            100,
            200,
        )
        .expect("first binding builds");
        let second = build_gateway_attestation_challenge_binding(
            &proposal,
            AdmissionPolicyId("gateway-attestation-policy-v1".to_owned()),
            "anchor-gateway-runtime-1",
            gateway_attestation_pubkey_hex(),
            42,
            100,
            200,
        )
        .expect("second binding builds");
        let changed_nonce = build_gateway_attestation_challenge_binding(
            &proposal,
            AdmissionPolicyId("gateway-attestation-policy-v1".to_owned()),
            "anchor-gateway-runtime-1",
            gateway_attestation_pubkey_hex(),
            43,
            100,
            200,
        )
        .expect("changed nonce binding builds");

        assert_eq!(first, second);
        assert_ne!(
            first.expected_report_data_hex,
            changed_nonce.expected_report_data_hex
        );
        assert_ne!(first.challenge_id, changed_nonce.challenge_id);
    }

    #[test]
    fn gateway_attestation_binding_rejects_gateway_case_tamper() {
        let original = gateway_proposal("gateway-attestation-action");
        let mut tampered = original.clone();
        tampered.target = "wrong-counterparty".to_owned();
        let binding = build_gateway_attestation_challenge_binding(
            &original,
            AdmissionPolicyId("gateway-attestation-policy-v1".to_owned()),
            "anchor-gateway-runtime-1",
            gateway_attestation_pubkey_hex(),
            42,
            100,
            200,
        )
        .expect("binding builds");

        let errors = validate_gateway_attestation_challenge_binding(
            &tampered,
            &AdmissionPolicyId("gateway-attestation-policy-v1".to_owned()),
            &binding,
            150,
        );

        assert!(errors.iter().any(|error| matches!(
            error,
            GatewayAttestationBindingError::GatewayCaseHashMismatch { .. }
        )));
        assert!(errors.iter().any(|error| matches!(
            error,
            GatewayAttestationBindingError::ReportDataMismatch { .. }
        )));
    }

    #[test]
    fn gateway_attestation_binding_rejects_expiry_and_challenge_id_tamper() {
        let proposal = gateway_proposal("gateway-attestation-action");
        let mut binding = gateway_attestation_binding();
        binding.challenge_id.replace_range(0..2, "ff");

        let errors = validate_gateway_attestation_challenge_binding(
            &proposal,
            &AdmissionPolicyId("gateway-attestation-policy-v1".to_owned()),
            &binding,
            201,
        );

        assert!(errors.iter().any(|error| matches!(
            error,
            GatewayAttestationBindingError::ExpiredChallenge { .. }
        )));
        assert!(errors.iter().any(|error| matches!(
            error,
            GatewayAttestationBindingError::ChallengeIdMismatch { .. }
        )));
    }

    #[test]
    fn gateway_attestation_binding_rejects_authority_and_missing_nonclaim() {
        let proposal = gateway_proposal("gateway-attestation-action");
        let mut binding = gateway_attestation_binding();
        binding.authority_granted = true;
        binding
            .nonclaims
            .remove(&NonClaimLabel("not proof".to_owned()));

        let errors = validate_gateway_attestation_challenge_binding(
            &proposal,
            &AdmissionPolicyId("gateway-attestation-policy-v1".to_owned()),
            &binding,
            150,
        );

        assert!(errors
            .iter()
            .any(|error| error == &GatewayAttestationBindingError::AuthorityGranted));
        assert!(errors.iter().any(|error| {
            error
                == &GatewayAttestationBindingError::MissingRequiredNonclaim("not proof".to_owned())
        }));
        assert!(errors.iter().any(|error| matches!(
            error,
            GatewayAttestationBindingError::ChallengeIdMismatch { .. }
        )));
    }

    #[test]
    fn gateway_formal_evidence_report_is_local_metadata_only() {
        let request = gateway_formal_evidence_request();
        let report = build_gateway_formal_evidence_report(&request);

        assert_eq!(
            report.schema_version,
            GATEWAY_FORMAL_EVIDENCE_REPORT_SCHEMA_VERSION
        );
        assert!(report.validation.valid);
        assert_eq!(
            report.check_status,
            GatewayFormalEvidenceCheckStatus::LocalMetadataCheckOnly
        );
        assert_eq!(report.request_digest, request.digest());
        assert_eq!(
            report.attestation_binding_digest,
            request.expected_binding_digest
        );
        assert!(!report.creates_formal_proof);
        assert!(!report.mutates_accepted_evidence_ledger);
        assert!(!report.creates_level2_evidence);
        assert!(!report.populates_score_axes);
        assert!(!report.grants_authority);
        assert!(report
            .nonclaims
            .contains(&NonClaimLabel("no formal backend was run".to_owned())));
        assert_ne!(report.digest(), Hash([0; 32]));
    }

    #[test]
    fn gateway_formal_evidence_local_check_tracks_determinism_and_sensitivity() {
        let request = gateway_formal_evidence_request();
        let report = build_gateway_formal_evidence_report(&request);

        assert!(report.local_check.deterministic_same_input);
        assert!(report.local_check.nonce_changes_binding);
        assert!(report.local_check.proposal_changes_binding);
        assert_eq!(
            report.local_check.base_binding_digest,
            report.local_check.repeated_binding_digest
        );
        assert_ne!(
            report.local_check.base_binding_digest,
            report.local_check.nonce_variant_binding_digest
        );
        assert_ne!(
            report.local_check.base_binding_digest,
            report.local_check.proposal_variant_binding_digest
        );
    }

    #[test]
    fn gateway_formal_evidence_rejects_claim_escalation_and_backend_execution() {
        let mut request = gateway_formal_evidence_request();
        request.formal_backend_execution_requested = true;
        request.proof_artifact_digest = Some(Hash([92; 32]));
        request.accepted_evidence_mutation_requested = true;
        request.level2_evidence_requested = true;
        request.score_axis_population_requested = true;
        request.production_readiness_claimed = true;
        request.semantic_correctness_claimed = true;
        request.sota_claimed = true;
        request.full_security_claimed = true;
        request.authority_grant_requested = true;
        request
            .claim_text
            .push("HSAI is SOTA and production ready".to_owned());

        let report = build_gateway_formal_evidence_report(&request);

        assert!(!report.validation.valid);
        assert_eq!(
            report.check_status,
            GatewayFormalEvidenceCheckStatus::Rejected
        );
        for expected in [
            GatewayFormalEvidenceIssue::FormalBackendExecutionRequested,
            GatewayFormalEvidenceIssue::ProofArtifactDigestSubmitted,
            GatewayFormalEvidenceIssue::AcceptedEvidenceMutationRequested,
            GatewayFormalEvidenceIssue::Level2EvidenceRequested,
            GatewayFormalEvidenceIssue::ScoreAxisPopulationRequested,
            GatewayFormalEvidenceIssue::ProductionReadinessClaimed,
            GatewayFormalEvidenceIssue::SemanticCorrectnessClaimed,
            GatewayFormalEvidenceIssue::SotaClaimed,
            GatewayFormalEvidenceIssue::FullSecurityClaimed,
            GatewayFormalEvidenceIssue::AuthorityGrantRequested,
            GatewayFormalEvidenceIssue::ForbiddenClaimText("sota".to_owned()),
        ] {
            assert!(
                report.validation.issues.contains(&expected),
                "missing {expected:?}"
            );
        }
    }

    #[test]
    fn gateway_formal_evidence_rejects_source_and_binding_drift() {
        let mut request = gateway_formal_evidence_request();
        request.source_files.push("../unsafe".to_owned());
        request
            .source_files
            .push("crates/hsai-agent-admission/src/lib.rs".to_owned());
        request.source_digest = Hash([0; 32]);
        request.source_commit = " dirty ".to_owned();
        request.expected_binding_digest = Hash([99; 32]);
        request
            .nonclaims
            .remove(&NonClaimLabel("not formal proof evidence".to_owned()));

        let validation = validate_gateway_formal_evidence_request(&request);

        assert!(!validation.valid);
        assert!(validation
            .issues
            .contains(&GatewayFormalEvidenceIssue::UnsafeSourceFile(
                "../unsafe".to_owned()
            )));
        assert!(validation
            .issues
            .contains(&GatewayFormalEvidenceIssue::DuplicateSourceFile(
                "crates/hsai-agent-admission/src/lib.rs".to_owned()
            )));
        assert!(validation
            .issues
            .contains(&GatewayFormalEvidenceIssue::MissingSourceDigest));
        assert!(validation
            .issues
            .contains(&GatewayFormalEvidenceIssue::MissingSourceCommit));
        assert!(validation
            .issues
            .contains(&GatewayFormalEvidenceIssue::BindingDigestMismatch));
        assert!(validation
            .issues
            .contains(&GatewayFormalEvidenceIssue::MissingRequiredNonclaim(
                "not formal proof evidence".to_owned()
            )));
    }

    #[test]
    fn gateway_formal_correspondence_certificate_accepts_metadata_only_mapping() {
        let certificate = gateway_formal_correspondence_certificate();
        let validation = validate_gateway_formal_correspondence_certificate(&certificate);

        assert!(validation.valid, "{:?}", validation.issues);
        assert_ne!(certificate.digest(), Hash([0; 32]));
        assert_eq!(
            certificate.proof_status,
            GatewayFormalCorrespondenceProofStatus::CorrespondenceOnly
        );
        assert_eq!(
            certificate.tool_status.execution_status,
            GatewayFormalToolExecutionStatus::NotRun
        );
        assert!(certificate.proof_artifact_digest.is_none());
        assert!(certificate
            .nonclaims
            .contains(&NonClaimLabel("correspondence metadata only".to_owned())));
    }

    #[test]
    fn gateway_formal_correspondence_certificate_requires_phase267_anchors() {
        let mut certificate = gateway_formal_correspondence_certificate();
        certificate
            .source_files
            .retain(|source| source.path != "crates/hsai-attestation/src/lib.rs");
        certificate
            .source_anchors
            .retain(|anchor| anchor.anchor != "report_data_binding");
        certificate
            .proof_obligations
            .remove(&GatewayFormalProofObligationId::P267ValidationAgreement);
        certificate
            .trusted_assumptions
            .remove("report_data_binding is imported and must be proved or assumed explicitly");
        certificate
            .modeled_replacements
            .remove("report_data_binding modeled as length-prefixed SHA-256 transcript");

        let validation = validate_gateway_formal_correspondence_certificate(&certificate);

        assert!(!validation.valid);
        assert!(validation
            .issues
            .contains(&GatewayFormalCorrespondenceIssue::MissingSourceFile(
                "crates/hsai-attestation/src/lib.rs".to_owned()
            )));
        assert!(validation.issues.contains(
            &GatewayFormalCorrespondenceIssue::MissingSourceAnchor(
                "report_data_binding".to_owned()
            )
        ));
        assert!(validation.issues.contains(
            &GatewayFormalCorrespondenceIssue::MissingProofObligation(
                GatewayFormalProofObligationId::P267ValidationAgreement
            )
        ));
        assert!(validation.issues.contains(
            &GatewayFormalCorrespondenceIssue::MissingTrustedAssumption(
                "report_data_binding is imported and must be proved or assumed explicitly"
                    .to_owned()
            )
        ));
        assert!(validation.issues.contains(
            &GatewayFormalCorrespondenceIssue::MissingModeledReplacement(
                "report_data_binding modeled as length-prefixed SHA-256 transcript".to_owned()
            )
        ));
    }

    #[test]
    fn gateway_formal_correspondence_certificate_rejects_proof_and_claim_escalation() {
        let mut certificate = gateway_formal_correspondence_certificate();
        certificate.tool_status.execution_status = GatewayFormalToolExecutionStatus::Executed;
        certificate.proof_status = GatewayFormalCorrespondenceProofStatus::MachineChecked;
        certificate.proof_artifact_digest = Some(Hash([105; 32]));
        certificate.formal_backend_execution_requested = true;
        certificate.accepted_evidence_mutation_requested = true;
        certificate.level2_evidence_requested = true;
        certificate.score_axis_population_requested = true;
        certificate.production_readiness_claimed = true;
        certificate.semantic_correctness_claimed = true;
        certificate.sota_claimed = true;
        certificate.full_security_claimed = true;
        certificate.authority_grant_requested = true;
        certificate
            .claim_text
            .push("HSAI proves semantic correctness and is fully secure".to_owned());

        let validation = validate_gateway_formal_correspondence_certificate(&certificate);

        assert!(!validation.valid);
        for expected in [
            GatewayFormalCorrespondenceIssue::FormalBackendExecuted,
            GatewayFormalCorrespondenceIssue::ProofStatusEscalated,
            GatewayFormalCorrespondenceIssue::ProofArtifactDigestSubmitted,
            GatewayFormalCorrespondenceIssue::FormalBackendExecutionRequested,
            GatewayFormalCorrespondenceIssue::AcceptedEvidenceMutationRequested,
            GatewayFormalCorrespondenceIssue::Level2EvidenceRequested,
            GatewayFormalCorrespondenceIssue::ScoreAxisPopulationRequested,
            GatewayFormalCorrespondenceIssue::ProductionReadinessClaimed,
            GatewayFormalCorrespondenceIssue::SemanticCorrectnessClaimed,
            GatewayFormalCorrespondenceIssue::SotaClaimed,
            GatewayFormalCorrespondenceIssue::FullSecurityClaimed,
            GatewayFormalCorrespondenceIssue::AuthorityGrantRequested,
            GatewayFormalCorrespondenceIssue::ForbiddenClaimText("semantic correctness".to_owned()),
            GatewayFormalCorrespondenceIssue::ForbiddenClaimText("fully secure".to_owned()),
        ] {
            assert!(
                validation.issues.contains(&expected),
                "missing {expected:?}"
            );
        }
    }

    #[test]
    fn gateway_formal_correspondence_certificate_rejects_source_drift() {
        let mut certificate = gateway_formal_correspondence_certificate();
        certificate
            .source_files
            .push(GatewayFormalSourceFileDigest {
                path: "../unsafe".to_owned(),
                sha256: Hash([106; 32]),
            });
        certificate
            .source_files
            .push(GatewayFormalSourceFileDigest {
                path: "crates/hsai-agent-admission/src/lib.rs".to_owned(),
                sha256: Hash([107; 32]),
            });
        certificate.source_files[0].sha256 = Hash([0; 32]);
        certificate.source_anchors.push(GatewayFormalSourceAnchor {
            anchor: "GatewayActionProposal".to_owned(),
            file_path: "crates/hsai-attestation/src/lib.rs".to_owned(),
            role: "wrong-file".to_owned(),
        });
        certificate.input_output_schema_digest = Hash([0; 32]);
        certificate
            .nonclaims
            .remove(&NonClaimLabel("not source proof".to_owned()));

        let validation = validate_gateway_formal_correspondence_certificate(&certificate);

        assert!(!validation.valid);
        assert!(validation
            .issues
            .contains(&GatewayFormalCorrespondenceIssue::UnsafeSourceFile(
                "../unsafe".to_owned()
            )));
        assert!(validation.issues.contains(
            &GatewayFormalCorrespondenceIssue::DuplicateSourceFile(
                "crates/hsai-agent-admission/src/lib.rs".to_owned()
            )
        ));
        assert!(validation.issues.contains(
            &GatewayFormalCorrespondenceIssue::MissingSourceDigest(
                "crates/hsai-agent-admission/src/lib.rs".to_owned()
            )
        ));
        assert!(validation.issues.contains(
            &GatewayFormalCorrespondenceIssue::DuplicateSourceAnchor(
                "GatewayActionProposal".to_owned()
            )
        ));
        assert!(validation
            .issues
            .contains(&GatewayFormalCorrespondenceIssue::MissingInputOutputSchemaDigest));
        assert!(validation.issues.contains(
            &GatewayFormalCorrespondenceIssue::MissingRequiredNonclaim(
                "not source proof".to_owned()
            )
        ));
    }

    #[test]
    fn gateway_formal_correspondence_bundle_materializes_declared_files_and_readback() {
        let certificate = gateway_formal_correspondence_certificate();
        let output_root = temp_output_root("gateway-formal-correspondence-bundle");
        let request = gateway_formal_correspondence_output_request(
            "gateway-formal-correspondence",
            &output_root,
        );

        let manifest =
            materialize_gateway_formal_correspondence_bundle(&output_root, &certificate, &request)
                .expect("formal correspondence bundle materializes");

        assert_eq!(manifest.bundle_id, "gateway-formal-correspondence");
        assert_eq!(
            manifest.declared_files,
            gateway_formal_correspondence_declared_files()
        );
        assert_eq!(manifest.certificate_digest, certificate.digest());
        assert!(!manifest.creates_formal_proof);
        assert!(!manifest.mutates_accepted_evidence_ledger);
        assert!(!manifest.creates_level2_evidence);
        assert!(!manifest.populates_score_axes);
        assert!(!manifest.grants_authority);
        assert_eq!(
            read_gateway_formal_correspondence_bundle(&output_root).expect("readback validates"),
            manifest
        );
        for logical_path in GATEWAY_FORMAL_CORRESPONDENCE_DECLARED_FILES {
            let path = output_root.join(logical_path);
            assert!(path.is_file(), "{logical_path} should exist");
            assert!(
                sidecar_path(&path).is_file(),
                "{logical_path} sidecar should exist"
            );
        }
        let _ = fs::remove_dir_all(output_root);
    }

