    #[test]
    fn gateway_formal_correspondence_bundle_rejects_undeclared_and_redaction_drift() {
        let certificate = gateway_formal_correspondence_certificate();
        let output_root = temp_output_root("gateway-formal-correspondence-redaction");
        let request = gateway_formal_correspondence_output_request(
            "gateway-formal-correspondence-redaction",
            &output_root,
        );
        materialize_gateway_formal_correspondence_bundle(&output_root, &certificate, &request)
            .expect("formal correspondence bundle materializes");

        fs::write(
            output_root.join("gateway-formal-correspondence/raw-prover.log"),
            b"forbidden",
        )
        .expect("undeclared file writes");
        let error = read_gateway_formal_correspondence_bundle(&output_root)
            .expect_err("undeclared file rejects");
        assert_eq!(
            error,
            GatewayFormalCorrespondenceOutputError::UndeclaredFile(
                "gateway-formal-correspondence/raw-prover.log".to_owned()
            )
        );
        fs::remove_file(output_root.join("gateway-formal-correspondence/raw-prover.log"))
            .expect("undeclared file removal succeeds");

        let mut redaction = gateway_formal_correspondence_redaction_report();
        redaction.retains_raw_prover_logs = true;
        rewrite_bundle_file(
            &output_root,
            "gateway-formal-correspondence/redaction-report.json",
            &serde_json::to_vec_pretty(&redaction).expect("redaction serializes"),
        );
        let error = read_gateway_formal_correspondence_bundle(&output_root)
            .expect_err("redaction drift rejects");
        assert_eq!(
            error,
            GatewayFormalCorrespondenceOutputError::RedactionReportMismatch
        );
        let _ = fs::remove_dir_all(output_root);
    }

