    #[test]
    fn gateway_formal_backend_run_bundle_materializes_declared_files_and_readback() {
        let certificate = gateway_formal_correspondence_certificate();
        let correspondence_root =
            temp_output_root("gateway-formal-backend-run-bundle-correspondence");
        let output_manifest = materialize_gateway_formal_correspondence_bundle(
            &correspondence_root,
            &certificate,
            &gateway_formal_correspondence_output_request(
                "backend-run-bundle-correspondence",
                &correspondence_root,
            ),
        )
        .expect("formal correspondence bundle materializes");
        let adapter_request =
            gateway_formal_backend_adapter_request(&certificate, &output_manifest);
        let adapter_report = build_gateway_formal_backend_adapter_report(
            &adapter_request,
            &certificate,
            &output_manifest,
        );
        let run_metadata = build_gateway_formal_backend_run_artifact_metadata(
            "phase-278-backend-run",
            &adapter_request,
            &adapter_report,
        );
        let bundle_root = temp_output_root("gateway-formal-backend-run-bundle-valid");
        let request =
            gateway_formal_backend_run_output_request("backend-run-bundle-valid", &bundle_root);

        let manifest = materialize_gateway_formal_backend_run_bundle(
            &bundle_root,
            &adapter_request,
            &adapter_report,
            &run_metadata,
            &request,
        )
        .expect("backend run bundle materializes");
        let readback =
            read_gateway_formal_backend_run_bundle(&bundle_root).expect("readback succeeds");

        assert_eq!(readback, manifest);
        assert_eq!(manifest.bundle_id, "backend-run-bundle-valid");
        assert_eq!(
            manifest.declared_files,
            gateway_formal_backend_run_declared_files()
        );
        assert_eq!(manifest.adapter_request_digest, adapter_request.digest());
        assert_eq!(manifest.adapter_report_digest, adapter_report.digest());
        assert_eq!(manifest.run_summary_digest, run_metadata.digest());
        assert_eq!(
            manifest.correspondence_certificate_digest,
            adapter_report.correspondence_certificate_digest
        );
        assert_eq!(
            manifest.correspondence_output_manifest_digest,
            adapter_report.output_manifest_digest
        );
        assert_eq!(
            manifest.claim_boundary,
            gateway_formal_backend_run_artifact_claim_boundary()
        );
        assert!(!manifest.creates_accepted_evidence);
        assert!(!manifest.creates_level2_evidence);
        assert!(!manifest.populates_score_axes);
        assert!(!manifest.grants_authority);
        assert!(bundle_root
            .join("gateway-formal-backend-run/manifest.json.sha256")
            .is_file());
        assert!(!bundle_root
            .join("gateway-formal-backend-run/candidate-proof-artifact.ref.json")
            .exists());
        assert_ne!(manifest.digest(), Hash([0; 32]));
        fs::remove_dir_all(&bundle_root).expect("backend run bundle cleanup succeeds");
        fs::remove_dir_all(&correspondence_root)
            .expect("backend run correspondence cleanup succeeds");
    }

