    #[test]
    fn gateway_formal_backend_run_bundle_readback_rejects_sidecar_manifest_and_json_drift() {
        let stale_root = temp_output_root("gateway-formal-backend-run-stale-sidecar");
        let stale_correspondence_root =
            gateway_formal_backend_run_bundle_fixture("backend-run-stale-sidecar", &stale_root);
        fs::write(
            stale_root.join("gateway-formal-backend-run/run-summary.json.sha256"),
            b"stale",
        )
        .expect("stale sidecar write succeeds");
        assert_eq!(
            read_gateway_formal_backend_run_bundle(&stale_root),
            Err(GatewayFormalBackendRunOutputError::DigestMismatch(
                "gateway-formal-backend-run/run-summary.json".to_owned()
            ))
        );

        let manifest_root = temp_output_root("gateway-formal-backend-run-manifest-drift");
        let manifest_correspondence_root =
            gateway_formal_backend_run_bundle_fixture("backend-run-manifest-drift", &manifest_root);
        let manifest_path = manifest_root.join("gateway-formal-backend-run/manifest.json");
        let mut manifest: GatewayFormalBackendRunOutputManifest =
            serde_json::from_slice(&fs::read(&manifest_path).expect("manifest read succeeds"))
                .expect("manifest parses");
        manifest.creates_level2_evidence = true;
        let manifest_bytes = serde_json::to_vec_pretty(&manifest).expect("manifest serializes");
        fs::write(&manifest_path, &manifest_bytes).expect("manifest drift write succeeds");
        fs::write(
            sidecar_path(&manifest_path),
            hash_hex(hash_bytes(&manifest_bytes)).into_bytes(),
        )
        .expect("manifest sidecar update succeeds");
        assert_eq!(
            read_gateway_formal_backend_run_bundle(&manifest_root),
            Err(GatewayFormalBackendRunOutputError::ManifestSemanticMismatch)
        );

        let malformed_root = temp_output_root("gateway-formal-backend-run-malformed-summary");
        let malformed_correspondence_root = gateway_formal_backend_run_bundle_fixture(
            "backend-run-malformed-summary",
            &malformed_root,
        );
        let run_summary_path = malformed_root.join("gateway-formal-backend-run/run-summary.json");
        fs::write(&run_summary_path, b"{not-json").expect("malformed run summary write succeeds");
        fs::write(
            sidecar_path(&run_summary_path),
            hash_hex(hash_bytes(b"{not-json")).into_bytes(),
        )
        .expect("malformed run summary sidecar update succeeds");
        assert_eq!(
            read_gateway_formal_backend_run_bundle(&malformed_root),
            Err(GatewayFormalBackendRunOutputError::MalformedDeclaredFile(
                "gateway-formal-backend-run/run-summary.json".to_owned()
            ))
        );

        fs::remove_dir_all(&stale_root).expect("stale sidecar root cleanup succeeds");
        fs::remove_dir_all(&manifest_root).expect("manifest drift root cleanup succeeds");
        fs::remove_dir_all(&malformed_root).expect("malformed root cleanup succeeds");
        fs::remove_dir_all(&stale_correspondence_root)
            .expect("stale sidecar correspondence cleanup succeeds");
        fs::remove_dir_all(&manifest_correspondence_root)
            .expect("manifest correspondence cleanup succeeds");
        fs::remove_dir_all(&malformed_correspondence_root)
            .expect("malformed correspondence cleanup succeeds");
    }

