    #[test]
    fn gateway_formal_backend_preflight_accepts_inert_metadata_only() {
        let (
            adapter_request,
            adapter_report,
            run_metadata,
            run_manifest,
            correspondence_root,
            run_root,
        ) = gateway_formal_backend_preflight_fixture("accepts-inert");
        let request = gateway_formal_backend_preflight_request(
            &adapter_request,
            &adapter_report,
            &run_metadata,
            &run_manifest,
        );

        let report = build_gateway_formal_backend_execution_preflight_report(
            &request,
            &adapter_request,
            &adapter_report,
            &run_metadata,
            &run_manifest,
        );

        assert_eq!(
            report.schema_version,
            GATEWAY_FORMAL_BACKEND_PREFLIGHT_REPORT_SCHEMA_VERSION
        );
        assert!(report.validation.valid);
        assert_eq!(
            report.readiness_status,
            GatewayFormalBackendPreflightReadinessStatus::ReadyCandidateOnly
        );
        assert_eq!(
            report.claim_boundary,
            gateway_formal_backend_preflight_claim_boundary()
        );
        assert_eq!(report.input_bundle_digest, run_manifest.digest());
        assert_eq!(
            report.command_descriptor_digest,
            request.command_descriptor.digest()
        );
        assert!(!report.backend_executed);
        assert!(!report.proof_artifact_created);
        assert!(!report.checker_transcript_created);
        assert!(!report.creates_accepted_evidence);
        assert!(!report.creates_level2_evidence);
        assert!(!report.populates_score_axes);
        assert!(!report.grants_authority);
        assert_ne!(report.digest(), Hash([0; 32]));

        fs::remove_dir_all(&run_root).expect("preflight run bundle cleanup succeeds");
        fs::remove_dir_all(&correspondence_root)
            .expect("preflight correspondence cleanup succeeds");
    }

    #[test]
    fn gateway_formal_backend_preflight_rejects_command_environment_and_root_drift() {
        let (
            adapter_request,
            adapter_report,
            run_metadata,
            run_manifest,
            correspondence_root,
            run_root,
        ) = gateway_formal_backend_preflight_fixture("rejects-command");
        let mut request = gateway_formal_backend_preflight_request(
            &adapter_request,
            &adapter_report,
            &run_metadata,
            &run_manifest,
        );

        request.command_descriptor.mode =
            GatewayFormalBackendPreflightMode::CobaltContainmentPreflight;
        request
            .command_descriptor
            .argv
            .push("echo ok; rm -rf /".to_owned());
        request
            .command_descriptor
            .allowed_environment_variables
            .insert("OPENAI_API_KEY".to_owned());
        request.environment_descriptor.inherit_full_environment = true;
        request.environment_descriptor.no_network = false;
        request
            .environment_descriptor
            .variables
            .insert("OPENAI_API_KEY".to_owned(), "sk-test-secret".to_owned());
        request.artifact_root_descriptor.path_label =
            "accepted-evidence/gateway-formal-backend-run".to_owned();
        request
            .artifact_root_descriptor
            .accepted_evidence_ledger_path = true;
        request.artifact_root_descriptor.symlink = true;

        let validation = validate_gateway_formal_backend_execution_preflight_request(
            &request,
            &adapter_request,
            &adapter_report,
            &run_metadata,
            &run_manifest,
        );

        assert!(!validation.valid);
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendPreflightIssue::PreflightModeMismatch));
        assert!(validation.issues.iter().any(|issue| matches!(
            issue,
            GatewayFormalBackendPreflightIssue::ShellMetacharacterFragment(arg)
                if arg.contains("rm -rf")
        )));
        assert!(validation.issues.iter().any(|issue| matches!(
            issue,
            GatewayFormalBackendPreflightIssue::CredentialLookingEnvironmentValue(name)
                if name == "OPENAI_API_KEY"
        )));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendPreflightIssue::InheritedFullEnvironment));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendPreflightIssue::NetworkPolicyEnabled));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendPreflightIssue::InvalidArtifactRoot));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendPreflightIssue::ArtifactRootAcceptedEvidenceLedgerPath));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendPreflightIssue::ArtifactRootIsSymlink));

        fs::remove_dir_all(&run_root).expect("preflight drift run cleanup succeeds");
        fs::remove_dir_all(&correspondence_root)
            .expect("preflight drift correspondence cleanup succeeds");
    }

    #[test]
    fn gateway_formal_backend_preflight_rejects_ack_redaction_and_claim_escalation() {
        let (
            adapter_request,
            adapter_report,
            run_metadata,
            run_manifest,
            correspondence_root,
            run_root,
        ) = gateway_formal_backend_preflight_fixture("rejects-escalation");
        let mut request = gateway_formal_backend_preflight_request(
            &adapter_request,
            &adapter_report,
            &run_metadata,
            &run_manifest,
        );

        request.operator_acknowledgement.operator_id.clear();
        request.operator_acknowledgement.grants_authority = true;
        request
            .operator_acknowledgement
            .input_bundle_digest_acknowledged = Hash([9; 32]);
        request.redaction_policy.retains_raw_solver_traces = true;
        request.backend_executed = true;
        request.proof_artifact_created = true;
        request.checker_transcript_created = true;
        request.creates_accepted_evidence = true;
        request.creates_level2_evidence = true;
        request.populates_score_axes = true;
        request.grants_authority = true;
        request.semantic_correctness_claimed = true;
        request.production_readiness_claimed = true;
        request.sota_claimed = true;
        request.full_security_claimed = true;
        request.claim_text = vec![
            "HSAI is SOTA and proves semantic correctness.".to_owned(),
            "HSAI is fully secure and production ready.".to_owned(),
        ];
        request
            .nonclaims
            .remove(&NonClaimLabel("no command executed".to_owned()));

        let validation = validate_gateway_formal_backend_execution_preflight_request(
            &request,
            &adapter_request,
            &adapter_report,
            &run_metadata,
            &run_manifest,
        );

        assert!(!validation.valid);
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendPreflightIssue::MissingOperatorAcknowledgement));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendPreflightIssue::OperatorAcknowledgementMismatch));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendPreflightIssue::OperatorAcknowledgementGrantsAuthority));
        assert!(validation.issues.contains(
            &GatewayFormalBackendPreflightIssue::RedactionPolicyRetainsForbiddenMaterial
        ));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendPreflightIssue::BackendExecuted));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendPreflightIssue::ProofArtifactCreated));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendPreflightIssue::CheckerTranscriptCreated));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendPreflightIssue::AcceptedEvidenceCreated));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendPreflightIssue::Level2EvidenceCreated));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendPreflightIssue::ScoreAxesPopulated));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendPreflightIssue::AuthorityGranted));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendPreflightIssue::SemanticCorrectnessClaimed));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendPreflightIssue::ProductionReadinessClaimed));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendPreflightIssue::SotaClaimed));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendPreflightIssue::FullSecurityClaimed));
        assert!(validation.issues.iter().any(|issue| matches!(
            issue,
            GatewayFormalBackendPreflightIssue::ForbiddenClaimText(fragment)
                if fragment == "sota"
        )));
        assert!(validation.issues.contains(
            &GatewayFormalBackendPreflightIssue::MissingRequiredNonclaim(
                "no command executed".to_owned()
            )
        ));

        fs::remove_dir_all(&run_root).expect("preflight escalation run cleanup succeeds");
        fs::remove_dir_all(&correspondence_root)
            .expect("preflight escalation correspondence cleanup succeeds");
    }

