    #[test]
    fn gateway_formal_backend_preflight_bundle_rejects_invalid_preflight_before_write() {
        let (
            adapter_request,
            adapter_report,
            run_metadata,
            run_manifest,
            correspondence_root,
            run_root,
        ) = gateway_formal_backend_preflight_fixture("bundle-invalid");
        let mut preflight_request = gateway_formal_backend_preflight_request(
            &adapter_request,
            &adapter_report,
            &run_metadata,
            &run_manifest,
        );
        let preflight_report = build_gateway_formal_backend_execution_preflight_report(
            &preflight_request,
            &adapter_request,
            &adapter_report,
            &run_metadata,
            &run_manifest,
        );
        preflight_request.backend_executed = true;
        let bundle_root = temp_output_root("gateway-formal-backend-preflight-invalid-request");
        let output_request = gateway_formal_backend_preflight_output_request(
            "preflight-invalid-request",
            &bundle_root,
        );

        let error = materialize_gateway_formal_backend_preflight_bundle(
            &bundle_root,
            &preflight_request,
            &preflight_report,
            &adapter_request,
            &adapter_report,
            &run_metadata,
            &run_manifest,
            &output_request,
        )
        .expect_err("invalid preflight request is rejected");

        assert!(matches!(
            error,
            GatewayFormalBackendPreflightOutputError::InvalidPreflight(issues)
                if issues.contains(&GatewayFormalBackendPreflightIssue::BackendExecuted)
        ));
        assert!(!bundle_root.exists());

        let valid_preflight_request = gateway_formal_backend_preflight_request(
            &adapter_request,
            &adapter_report,
            &run_metadata,
            &run_manifest,
        );
        let mut escalated_report = build_gateway_formal_backend_execution_preflight_report(
            &valid_preflight_request,
            &adapter_request,
            &adapter_report,
            &run_metadata,
            &run_manifest,
        );
        escalated_report.creates_level2_evidence = true;
        let escalated_root = temp_output_root("gateway-formal-backend-preflight-invalid-report");
        let escalated_output_request = gateway_formal_backend_preflight_output_request(
            "preflight-invalid-report",
            &escalated_root,
        );
        assert_eq!(
            materialize_gateway_formal_backend_preflight_bundle(
                &escalated_root,
                &valid_preflight_request,
                &escalated_report,
                &adapter_request,
                &adapter_report,
                &run_metadata,
                &run_manifest,
                &escalated_output_request,
            ),
            Err(GatewayFormalBackendPreflightOutputError::PreflightReportMismatch)
        );
        assert!(!escalated_root.exists());

        fs::remove_dir_all(&run_root).expect("preflight invalid run cleanup succeeds");
        fs::remove_dir_all(&correspondence_root)
            .expect("preflight invalid correspondence cleanup succeeds");
    }

