    #[test]
    fn gateway_formal_backend_execution_authorization_output_bundle_materializes_and_reads_back() {
        let (
            authorization,
            preflight_request,
            preflight_report,
            preflight_manifest,
            transcript_metadata,
            transcript_manifest,
            transcript_root,
            preflight_root,
            run_root,
            correspondence_root,
        ) = gateway_formal_backend_execution_authorization_fixture("authorization-output-valid");
        let output_root = temp_output_root("gateway-formal-backend-authorization-output-valid");
        let output_request = gateway_formal_backend_execution_authorization_output_request(
            "authorization-output-valid",
            &output_root,
        );

        let manifest = materialize_gateway_formal_backend_execution_authorization_output_bundle(
            &output_root,
            &authorization,
            &preflight_request,
            &preflight_report,
            &preflight_manifest,
            &transcript_metadata,
            &transcript_manifest,
            &output_request,
        )
        .expect("authorization output bundle materializes");
        let readback =
            read_gateway_formal_backend_execution_authorization_output_bundle(&output_root)
                .expect("authorization output readback succeeds");

        assert_eq!(readback, manifest);
        assert_eq!(manifest.bundle_id, "authorization-output-valid");
        assert_eq!(
            manifest.declared_files,
            gateway_formal_backend_execution_authorization_output_declared_files()
        );
        assert_eq!(
            manifest.authorization_request_digest,
            authorization.digest()
        );
        assert_eq!(
            manifest.preflight_bundle_manifest_digest,
            preflight_manifest.digest()
        );
        assert_eq!(
            manifest.transcript_output_manifest_digest,
            transcript_manifest.digest()
        );
        assert_eq!(
            manifest.command_descriptor_digest,
            preflight_request.command_descriptor.digest()
        );
        assert_eq!(
            manifest.claim_boundary,
            gateway_formal_backend_execution_authorization_output_claim_boundary()
        );
        assert!(!manifest.command_spawned);
        assert!(!manifest.backend_executed);
        assert!(!manifest.proof_artifact_created);
        assert!(!manifest.checker_transcript_created);
        assert!(!manifest.checker_succeeded);
        assert!(!manifest.creates_accepted_evidence);
        assert!(!manifest.creates_level2_evidence);
        assert!(!manifest.populates_score_axes);
        assert!(!manifest.grants_authority);
        assert!(output_root
            .join("gateway-formal-backend-authorization/manifest.json.sha256")
            .is_file());
        assert!(!output_root
            .join("gateway-formal-backend-authorization/proof-artifact.json")
            .exists());

        fs::remove_dir_all(&output_root).expect("authorization output cleanup succeeds");
        fs::remove_dir_all(&transcript_root)
            .expect("authorization output transcript cleanup succeeds");
        fs::remove_dir_all(&preflight_root)
            .expect("authorization output preflight cleanup succeeds");
        fs::remove_dir_all(&run_root).expect("authorization output run cleanup succeeds");
        fs::remove_dir_all(&correspondence_root)
            .expect("authorization output correspondence cleanup succeeds");
    }

    #[test]
    fn gateway_formal_backend_execution_authorization_output_bundle_rejects_invalid_before_write() {
        let (
            mut authorization,
            preflight_request,
            preflight_report,
            preflight_manifest,
            transcript_metadata,
            transcript_manifest,
            transcript_root,
            preflight_root,
            run_root,
            correspondence_root,
        ) = gateway_formal_backend_execution_authorization_fixture("authorization-output-invalid");
        let output_root = temp_output_root("gateway-formal-backend-authorization-output-invalid");
        authorization.backend_executed = true;

        let error = materialize_gateway_formal_backend_execution_authorization_output_bundle(
            &output_root,
            &authorization,
            &preflight_request,
            &preflight_report,
            &preflight_manifest,
            &transcript_metadata,
            &transcript_manifest,
            &gateway_formal_backend_execution_authorization_output_request(
                "authorization-output-invalid",
                &output_root,
            ),
        );

        assert!(matches!(
            error,
            Err(GatewayFormalBackendExecutionAuthorizationOutputError::InvalidAuthorization(
                issues
            )) if issues.contains(&GatewayFormalBackendExecutionAuthorizationIssue::BackendExecuted)
        ));
        assert!(!output_root.exists());

        let valid_authorization = build_gateway_formal_backend_execution_authorization_request(
            "authorization-output-mismatch",
            &preflight_request,
            &preflight_report,
            &preflight_manifest,
            &transcript_metadata,
            &transcript_manifest,
            gateway_formal_backend_execution_authorization_quarantine_descriptor(
                &preflight_request,
            ),
            gateway_formal_backend_execution_authorization_operator_acknowledgement(
                "authorization-output-mismatch",
                "local-operator",
                &preflight_request,
                &preflight_manifest,
                &transcript_manifest,
                &gateway_formal_backend_execution_authorization_quarantine_descriptor(
                    &preflight_request,
                ),
            ),
        );
        let mut drift_request = gateway_formal_backend_execution_authorization_output_request(
            "authorization/output/mismatch",
            &output_root,
        );
        drift_request.bundle_id = "../bad".to_owned();
        assert_eq!(
            materialize_gateway_formal_backend_execution_authorization_output_bundle(
                &output_root,
                &valid_authorization,
                &preflight_request,
                &preflight_report,
                &preflight_manifest,
                &transcript_metadata,
                &transcript_manifest,
                &drift_request,
            ),
            Err(GatewayFormalBackendExecutionAuthorizationOutputError::EmptyBundleId)
        );

        fs::remove_dir_all(&transcript_root)
            .expect("invalid authorization output transcript cleanup succeeds");
        fs::remove_dir_all(&preflight_root)
            .expect("invalid authorization output preflight cleanup succeeds");
        fs::remove_dir_all(&run_root).expect("invalid authorization output run cleanup succeeds");
        fs::remove_dir_all(&correspondence_root)
            .expect("invalid authorization output correspondence cleanup succeeds");
    }

    #[test]
    fn gateway_formal_backend_execution_authorization_output_bundle_rejects_readback_drift() {
        let (
            _authorization,
            _manifest,
            command_root,
            command_transcript_root,
            command_preflight_root,
            command_run_root,
            command_correspondence_root,
        ) = gateway_formal_backend_execution_authorization_output_bundle_fixture(
            "authorization-output-command-drift",
        );
        let command_path =
            command_root.join("gateway-formal-backend-authorization/command-binding.json");
        let mut command_binding: GatewayFormalBackendExecutionAuthorizationCommandBinding =
            serde_json::from_slice(
                &fs::read(&command_path).expect("command binding read succeeds"),
            )
            .expect("command binding parses");
        command_binding.argv.push("--unexpected".to_owned());
        let command_bytes =
            serde_json::to_vec_pretty(&command_binding).expect("command binding serializes");
        fs::write(&command_path, &command_bytes).expect("command binding drift write succeeds");
        fs::write(
            sidecar_path(&command_path),
            hash_hex(hash_bytes(&command_bytes)).into_bytes(),
        )
        .expect("command binding sidecar update succeeds");
        assert_eq!(
            read_gateway_formal_backend_execution_authorization_output_bundle(&command_root),
            Err(GatewayFormalBackendExecutionAuthorizationOutputError::CommandBindingMismatch)
        );

        let (
            _authorization,
            _manifest,
            nonclaim_root,
            nonclaim_transcript_root,
            nonclaim_preflight_root,
            nonclaim_run_root,
            nonclaim_correspondence_root,
        ) = gateway_formal_backend_execution_authorization_output_bundle_fixture(
            "authorization-output-nonclaim-drift",
        );
        let nonclaim_path = nonclaim_root.join("gateway-formal-backend-authorization/nonclaims.md");
        fs::write(
            &nonclaim_path,
            b"# Gateway Formal Backend Authorization Nonclaims\n",
        )
        .expect("authorization nonclaim drift write succeeds");
        fs::write(
            sidecar_path(&nonclaim_path),
            hash_hex(hash_bytes(
                b"# Gateway Formal Backend Authorization Nonclaims\n",
            ))
            .into_bytes(),
        )
        .expect("authorization nonclaim sidecar update succeeds");
        assert_eq!(
            read_gateway_formal_backend_execution_authorization_output_bundle(&nonclaim_root),
            Err(GatewayFormalBackendExecutionAuthorizationOutputError::NonclaimMismatch)
        );

        let (
            _authorization,
            _manifest,
            manifest_root,
            manifest_transcript_root,
            manifest_preflight_root,
            manifest_run_root,
            manifest_correspondence_root,
        ) = gateway_formal_backend_execution_authorization_output_bundle_fixture(
            "authorization-output-manifest-drift",
        );
        let manifest_path =
            manifest_root.join("gateway-formal-backend-authorization/manifest.json");
        let mut manifest: GatewayFormalBackendExecutionAuthorizationOutputManifest =
            serde_json::from_slice(&fs::read(&manifest_path).expect("manifest read succeeds"))
                .expect("manifest parses");
        manifest.creates_level2_evidence = true;
        let manifest_bytes = serde_json::to_vec_pretty(&manifest).expect("manifest serializes");
        fs::write(&manifest_path, &manifest_bytes).expect("manifest drift write succeeds");
        fs::write(
            sidecar_path(&manifest_path),
            hash_hex(hash_bytes(&manifest_bytes)).into_bytes(),
        )
        .expect("manifest sidecar update succeeds");
        assert_eq!(
            read_gateway_formal_backend_execution_authorization_output_bundle(&manifest_root),
            Err(GatewayFormalBackendExecutionAuthorizationOutputError::ManifestSemanticMismatch)
        );

        fs::remove_dir_all(&command_root).expect("authorization command root cleanup succeeds");
        fs::remove_dir_all(&command_transcript_root)
            .expect("authorization command transcript cleanup succeeds");
        fs::remove_dir_all(&command_preflight_root)
            .expect("authorization command preflight cleanup succeeds");
        fs::remove_dir_all(&command_run_root).expect("authorization command run cleanup succeeds");
        fs::remove_dir_all(&command_correspondence_root)
            .expect("authorization command correspondence cleanup succeeds");
        fs::remove_dir_all(&nonclaim_root).expect("authorization nonclaim root cleanup succeeds");
        fs::remove_dir_all(&nonclaim_transcript_root)
            .expect("authorization nonclaim transcript cleanup succeeds");
        fs::remove_dir_all(&nonclaim_preflight_root)
            .expect("authorization nonclaim preflight cleanup succeeds");
        fs::remove_dir_all(&nonclaim_run_root)
            .expect("authorization nonclaim run cleanup succeeds");
        fs::remove_dir_all(&nonclaim_correspondence_root)
            .expect("authorization nonclaim correspondence cleanup succeeds");
        fs::remove_dir_all(&manifest_root).expect("authorization manifest root cleanup succeeds");
        fs::remove_dir_all(&manifest_transcript_root)
            .expect("authorization manifest transcript cleanup succeeds");
        fs::remove_dir_all(&manifest_preflight_root)
            .expect("authorization manifest preflight cleanup succeeds");
        fs::remove_dir_all(&manifest_run_root)
            .expect("authorization manifest run cleanup succeeds");
        fs::remove_dir_all(&manifest_correspondence_root)
            .expect("authorization manifest correspondence cleanup succeeds");
    }

