    #[test]
    fn gateway_formal_backend_execution_quarantine_artifact_rejects_claim_escalation() {
        let (
            mut metadata,
            mut authorization,
            mut authorization_manifest,
            authorization_root,
            transcript_root,
            preflight_root,
            run_root,
            correspondence_root,
        ) = gateway_formal_backend_execution_quarantine_metadata_fixture("quarantine-claim");
        authorization.backend_executed = true;
        authorization.creates_level2_evidence = true;
        authorization_manifest.creates_level2_evidence = true;
        metadata.command_spawned_by_this_crate = true;
        metadata.creates_accepted_evidence = true;
        metadata.creates_level2_evidence = true;
        metadata.populates_score_axes = true;
        metadata.grants_authority = true;
        metadata.semantic_correctness_claimed = true;
        metadata.production_readiness_claimed = true;
        metadata.sota_claimed = true;
        metadata.full_security_claimed = true;
        metadata.claim_boundary = "wrong boundary".to_owned();
        metadata.claim_text = vec![
            "HSAI is SOTA and proves semantic correctness.".to_owned(),
            "HSAI is fully secure and production ready.".to_owned(),
        ];
        metadata.nonclaims.remove(&NonClaimLabel(
            "quarantine artifact is local candidate metadata".to_owned(),
        ));

        let validation = validate_gateway_formal_backend_execution_quarantine_artifact_metadata(
            &metadata,
            &authorization,
            &authorization_manifest,
        );

        assert!(!validation.valid);
        assert!(validation.issues.iter().any(|issue| matches!(
            issue,
            GatewayFormalBackendExecutionQuarantineArtifactIssue::InvalidAuthorization(nested)
                if nested.contains(&GatewayFormalBackendExecutionAuthorizationIssue::BackendExecuted)
                    && nested.contains(&GatewayFormalBackendExecutionAuthorizationIssue::Level2EvidenceCreated)
        )));
        assert!(validation.issues.contains(
            &GatewayFormalBackendExecutionQuarantineArtifactIssue::AuthorizationOutputManifestEscalated
        ));
        assert!(validation.issues.contains(
            &GatewayFormalBackendExecutionQuarantineArtifactIssue::CommandSpawnedByThisCrate
        ));
        assert!(validation.issues.contains(
            &GatewayFormalBackendExecutionQuarantineArtifactIssue::AcceptedEvidenceCreated
        ));
        assert!(validation.issues.contains(
            &GatewayFormalBackendExecutionQuarantineArtifactIssue::Level2EvidenceCreated
        ));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendExecutionQuarantineArtifactIssue::ScoreAxesPopulated));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendExecutionQuarantineArtifactIssue::AuthorityGranted));
        assert!(validation.issues.contains(
            &GatewayFormalBackendExecutionQuarantineArtifactIssue::SemanticCorrectnessClaimed
        ));
        assert!(validation.issues.contains(
            &GatewayFormalBackendExecutionQuarantineArtifactIssue::ProductionReadinessClaimed
        ));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendExecutionQuarantineArtifactIssue::SotaClaimed));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendExecutionQuarantineArtifactIssue::FullSecurityClaimed));
        assert!(validation.issues.contains(
            &GatewayFormalBackendExecutionQuarantineArtifactIssue::ClaimBoundaryMismatch
        ));
        assert!(validation.issues.iter().any(|issue| matches!(
            issue,
            GatewayFormalBackendExecutionQuarantineArtifactIssue::ForbiddenClaimText(fragment)
                if fragment == "sota"
        )));
        assert!(validation.issues.contains(
            &GatewayFormalBackendExecutionQuarantineArtifactIssue::MissingRequiredNonclaim(
                "quarantine artifact is local candidate metadata".to_owned()
            )
        ));

        fs::remove_dir_all(&authorization_root)
            .expect("quarantine claim auth root cleanup succeeds");
        fs::remove_dir_all(&transcript_root).expect("quarantine claim transcript cleanup succeeds");
        fs::remove_dir_all(&preflight_root).expect("quarantine claim preflight cleanup succeeds");
        fs::remove_dir_all(&run_root).expect("quarantine claim run cleanup succeeds");
        fs::remove_dir_all(&correspondence_root)
            .expect("quarantine claim correspondence cleanup succeeds");
    }

