    #[test]
    fn gateway_formal_backend_hermetic_execution_descriptor_is_no_spawn_metadata_only() {
        let toolchain_lock_digest = hash_tagged("phase-304-toolchain-lock", &"z3-locked");
        let input_manifest_digest = hash_tagged("phase-304-input-manifest", &"phase-302-summary");
        let descriptor = build_gateway_formal_backend_hermetic_execution_descriptor(
            "hermetic-execution-descriptor-valid",
            GatewayFormalBackendHermeticInvariantProperty::AttestationChallengeBindingDeterminism,
            toolchain_lock_digest,
            input_manifest_digest,
            "ignored/formal-backend/local-smt-tiny-gateway-invariant",
        );
        let validation = validate_gateway_formal_backend_hermetic_execution_descriptor(&descriptor);
        let report = build_gateway_formal_backend_hermetic_execution_descriptor_report(&descriptor);

        assert!(validation.valid);
        assert!(validation.issues.is_empty());
        assert_eq!(report.validation, validation);
        assert_eq!(report.descriptor_digest, descriptor.digest());
        assert_eq!(report.input_manifest_digest, input_manifest_digest);
        assert_eq!(report.toolchain_lock_digest, toolchain_lock_digest);
        assert_eq!(
            report.lane,
            GatewayFormalBackendHermeticExecutionLane::LocalSmtTinyGatewayInvariant
        );
        assert_eq!(report.backend_kind, GatewayFormalBackendKind::Smt);
        assert!(report.no_spawn);
        assert!(!report.backend_executed);
        assert!(!report.proof_artifact_created);
        assert!(!report.checker_transcript_created);
        assert!(!report.creates_accepted_evidence);
        assert!(!report.creates_level2_evidence);
        assert!(!report.populates_score_axes);
        assert!(!report.grants_authority);
        assert_eq!(
            report.claim_boundary,
            gateway_formal_backend_hermetic_execution_descriptor_claim_boundary()
        );
    }

    #[test]
    fn gateway_formal_backend_hermetic_execution_descriptor_rejects_execution_and_claim_escalation()
    {
        let mut descriptor = build_gateway_formal_backend_hermetic_execution_descriptor(
            "hermetic-execution-descriptor-escalated",
            GatewayFormalBackendHermeticInvariantProperty::AcceptedEvidenceRequestBoundaryRejection,
            hash_tagged("phase-304-toolchain-lock", &"z3-locked"),
            hash_tagged("phase-304-input-manifest", &"phase-302-summary"),
            "ignored/formal-backend/local-smt-escalated",
        );
        descriptor.no_spawn = false;
        descriptor.backend_executed = true;
        descriptor.proof_artifact_created = true;
        descriptor.checker_transcript_created = true;
        descriptor.creates_accepted_evidence = true;
        descriptor.creates_level2_evidence = true;
        descriptor.populates_score_axes = true;
        descriptor.grants_authority = true;
        descriptor.semantic_correctness_claimed = true;
        descriptor.production_readiness_claimed = true;
        descriptor.sota_claimed = true;
        descriptor.breakthrough_claimed = true;
        descriptor.full_security_claimed = true;
        descriptor.claim_text.push("HSAI is SOTA".to_owned());
        descriptor.nonclaims.remove(&NonClaimLabel(
            "hermetic execution descriptor only".to_owned(),
        ));

        let validation = validate_gateway_formal_backend_hermetic_execution_descriptor(&descriptor);
        assert!(!validation.valid);
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendHermeticExecutionDescriptorIssue::ProcessSpawnAllowed));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendHermeticExecutionDescriptorIssue::BackendExecuted));
        assert!(validation.issues.contains(
            &GatewayFormalBackendHermeticExecutionDescriptorIssue::AcceptedEvidenceCreated
        ));
        assert!(validation.issues.contains(
            &GatewayFormalBackendHermeticExecutionDescriptorIssue::Level2EvidenceCreated
        ));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendHermeticExecutionDescriptorIssue::ScoreAxesPopulated));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendHermeticExecutionDescriptorIssue::AuthorityGranted));
        assert!(validation.issues.contains(
            &GatewayFormalBackendHermeticExecutionDescriptorIssue::SemanticCorrectnessClaimed
        ));
        assert!(validation.issues.contains(
            &GatewayFormalBackendHermeticExecutionDescriptorIssue::ProductionReadinessClaimed
        ));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendHermeticExecutionDescriptorIssue::SotaClaimed));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendHermeticExecutionDescriptorIssue::BreakthroughClaimed));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendHermeticExecutionDescriptorIssue::FullSecurityClaimed));
        assert!(validation.issues.contains(
            &GatewayFormalBackendHermeticExecutionDescriptorIssue::ForbiddenClaimText(
                "sota".to_owned()
            )
        ));
        assert!(validation.issues.contains(
            &GatewayFormalBackendHermeticExecutionDescriptorIssue::MissingRequiredNonclaim(
                "hermetic execution descriptor only".to_owned()
            )
        ));
    }

    #[test]
    fn gateway_formal_backend_hermetic_execution_descriptor_rejects_shell_env_and_raw_retention() {
        let mut descriptor = build_gateway_formal_backend_hermetic_execution_descriptor(
            "hermetic-execution-descriptor-shell-env",
            GatewayFormalBackendHermeticInvariantProperty::GatewayProposalDigestBindingDeterminism,
            hash_tagged("phase-304-toolchain-lock", &"z3-locked"),
            hash_tagged("phase-304-input-manifest", &"phase-302-summary"),
            "ignored/formal-backend/local-smt-shell-env",
        );
        descriptor.executable_path_label = "tools/formal/runner;rm".to_owned();
        descriptor.argv_template.push("$(cat secret)".to_owned());
        descriptor.inherit_environment = true;
        descriptor
            .allowed_environment_variables
            .insert("HSAI_FORMAL_MODE".to_owned());
        descriptor
            .environment_variables
            .insert("AWS_SECRET_ACCESS_KEY".to_owned(), "abc123".to_owned());
        descriptor.no_stdin = false;
        descriptor.no_shell = false;
        descriptor.no_network = false;
        descriptor.output_root_ignored = false;
        descriptor.raw_stdout_retained = true;
        descriptor.raw_stderr_retained = true;
        descriptor.raw_solver_trace_retained = true;

        let validation = validate_gateway_formal_backend_hermetic_execution_descriptor(&descriptor);
        assert!(!validation.valid);
        assert!(validation.issues.contains(
            &GatewayFormalBackendHermeticExecutionDescriptorIssue::InvalidExecutablePathLabel
        ));
        assert!(validation.issues.contains(
            &GatewayFormalBackendHermeticExecutionDescriptorIssue::ShellMetacharacterFragment(
                "$(cat secret)".to_owned()
            )
        ));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendHermeticExecutionDescriptorIssue::InheritedEnvironment));
        assert!(validation.issues.contains(
            &GatewayFormalBackendHermeticExecutionDescriptorIssue::EnvironmentVariableNotAllowed(
                "AWS_SECRET_ACCESS_KEY".to_owned()
            )
        ));
        assert!(validation.issues.contains(
            &GatewayFormalBackendHermeticExecutionDescriptorIssue::CredentialLookingEnvironmentValue(
                "AWS_SECRET_ACCESS_KEY".to_owned()
            )
        ));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendHermeticExecutionDescriptorIssue::StdinEnabled));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendHermeticExecutionDescriptorIssue::ShellEnabled));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendHermeticExecutionDescriptorIssue::NetworkEnabled));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendHermeticExecutionDescriptorIssue::OutputRootNotIgnored));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendHermeticExecutionDescriptorIssue::RawStdoutRetained));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendHermeticExecutionDescriptorIssue::RawStderrRetained));
        assert!(validation.issues.contains(
            &GatewayFormalBackendHermeticExecutionDescriptorIssue::RawSolverTraceRetained
        ));
    }

    #[test]
    fn gateway_formal_backend_hermetic_execution_descriptor_digest_is_sensitive() {
        let toolchain_lock_digest = hash_tagged("phase-304-toolchain-lock", &"z3-locked");
        let input_manifest_digest = hash_tagged("phase-304-input-manifest", &"phase-302-summary");
        let descriptor = build_gateway_formal_backend_hermetic_execution_descriptor(
            "hermetic-execution-descriptor-digest",
            GatewayFormalBackendHermeticInvariantProperty::GatewayProposalDigestBindingDeterminism,
            toolchain_lock_digest,
            input_manifest_digest,
            "ignored/formal-backend/local-smt-digest",
        );
        let same = build_gateway_formal_backend_hermetic_execution_descriptor(
            "hermetic-execution-descriptor-digest",
            GatewayFormalBackendHermeticInvariantProperty::GatewayProposalDigestBindingDeterminism,
            toolchain_lock_digest,
            input_manifest_digest,
            "ignored/formal-backend/local-smt-digest",
        );
        let changed = build_gateway_formal_backend_hermetic_execution_descriptor(
            "hermetic-execution-descriptor-digest",
            GatewayFormalBackendHermeticInvariantProperty::AttestationChallengeBindingDeterminism,
            toolchain_lock_digest,
            input_manifest_digest,
            "ignored/formal-backend/local-smt-digest",
        );

        assert_eq!(descriptor.digest(), same.digest());
        assert_ne!(descriptor.digest(), changed.digest());
        assert_eq!(
            build_gateway_formal_backend_hermetic_execution_descriptor_report(&descriptor)
                .descriptor_digest,
            descriptor.digest()
        );
    }

