    #[test]
    fn gateway_formal_backend_hermetic_fixture_runner_spawns_fixed_process_and_quarantines_output()
    {
        let (
            descriptor,
            descriptor_report_manifest,
            source_result_manifest,
            interface,
            descriptor_output_root,
            source_result_output_root,
        ) = gateway_formal_backend_hermetic_fixture_runner_fixture("hermetic-fixture-runner-valid");
        let output_root = temp_output_root("gateway-formal-backend-hermetic-fixture-runner-valid");
        let request = gateway_formal_backend_hermetic_fixture_runner_request(
            "hermetic-fixture-runner-valid",
            &output_root,
        );

        let output = materialize_gateway_formal_backend_hermetic_fixture_runner_output_bundle(
            &output_root,
            &interface,
            &descriptor,
            &descriptor_report_manifest,
            &source_result_manifest,
            &request,
        )
        .expect("fixture runner output materializes");
        let readback =
            read_gateway_formal_backend_hermetic_fixture_runner_output_bundle(&output_root)
                .expect("fixture runner readback succeeds");

        assert_eq!(readback, output.manifest);
        assert_eq!(
            output.manifest.state_slice,
            GATEWAY_FORMAL_BACKEND_HERMETIC_FIXTURE_RUNNER_STATE_SLICE
        );
        assert_eq!(
            output.manifest.claim_boundary,
            gateway_formal_backend_hermetic_fixture_runner_claim_boundary()
        );
        assert!(output.manifest.process_spawned);
        assert!(output.manifest.backend_executed);
        assert!(!output.manifest.proof_artifact_created);
        assert!(!output.manifest.checker_transcript_created);
        assert!(!output.manifest.solver_certificate_created);
        assert!(!output.manifest.creates_accepted_evidence);
        assert!(!output.manifest.creates_level2_evidence);
        assert!(!output.manifest.populates_score_axes);
        assert!(!output.manifest.semantic_correctness_claimed);
        assert!(!output.manifest.production_readiness_claimed);
        assert!(!output.manifest.sota_claimed);
        assert!(!output.manifest.breakthrough_claimed);
        assert!(!output.manifest.full_security_claimed);
        assert!(!output.manifest.grants_authority);
        assert_eq!(
            output.manifest.solver_status,
            GatewayFormalBackendHermeticExecutionSolverStatus::FixtureProcessExited
        );
        assert_eq!(
            output.manifest.invariant_verdict,
            GatewayFormalBackendHermeticExecutionInvariantVerdict::NotEvaluated
        );
        assert_eq!(output.manifest.process_exit_code_label, "exit_0");
        assert_eq!(
            output.report.output_manifest_digest,
            output.manifest.digest()
        );
        assert!(output
            .report
            .nonclaims
            .contains(&NonClaimLabel("fixture process only".to_owned())));

        let status_path = output_root.join(
            "gateway-formal-backend-hermetic-execution-result-quarantine/execution-status.json",
        );
        let status: GatewayFormalBackendHermeticExecutionResultExecutionStatus =
            serde_json::from_slice(&fs::read(status_path).expect("fixture status reads"))
                .expect("fixture status parses");
        assert!(status.process_spawned);
        assert!(status.backend_executed);
        assert_eq!(
            status.solver_status,
            GatewayFormalBackendHermeticExecutionSolverStatus::FixtureProcessExited
        );
        assert_eq!(
            read_gateway_formal_backend_hermetic_execution_result_quarantine_output_bundle(
                &output_root
            ),
            Err(
                GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::ExecutionStatusMismatch
            )
        );

        cleanup_validation_summary_output_fixture(&output_root);
        cleanup_validation_summary_output_fixture(&descriptor_output_root);
        cleanup_validation_summary_output_fixture(&source_result_output_root);
    }

