    #[test]
    fn gateway_formal_backend_hermetic_fixture_runner_classifies_nonzero_exit_and_timeout() {
        let (
            nonzero_descriptor,
            nonzero_descriptor_report_manifest,
            nonzero_source_result_manifest,
            nonzero_interface,
            nonzero_descriptor_output_root,
            nonzero_source_result_output_root,
        ) = gateway_formal_backend_hermetic_fixture_runner_fixture_with_argv(
            "hermetic-fixture-runner-nonzero",
            vec![
                "--ignored".to_owned(),
                "--exact".to_owned(),
                "tests::phase314_fixture_child_nonzero".to_owned(),
            ],
            None,
            None,
        );
        let nonzero_output_root =
            temp_output_root("gateway-formal-backend-hermetic-fixture-runner-nonzero");
        let nonzero_request = gateway_formal_backend_hermetic_fixture_runner_request(
            "hermetic-fixture-runner-nonzero",
            &nonzero_output_root,
        );
        let nonzero_output =
            materialize_gateway_formal_backend_hermetic_fixture_runner_output_bundle(
                &nonzero_output_root,
                &nonzero_interface,
                &nonzero_descriptor,
                &nonzero_descriptor_report_manifest,
                &nonzero_source_result_manifest,
                &nonzero_request,
            )
            .expect("nonzero fixture runner output materializes");
        assert_eq!(
            nonzero_output.manifest.solver_status,
            GatewayFormalBackendHermeticExecutionSolverStatus::FixtureProcessFailed
        );
        assert!(nonzero_output
            .manifest
            .process_exit_code_label
            .starts_with("exit_"));
        assert_ne!(nonzero_output.manifest.process_exit_code_label, "exit_0");
        assert!(!nonzero_output.manifest.creates_accepted_evidence);
        assert!(!nonzero_output.manifest.creates_level2_evidence);
        assert!(!nonzero_output.manifest.semantic_correctness_claimed);

        let (
            timeout_descriptor,
            timeout_descriptor_report_manifest,
            timeout_source_result_manifest,
            timeout_interface,
            timeout_descriptor_output_root,
            timeout_source_result_output_root,
        ) = gateway_formal_backend_hermetic_fixture_runner_fixture_with_argv(
            "hermetic-fixture-runner-timeout",
            vec![
                "--ignored".to_owned(),
                "--exact".to_owned(),
                "tests::phase314_fixture_child_sleep".to_owned(),
            ],
            None,
            None,
        );
        let timeout_output_root =
            temp_output_root("gateway-formal-backend-hermetic-fixture-runner-timeout");
        let timeout_request = gateway_formal_backend_hermetic_fixture_runner_request(
            "hermetic-fixture-runner-timeout",
            &timeout_output_root,
        );
        let timeout_output =
            materialize_gateway_formal_backend_hermetic_fixture_runner_output_bundle(
                &timeout_output_root,
                &timeout_interface,
                &timeout_descriptor,
                &timeout_descriptor_report_manifest,
                &timeout_source_result_manifest,
                &timeout_request,
            )
            .expect("timeout fixture runner output materializes");
        assert_eq!(
            timeout_output.manifest.solver_status,
            GatewayFormalBackendHermeticExecutionSolverStatus::FixtureProcessTimedOut
        );
        assert_eq!(timeout_output.manifest.process_exit_code_label, "timeout");
        assert!(timeout_output.manifest.timeout);
        assert!(!timeout_output.manifest.proof_artifact_created);
        assert!(!timeout_output.manifest.checker_transcript_created);
        assert!(!timeout_output.manifest.solver_certificate_created);

        cleanup_validation_summary_output_fixture(&nonzero_output_root);
        cleanup_validation_summary_output_fixture(&nonzero_descriptor_output_root);
        cleanup_validation_summary_output_fixture(&nonzero_source_result_output_root);
        cleanup_validation_summary_output_fixture(&timeout_output_root);
        cleanup_validation_summary_output_fixture(&timeout_descriptor_output_root);
        cleanup_validation_summary_output_fixture(&timeout_source_result_output_root);
    }

